import React, { useEffect, useMemo } from 'react';
import { useLoader } from '@react-three/fiber';
import { FBXLoader } from 'three/examples/jsm/loaders/FBXLoader';
import * as THREE from 'three';
import { MaterialSettings } from '../types';

interface FBXModelProps {
  url: string;
  settings: MaterialSettings;
}

const FBXModel: React.FC<FBXModelProps> = ({ url, settings }) => {
  const fbx = useLoader(FBXLoader, url);

  // Apply settings to all meshes in the model
  useEffect(() => {
    fbx.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;

        // Ensure standard material for PBR properties
        if (!(mesh.material instanceof THREE.MeshStandardMaterial)) {
          const oldMaterial = mesh.material as THREE.Material;
          mesh.material = new THREE.MeshStandardMaterial({
            color: (oldMaterial as any).color || new THREE.Color(settings.color),
            map: (oldMaterial as any).map || null,
          });
        }

        const mat = mesh.material as THREE.MeshStandardMaterial;
        mat.transparent = settings.transparent;
        mat.opacity = settings.opacity;
        mat.metalness = settings.metalness;
        mat.roughness = settings.roughness;
        mat.needsUpdate = true;
      }
    });
  }, [fbx, settings]);

  // Center and normalize the model size
  const processedModel = useMemo(() => {
    // Reset transformations before calculation
    fbx.position.set(0, 0, 0);
    fbx.scale.setScalar(1);
    fbx.updateMatrixWorld();

    const box = new THREE.Box3().setFromObject(fbx);
    const center = box.getCenter(new THREE.Vector3());
    const size = box.getSize(new THREE.Vector3());

    // Scale the model so its largest dimension is 4 units
    const maxDim = Math.max(size.x, size.y, size.z);
    const targetScale = 4 / (maxDim || 1);
    fbx.scale.setScalar(targetScale);

    // Recalculate center after scaling to ensure precision
    const scaledBox = new THREE.Box3().setFromObject(fbx);
    const scaledCenter = scaledBox.getCenter(new THREE.Vector3());

    // Move the group so the geometry center is at (0,0,0)
    fbx.position.x -= scaledCenter.x;
    fbx.position.y -= scaledCenter.y;
    fbx.position.z -= scaledCenter.z;

    return fbx;
  }, [fbx]);

  return <primitive object={processedModel} />;
};

export default FBXModel;

