import React, { useState, Suspense, useEffect } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, PerspectiveCamera, Environment, ContactShadows, Float, Html } from '@react-three/drei';
import Room from './components/Room';
import FBXModel from './components/FBXModel';
import UIOverlay from './components/UIOverlay';
import { MaterialSettings } from './types';

const App: React.FC = () => {
  const [modelUrl, setModelUrl] = useState<string | null>(null);
  const [materialSettings, setMaterialSettings] = useState<MaterialSettings>({
    opacity: 1.0,
    metalness: 0.8,
    roughness: 0.2,
    color: '#ffffff',
    transparent: false,
    textureUrl: null,
    metalnessUrl: null,
    roughnessUrl: null,
    opacityUrl: null
  });

  const handleFileUpload = (file: File) => {
    const url = URL.createObjectURL(file);
    setModelUrl(url);
    // Reset all textures when new model is loaded
    setMaterialSettings(prev => {
      if (prev.textureUrl) URL.revokeObjectURL(prev.textureUrl);
      if (prev.metalnessUrl) URL.revokeObjectURL(prev.metalnessUrl);
      if (prev.roughnessUrl) URL.revokeObjectURL(prev.roughnessUrl);
      if (prev.opacityUrl) URL.revokeObjectURL(prev.opacityUrl);
      return { 
        ...prev, 
        textureUrl: null, 
        metalnessUrl: null, 
        roughnessUrl: null, 
        opacityUrl: null 
      };
    });
  };

  const handleTextureUpload = (file: File, type: 'base' | 'metal' | 'rough' | 'opacity') => {
    const url = URL.createObjectURL(file);
    setMaterialSettings(prev => {
      const fieldMap = {
        base: 'textureUrl',
        metal: 'metalnessUrl',
        rough: 'roughnessUrl',
        opacity: 'opacityUrl'
      } as const;

      const field = fieldMap[type];
      const oldUrl = prev[field];
      if (oldUrl) URL.revokeObjectURL(oldUrl);

      return { ...prev, [field]: url };
    });
  };

  // Cleanup blob URLs on unmount or change
  useEffect(() => {
    return () => {
      if (modelUrl) URL.revokeObjectURL(modelUrl);
      if (materialSettings.textureUrl) URL.revokeObjectURL(materialSettings.textureUrl);
      if (materialSettings.metalnessUrl) URL.revokeObjectURL(materialSettings.metalnessUrl);
      if (materialSettings.roughnessUrl) URL.revokeObjectURL(materialSettings.roughnessUrl);
      if (materialSettings.opacityUrl) URL.revokeObjectURL(materialSettings.opacityUrl);
    };
  }, [modelUrl, materialSettings]);

  return (
    <div className="relative w-screen h-screen bg-slate-950 overflow-hidden">
      <Canvas shadows dpr={[1, 2]}>
        <PerspectiveCamera makeDefault position={[12, 6, 12]} fov={35} />

        <Suspense fallback={<Html center><div className="text-white animate-pulse font-mono tracking-widest bg-slate-900/50 p-4 rounded-lg backdrop-blur-md border border-slate-700">INITIALIZING ENGINE...</div></Html>}>
          <ambientLight intensity={0.6} />
          <spotLight position={[15, 20, 15]} angle={0.3} penumbra={1} intensity={3} castShadow />
          <pointLight position={[-10, 8, -5]} intensity={2} color="#3b82f6" />
          <pointLight position={[10, 2, 10]} intensity={1} color="#6366f1" />

          {/* Using 'city' environment for high-contrast reflections on metal */}
          <Environment preset="city" background={false} />

          <Room />

          <group position={[0, 0, 0]}>
            <Float 
              speed={1.5} 
              rotationIntensity={0.2} 
              floatIntensity={0.3}
              floatingRange={[-0.2, 0.2]}
            >
              {modelUrl ? (
                <FBXModel url={modelUrl} settings={materialSettings} />
              ) : (
                <mesh castShadow receiveShadow>
                  <boxGeometry args={[2, 2, 2]} />
                  <meshStandardMaterial 
                     color="#1e293b" 
                     wireframe 
                     transparent 
                     opacity={0.4} 
                  />
                  <Html position={[0, -2, 0]} center>
                    <div className="text-blue-400 text-xs font-mono uppercase tracking-widest whitespace-nowrap bg-slate-900/80 px-4 py-2 rounded-full border border-blue-500/30">
                      DROP MODEL IN CENTER
                    </div>
                  </Html>
                </mesh>
              )}
            </Float>

            <ContactShadows 
              position={[0, -4.9, 0]} 
              opacity={0.6} 
              scale={15} 
              blur={2.5} 
              far={10} 
              resolution={512} 
              color="#000000" 
            />
          </group>

        </Suspense>

        <OrbitControls 
          enableDamping 
          dampingFactor={0.07} 
          minDistance={3} 
          maxDistance={25}
          target={[0, 0, 0]} 
        />
      </Canvas>

      <UIOverlay 
        settings={materialSettings} 
        setSettings={setMaterialSettings} 
        onFileUpload={handleFileUpload}
        onTextureUpload={handleTextureUpload}
      />

      <div className="absolute top-0 right-0 w-1/3 h-1/3 bg-blue-600/5 blur-[120px] pointer-events-none rounded-full"></div>
      <div className="absolute bottom-0 left-0 w-1/4 h-1/4 bg-indigo-600/5 blur-[120px] pointer-events-none rounded-full"></div>

      <div className="absolute top-4 right-4 pointer-events-none text-[10px] text-slate-500 font-mono text-right space-y-1">
        <div>CORE_SYSTEM: STABLE</div>
        <div>PBR_RENDERER: ACTIVE</div>
        <div>ENV_MAP: CITY_REFLECTIONS</div>
        <div>MAP_CHANNELS: {
          [materialSettings.textureUrl, materialSettings.metalnessUrl, materialSettings.roughnessUrl, materialSettings.opacityUrl].filter(Boolean).length
        }/4</div>
      </div>
    </div>
  );
};

export default App;

import React, { useEffect, useMemo } from 'react';
import { useLoader } from '@react-three/fiber';
import { FBXLoader } from 'three/examples/jsm/loaders/FBXLoader';
import * as THREE from 'three';
import { MaterialSettings } from '../types';

interface FBXModelProps {
  url: string;
  settings: MaterialSettings;
}

const FBXModel: React.FC<FBXModelProps> = ({ url, settings }) => {
  const fbx = useLoader(FBXLoader, url);

  // Memoized texture loading
  const textures = useMemo(() => {
    const loader = new THREE.TextureLoader();
    const loadTex = (url: string | null | undefined, isColor = false) => {
      if (!url) return null;
      const tex = loader.load(url);
      if (isColor) tex.colorSpace = THREE.SRGBColorSpace;
      tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
      return tex;
    };

    return {
      map: loadTex(settings.textureUrl, true),
      metalnessMap: loadTex(settings.metalnessUrl),
      roughnessMap: loadTex(settings.roughnessUrl),
      alphaMap: loadTex(settings.opacityUrl)
    };
  }, [settings.textureUrl, settings.metalnessUrl, settings.roughnessUrl, settings.opacityUrl]);

  // Apply settings to all meshes in the model
  useEffect(() => {
    fbx.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;
        const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];

        const updatedMaterials = materials.map((mat) => {
          let targetMat = mat;

          // Convert to Standard Material to support PBR if it's a legacy material (Phong/Lambert)
          if (!(mat instanceof THREE.MeshStandardMaterial)) {
            const newMat = new THREE.MeshStandardMaterial();
            // Preserve existing textures and colors
            if ('color' in mat) newMat.color.copy((mat as any).color);
            if ('map' in mat) newMat.map = (mat as any).map;
            if ('normalMap' in mat) newMat.normalMap = (mat as any).normalMap;
            if ('roughnessMap' in mat) newMat.roughnessMap = (mat as any).roughnessMap;
            if ('metalnessMap' in mat) newMat.metalnessMap = (mat as any).metalnessMap;
            if ('emissive' in mat) newMat.emissive.copy((mat as any).emissive);
            if ('emissiveMap' in mat) newMat.emissiveMap = (mat as any).emissiveMap;

            // Check for vertex colors (common in game models)
            if (mesh.geometry.attributes.color) {
              newMat.vertexColors = true;
            }
            targetMat = newMat;
          }

          const standardMat = targetMat as THREE.MeshStandardMaterial;

          // Apply custom uploaded maps if they exist
          if (textures.map) standardMat.map = textures.map;
          if (textures.metalnessMap) standardMat.metalnessMap = textures.metalnessMap;
          if (textures.roughnessMap) standardMat.roughnessMap = textures.roughnessMap;
          if (textures.alphaMap) standardMat.alphaMap = textures.alphaMap;

          // Transparency handling - Crucial for eyes/hair
          const isTransparent = settings.transparent || settings.opacity < 1 || !!textures.alphaMap || !!standardMat.map?.format;
          standardMat.transparent = isTransparent;
          standardMat.opacity = settings.opacity;

          // Use alphaTest to prevent depth sorting issues often found with character eyes
          standardMat.alphaTest = 0.5;

          // PBR Properties - boost intensity to match video's "shiny" look
          standardMat.metalness = settings.metalness;
          standardMat.roughness = settings.roughness;

          // Environment intensity boost for reflections
          standardMat.envMapIntensity = 2.0; 

          // Ensure internal parts (like the back of eyes or inner mouth) are visible
          standardMat.side = THREE.DoubleSide;

          // Color tinting - if white (#ffffff), it stays original
          standardMat.color.set(settings.color);

          standardMat.needsUpdate = true;
          return standardMat;
        });

        mesh.material = Array.isArray(mesh.material) ? updatedMaterials : updatedMaterials[0];
        mesh.castShadow = true;
        mesh.receiveShadow = true;
      }
    });
  }, [fbx, settings, textures]);

  const processedModel = useMemo(() => {
    // Standardize model positioning and scale
    fbx.position.set(0, 0, 0);
    fbx.scale.setScalar(1);
    fbx.updateMatrixWorld();

    const box = new THREE.Box3().setFromObject(fbx);
    const center = box.getCenter(new THREE.Vector3());
    const size = box.getSize(new THREE.Vector3());

    // Scale to fit viewing volume
    const maxDim = Math.max(size.x, size.y, size.z);
    const targetScale = 6 / (maxDim || 1);
    fbx.scale.setScalar(targetScale);

    const scaledBox = new THREE.Box3().setFromObject(fbx);
    const scaledCenter = scaledBox.getCenter(new THREE.Vector3());

    // Center it horizontally, but keep it on the ground visually
    fbx.position.x -= scaledCenter.x;
    fbx.position.y -= scaledCenter.y;
    fbx.position.z -= scaledCenter.z;

    return fbx;
  }, [fbx]);

  return <primitive object={processedModel} />;
};

export default FBXModel;

