import React, { useState, Suspense, useEffect } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, PerspectiveCamera, Environment, ContactShadows, Float, Html } from '@react-three/drei';
import Room from './components/Room';
import FBXModel from './components/FBXModel';
import UIOverlay from './components/UIOverlay';
import { MaterialSettings } from './types';

const App: React.FC = () => {
  const [modelUrl, setModelUrl] = useState<string | null>(null);
  const [materialSettings, setMaterialSettings] = useState<MaterialSettings>({
    opacity: 1.0,
    metalness: 0.6,
    roughness: 0.4,
    color: '#ffffff',
    transparent: false,
    textureUrl: null,
    metalnessUrl: null,
    roughnessUrl: null,
    opacityUrl: null
  });

  const handleFileUpload = (file: File) => {
    const url = URL.createObjectURL(file);
    setModelUrl(url);
    // Reset all textures when new model is loaded to avoid ghosting from previous model
    setMaterialSettings(prev => {
      if (prev.textureUrl) URL.revokeObjectURL(prev.textureUrl);
      if (prev.metalnessUrl) URL.revokeObjectURL(prev.metalnessUrl);
      if (prev.roughnessUrl) URL.revokeObjectURL(prev.roughnessUrl);
      if (prev.opacityUrl) URL.revokeObjectURL(prev.opacityUrl);
      return { 
        ...prev, 
        textureUrl: null, 
        metalnessUrl: null, 
        roughnessUrl: null, 
        opacityUrl: null,
        metalness: 0.6,
        roughness: 0.4,
        opacity: 1.0,
        color: '#ffffff'
      };
    });
  };

  const handleTextureUpload = (file: File, type: 'base' | 'metal' | 'rough' | 'opacity') => {
    const url = URL.createObjectURL(file);
    setMaterialSettings(prev => {
      const fieldMap = {
        base: 'textureUrl',
        metal: 'metalnessUrl',
        rough: 'roughnessUrl',
        opacity: 'opacityUrl'
      } as const;

      const field = fieldMap[type];
      const oldUrl = prev[field];
      if (oldUrl) URL.revokeObjectURL(oldUrl);

      // Auto-bump multipliers to 1.0 when a map is provided to ensure full visibility of the map's values
      let newMetalness = prev.metalness;
      let newRoughness = prev.roughness;
      let newOpacity = prev.opacity;

      if (type === 'metal') newMetalness = 1.0;
      if (type === 'rough') newRoughness = 1.0;
      if (type === 'opacity') newOpacity = 1.0;

      return { 
        ...prev, 
        [field]: url,
        metalness: newMetalness,
        roughness: newRoughness,
        opacity: newOpacity
      };
    });
  };

  // Cleanup blob URLs on unmount or change
  useEffect(() => {
    return () => {
      if (modelUrl) URL.revokeObjectURL(modelUrl);
      if (materialSettings.textureUrl) URL.revokeObjectURL(materialSettings.textureUrl);
      if (materialSettings.metalnessUrl) URL.revokeObjectURL(materialSettings.metalnessUrl);
      if (materialSettings.roughnessUrl) URL.revokeObjectURL(materialSettings.roughnessUrl);
      if (materialSettings.opacityUrl) URL.revokeObjectURL(materialSettings.opacityUrl);
    };
  }, [modelUrl, materialSettings]);

  return (
    <div className="relative w-screen h-screen bg-slate-950 overflow-hidden">
      <Canvas shadows dpr={[1, 2]} gl={{ antialias: true, preserveDrawingBuffer: true, powerPreference: "high-performance" }}>
        <PerspectiveCamera makeDefault position={[10, 5, 10]} fov={35} />

        <Suspense fallback={<Html center><div className="text-white animate-pulse font-mono tracking-widest bg-slate-900/50 p-6 rounded-2xl backdrop-blur-xl border border-slate-700 shadow-2xl flex flex-col items-center gap-4 text-center">
          <div className="w-8 h-8 border-4 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
          INITIALIZING ENGINE...
        </div></Html>}>
          <ambientLight intensity={0.5} />

          {/* Main Key Light */}
          <spotLight 
            position={[10, 20, 10]} 
            angle={0.15} 
            penumbra={1} 
            intensity={2.5} 
            castShadow 
            shadow-mapSize={[1024, 1024]}
            shadow-bias={-0.0001}
          />

          {/* Fill lights for specular highlights */}
          <pointLight position={[-8, 10, -5]} intensity={3} color="#ffffff" />
          <pointLight position={[8, 5, 5]} intensity={2} color="#ffffff" />

          <Environment preset="warehouse" background={false} blur={0.8} />

          <Room />

          <group position={[0, 0, 0]}>
            <Float 
              speed={1.2} 
              rotationIntensity={0.1} 
              floatIntensity={0.2}
              floatingRange={[-0.1, 0.1]}
            >
              {modelUrl ? (
                <FBXModel url={modelUrl} settings={materialSettings} />
              ) : (
                <mesh castShadow receiveShadow>
                  <boxGeometry args={[2, 2, 2]} />
                  <meshStandardMaterial 
                     color="#1e293b" 
                     wireframe 
                     transparent 
                     opacity={0.4} 
                  />
                  <Html position={[0, -2.5, 0]} center>
                    <div className="text-blue-400 text-xs font-mono uppercase tracking-[0.3em] whitespace-nowrap bg-slate-900/80 px-6 py-3 rounded-full border border-blue-500/30 backdrop-blur-sm animate-pulse">
                      WAITING FOR FBX
                    </div>
                  </Html>
                </mesh>
              )}
            </Float>

            <ContactShadows 
              position={[0, -4.9, 0]} 
              opacity={0.7} 
              scale={20} 
              blur={2} 
              far={10} 
              resolution={1024} 
              color="#000000" 
            />
          </group>

        </Suspense>

        <OrbitControls 
          enableDamping 
          dampingFactor={0.05} 
          minDistance={2} 
          maxDistance={25}
          target={[0, 0, 0]} 
        />
      </Canvas>

      <UIOverlay 
        settings={materialSettings} 
        setSettings={setMaterialSettings} 
        onFileUpload={handleFileUpload}
        onTextureUpload={handleTextureUpload}
      />

      <div className="absolute top-6 right-6 pointer-events-none text-[11px] text-slate-500 font-mono text-right space-y-1 bg-slate-900/40 p-3 rounded-lg backdrop-blur-sm border border-slate-800">
        <div className="text-blue-400 font-bold mb-1 uppercase tracking-tighter">PBR Status</div>
        <div>DIFFUSE: {materialSettings.textureUrl ? 'OK' : 'NONE'}</div>
        <div>METAL: {materialSettings.metalnessUrl ? 'OK' : 'NONE'}</div>
        <div>ROUGH: {materialSettings.roughnessUrl ? 'OK' : 'NONE'}</div>
        <div>ALPHA: {materialSettings.opacityUrl ? 'OK' : 'NONE'}</div>
      </div>
    </div>
  );
};

export default App;

import React, { useEffect, useMemo, useState } from 'react';
import { useLoader, useThree } from '@react-three/fiber';
import { FBXLoader } from 'three/examples/jsm/loaders/FBXLoader';
import * as THREE from 'three';
import { MaterialSettings } from '../types';

interface FBXModelProps {
  url: string;
  settings: MaterialSettings;
}

const FBXModel: React.FC<FBXModelProps> = ({ url, settings }) => {
  const fbx = useLoader(FBXLoader, url);
  const [loadedTextures, setLoadedTextures] = useState<{ [key: string]: THREE.Texture }>({});

  // Effect to load textures asynchronously and update state when ready
  useEffect(() => {
    const loader = new THREE.TextureLoader();
    const mapKeys = [
      { key: 'map', url: settings.textureUrl, isColor: true },
      { key: 'metalnessMap', url: settings.metalnessUrl, isColor: false },
      { key: 'roughnessMap', url: settings.roughnessUrl, isColor: false },
      { key: 'alphaMap', url: settings.opacityUrl, isColor: false },
    ];

    mapKeys.forEach(({ key, url, isColor }) => {
      if (url) {
        loader.load(url, (tex) => {
          if (isColor) tex.colorSpace = THREE.SRGBColorSpace;
          tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
          tex.needsUpdate = true;
          setLoadedTextures(prev => ({ ...prev, [key]: tex }));
        });
      } else {
        setLoadedTextures(prev => {
          const next = { ...prev };
          delete next[key];
          return next;
        });
      }
    });
  }, [settings.textureUrl, settings.metalnessUrl, settings.roughnessUrl, settings.opacityUrl]);

  // Apply settings to all meshes in the model
  useEffect(() => {
    fbx.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;
        const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];

        const updatedMaterials = materials.map((mat) => {
          // Store original transparency traits before converting
          const originalTransparent = (mat as any).transparent || false;
          const originalOpacity = (mat as any).opacity !== undefined ? (mat as any).opacity : 1;
          const originalAlphaTest = (mat as any).alphaTest || 0;
          const originalMap = (mat as any).map;

          let standardMat: THREE.MeshStandardMaterial;

          // Convert to Standard Material if it's not already, preserving original attributes
          if (!(mat instanceof THREE.MeshStandardMaterial)) {
            standardMat = new THREE.MeshStandardMaterial();
            if ('color' in mat) standardMat.color.copy((mat as any).color);
            if (originalMap) standardMat.map = originalMap;
            if ('normalMap' in mat) standardMat.normalMap = (mat as any).normalMap;
            if ('emissive' in mat) standardMat.emissive.copy((mat as any).emissive);

            if (mesh.geometry.attributes.color) {
              standardMat.vertexColors = true;
            }
          } else {
            standardMat = mat;
          }

          // Apply custom textures from state if they exist, otherwise keep originals
          if (loadedTextures.map) standardMat.map = loadedTextures.map;
          if (loadedTextures.metalnessMap) standardMat.metalnessMap = loadedTextures.metalnessMap;
          if (loadedTextures.roughnessMap) standardMat.roughnessMap = loadedTextures.roughnessMap;
          if (loadedTextures.alphaMap) standardMat.alphaMap = loadedTextures.alphaMap;

          // Crucial: Determine transparency
          // 1. If user uploaded alpha map
          // 2. If original material was transparent
          // 3. If original opacity was less than 1
          // 4. If current map (original or uploaded) might have alpha
          const hasUploadedAlpha = !!loadedTextures.alphaMap;
          const isActuallyTransparent = hasUploadedAlpha || originalTransparent || originalOpacity < 1 || settings.opacity < 1;

          standardMat.transparent = isActuallyTransparent;

          // Use original opacity as base, multiply by settings.opacity
          // If settings.opacity is 1 (default), it respects original.
          standardMat.opacity = originalOpacity * settings.opacity;

          // Alpha Test is vital for FBX models with PNG "cutout" textures (e.g. foliage, fences, decals)
          standardMat.alphaTest = hasUploadedAlpha ? 0.05 : (originalAlphaTest > 0 ? originalAlphaTest : 0.05);

          standardMat.metalness = settings.metalness;
          standardMat.roughness = settings.roughness;

          // Ensure side is DoubleSide so we see transparency from both sides
          standardMat.side = THREE.DoubleSide;
          standardMat.envMapIntensity = 1.5;

          if (settings.color !== '#ffffff') {
            standardMat.color.set(settings.color);
          }

          standardMat.needsUpdate = true;
          return standardMat;
        });

        mesh.material = Array.isArray(mesh.material) ? updatedMaterials : updatedMaterials[0];
        mesh.castShadow = true;
        mesh.receiveShadow = true;
      }
    });
  }, [fbx, settings, loadedTextures]);

  const processedModel = useMemo(() => {
    fbx.position.set(0, 0, 0);
    fbx.scale.setScalar(1);
    fbx.updateMatrixWorld();

    const box = new THREE.Box3().setFromObject(fbx);
    const size = box.getSize(new THREE.Vector3());

    const maxDim = Math.max(size.x, size.y, size.z);
    const targetScale = 6 / (maxDim || 1);
    fbx.scale.setScalar(targetScale);

    const scaledBox = new THREE.Box3().setFromObject(fbx);
    const scaledCenter = scaledBox.getCenter(new THREE.Vector3());

    fbx.position.x -= scaledCenter.x;
    fbx.position.y -= scaledCenter.y;
    fbx.position.z -= scaledCenter.z;

    return fbx;
  }, [fbx]);

  return <primitive object={processedModel} />;
};

