      }
    });
  }, [settings.textureUrl, settings.metalnessUrl, settings.roughnessUrl, settings.transparencyUrl]);

  // Apply settings to all meshes in the model
  useEffect(() => {
    fbx.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;
        const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];

        const updatedMaterials = materials.map((mat) => {
          // Initialize userData storage if it doesn't exist to prevent destructive updates
          if (!mat.userData.originalProps) {
            mat.userData.originalProps = {
              transparent: mat.transparent,
              opacity: mat.opacity,
              alphaTest: mat.alphaTest,
              color: mat instanceof THREE.MeshStandardMaterial ? mat.color.clone() : new THREE.Color(0xffffff)
            };
          }

          const { originalTransparent, originalOpacity, originalAlphaTest } = {
            originalTransparent: mat.userData.originalProps.transparent,
            originalOpacity: mat.userData.originalProps.opacity,
            originalAlphaTest: mat.userData.originalProps.alphaTest
          };

          const originalMap = (mat as any).map;

          let standardMat: THREE.MeshStandardMaterial;

          // Convert to Standard Material if it's not already
          if (!(mat instanceof THREE.MeshStandardMaterial)) {
            standardMat = new THREE.MeshStandardMaterial();
            if ('color' in mat) standardMat.color.copy((mat as any).color);
            if (originalMap) standardMat.map = originalMap;
            if ('normalMap' in mat) standardMat.normalMap = (mat as any).normalMap;
            if ('emissive' in mat) standardMat.emissive.copy((mat as any).emissive);
            if (mesh.geometry.attributes.color) standardMat.vertexColors = true;
            // Transfer the userData so we keep tracking original props
            standardMat.userData = mat.userData;
          } else {
            standardMat = mat;
          }

          // Apply texture overrides
          if (loadedTextures.map) standardMat.map = loadedTextures.map;
          if (loadedTextures.metalnessMap) standardMat.metalnessMap = loadedTextures.metalnessMap;
          if (loadedTextures.roughnessMap) standardMat.roughnessMap = loadedTextures.roughnessMap;
          if (loadedTextures.alphaMap) standardMat.alphaMap = loadedTextures.alphaMap;

          // Determine transparency
          const hasUploadedAlpha = !!loadedTextures.alphaMap;
          // Logic: Force transparency if settings.transparent is true OR if map/original has it
          const shouldBeTransparent = settings.transparent || hasUploadedAlpha || originalTransparent || originalOpacity < 1 || settings.opacity < 1;

          standardMat.transparent = shouldBeTransparent;

          // Multiply stored original opacity by the multiplier from settings
          // This prevents the "vanishing" effect where 0.4 * 0.4 * 0.4... leads to 0
          standardMat.opacity = originalOpacity * settings.opacity;

          // Use alphaTest to handle cutouts properly
          standardMat.alphaTest = hasUploadedAlpha ? 0.05 : (originalAlphaTest > 0 ? originalAlphaTest : 0.05);

          // Physical properties
          standardMat.metalness = settings.metalness;
          standardMat.roughness = settings.roughness;
          standardMat.side = THREE.DoubleSide;
          standardMat.envMapIntensity = 1.5;

          // Color override
          if (settings.color !== '#ffffff') {
            standardMat.color.set(settings.color);
          } else {
            standardMat.color.copy(mat.userData.originalProps.color);
          }

          standardMat.needsUpdate = true;
          return standardMat;
        });

        mesh.material = Array.isArray(mesh.material) ? updatedMaterials : updatedMaterials[0];
        mesh.castShadow = true;
        mesh.receiveShadow = true;
      }
    });
  }, [fbx, settings, loadedTextures]);

  const processedModel = useMemo(() => {
    fbx.position.set(0, 0, 0);
    fbx.scale.setScalar(1);
    fbx.updateMatrixWorld();

    const box = new THREE.Box3().setFromObject(fbx);
    const size = box.getSize(new THREE.Vector3());
    const maxDim = Math.max(size.x, size.y, size.z);
    const targetScale = 6 / (maxDim || 1);
    fbx.scale.setScalar(targetScale);

    const scaledBox = new THREE.Box3().setFromObject(fbx);
    const scaledCenter = scaledBox.getCenter(new THREE.Vector3());
    fbx.position.x -= scaledCenter.x;
    fbx.position.y -= scaledCenter.y;
    fbx.position.z -= scaledCenter.z;

    return fbx;
  }, [fbx]);

  return <primitive object={processedModel} />;
};

export default FBXModel;

export interface MaterialSettings {
