import React, { useState, Suspense, useEffect } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, PerspectiveCamera, Environment, ContactShadows, Float, Html } from '@react-three/drei';
import Room from './components/Room';
import FBXModel from './components/FBXModel';
import UIOverlay from './components/UIOverlay';
import { MaterialSettings } from './types';

const App: React.FC = () => {
  const [modelUrl, setModelUrl] = useState<string | null>(null);
  const [materialSettings, setMaterialSettings] = useState<MaterialSettings>({
    opacity: 1.0,
    metalness: 0.6,
    roughness: 0.4,
    color: '#ffffff',
    transparent: false,
    textureUrl: null,
    allDiffuseMaps: [],
    metalnessUrl: null,
    roughnessUrl: null,
    transparencyUrl: null
  });

  const handleFileUpload = (file: File) => {
    const url = URL.createObjectURL(file);
    setModelUrl(url);

    // Clean up old URLs
    materialSettings.allDiffuseMaps.forEach(url => URL.revokeObjectURL(url));
    if (materialSettings.metalnessUrl) URL.revokeObjectURL(materialSettings.metalnessUrl);
    if (materialSettings.roughnessUrl) URL.revokeObjectURL(materialSettings.roughnessUrl);
    if (materialSettings.transparencyUrl) URL.revokeObjectURL(materialSettings.transparencyUrl);

    setMaterialSettings({ 
      opacity: 1.0,
      metalness: 0.6,
      roughness: 0.4,
      color: '#ffffff',
      transparent: false,
      textureUrl: null,
      allDiffuseMaps: [],
      metalnessUrl: null,
      roughnessUrl: null,
      transparencyUrl: null
    });
  };

  const handleTextureUpload = (file: File, type: 'base' | 'metal' | 'rough' | 'transparency') => {
    const url = URL.createObjectURL(file);
    setMaterialSettings(prev => {
      if (type === 'base') {
        return {
          ...prev,
          allDiffuseMaps: [...prev.allDiffuseMaps, url],
          textureUrl: url // Set newly uploaded as active
        };
      }

      const fieldMap = {
        metal: 'metalnessUrl',
        rough: 'roughnessUrl',
        transparency: 'transparencyUrl'
      } as const;

      const field = fieldMap[type as keyof typeof fieldMap];
      const oldUrl = prev[field];
      if (oldUrl) URL.revokeObjectURL(oldUrl);

      return { 
        ...prev, 
        [field]: url,
        metalness: type === 'metal' ? 1.0 : prev.metalness,
        roughness: type === 'rough' ? 1.0 : prev.roughness,
        opacity: type === 'transparency' ? 1.0 : prev.opacity
      };
    });
  };

  const selectDiffuseMap = (url: string) => {
    setMaterialSettings(prev => ({ ...prev, textureUrl: url }));
  };

  useEffect(() => {
    return () => {
      if (modelUrl) URL.revokeObjectURL(modelUrl);
      materialSettings.allDiffuseMaps.forEach(url => URL.revokeObjectURL(url));
      if (materialSettings.metalnessUrl) URL.revokeObjectURL(materialSettings.metalnessUrl);
      if (materialSettings.roughnessUrl) URL.revokeObjectURL(materialSettings.roughnessUrl);
      if (materialSettings.transparencyUrl) URL.revokeObjectURL(materialSettings.transparencyUrl);
    };
  }, []);

  return (
    <div className="relative w-screen h-screen bg-slate-950 overflow-hidden">
      <Canvas shadows dpr={[1, 2]} gl={{ antialias: true, preserveDrawingBuffer: true, powerPreference: "high-performance" }}>
        <PerspectiveCamera makeDefault position={[10, 5, 10]} fov={35} />

        <Suspense fallback={<Html center><div className="text-white animate-pulse font-mono tracking-widest bg-slate-900/50 p-6 rounded-2xl backdrop-blur-xl border border-slate-700 shadow-2xl flex flex-col items-center gap-4 text-center">
          <div className="w-8 h-8 border-4 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
          LOADING ENGINE...
        </div></Html>}>
          <ambientLight intensity={0.5} />
          <spotLight 
            position={[10, 20, 10]} 
            angle={0.15} 
            penumbra={1} 
            intensity={2.5} 
            castShadow 
            shadow-mapSize={[1024, 1024]}
            shadow-bias={-0.0001}
          />
          <pointLight position={[-8, 10, -5]} intensity={3} color="#ffffff" />
          <pointLight position={[8, 5, 5]} intensity={2} color="#ffffff" />
          <Environment preset="warehouse" background={false} blur={0.8} />

          <Room />

          <group position={[0, 0, 0]}>
            <Float 
              speed={1.2} 
              rotationIntensity={0.1} 
              floatIntensity={0.2}
              floatingRange={[-0.1, 0.1]}
            >
              {modelUrl ? (
                <FBXModel url={modelUrl} settings={materialSettings} />
              ) : (
                <mesh castShadow receiveShadow>
                  <boxGeometry args={[2, 2, 2]} />
                  <meshStandardMaterial 
                     color="#1e293b" 
                     wireframe 
                     transparent 
                     opacity={0.4} 
                  />
                  <Html position={[0, -2.5, 0]} center>
                    <div className="text-blue-400 text-xs font-mono uppercase tracking-[0.3em] whitespace-nowrap bg-slate-900/80 px-6 py-3 rounded-full border border-blue-500/30 backdrop-blur-sm animate-pulse">
                      WAITING FOR FBX
                    </div>
                  </Html>
                </mesh>
              )}
            </Float>
            <ContactShadows position={[0, -4.9, 0]} opacity={0.7} scale={20} blur={2} far={10} resolution={1024} color="#000000" />
          </group>
        </Suspense>

        <OrbitControls enableDamping dampingFactor={0.05} minDistance={2} maxDistance={25} target={[0, 0, 0]} />
      </Canvas>

      <UIOverlay 
        settings={materialSettings} 
        setSettings={setMaterialSettings} 
        onFileUpload={handleFileUpload}
        onTextureUpload={handleTextureUpload}
        onSelectDiffuse={selectDiffuseMap}
      />

      <div className="absolute top-6 right-6 pointer-events-none text-[11px] text-slate-500 font-mono text-right space-y-1 bg-slate-900/40 p-3 rounded-lg backdrop-blur-sm border border-slate-800">
        <div className="text-blue-400 font-bold mb-1 uppercase tracking-tighter">PBR Status</div>
        <div>DIFFUSE MAPS: {materialSettings.allDiffuseMaps.length}</div>
        <div>METAL: {materialSettings.metalnessUrl ? 'OK' : 'NONE'}</div>
        <div>ROUGH: {materialSettings.roughnessUrl ? 'OK' : 'NONE'}</div>
        <div>TRANS: {materialSettings.transparencyUrl ? 'OK' : 'NONE'}</div>
      </div>
    </div>
  );
};

export default App;

