import React, { useEffect, useMemo, useState } from 'react';
import { useLoader } from '@react-three/fiber';
import { FBXLoader } from 'three/examples/jsm/loaders/FBXLoader';
import * as THREE from 'three';
import { MaterialSettings } from '../types';

interface FBXModelProps {
  url: string;
  settings: MaterialSettings;
}

const FBXModel: React.FC<FBXModelProps> = ({ url, settings }) => {
  const fbx = useLoader(FBXLoader, url);
  const [loadedTextures, setLoadedTextures] = useState<{ [key: string]: THREE.Texture }>({});

  // Effect to load textures asynchronously
  useEffect(() => {
    const loader = new THREE.TextureLoader();
    const mapKeys = [
      { key: 'map', url: settings.textureUrl, isColor: true },
      { key: 'metalnessMap', url: settings.metalnessUrl, isColor: false },
      { key: 'roughnessMap', url: settings.roughnessUrl, isColor: false },
      { key: 'alphaMap', url: settings.transparencyUrl, isColor: false },
    ];

    mapKeys.forEach(({ key, url, isColor }) => {
      if (url) {
        loader.load(url, (tex) => {
          if (isColor) tex.colorSpace = THREE.SRGBColorSpace;
          tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
          tex.needsUpdate = true;
          setLoadedTextures(prev => ({ ...prev, [key]: tex }));
        });
      } else {
        setLoadedTextures(prev => {
          const next = { ...prev };
          delete next[key];
          return next;
        });
      }
    });
  }, [settings.textureUrl, settings.metalnessUrl, settings.roughnessUrl, settings.transparencyUrl]);

  // Apply settings to all meshes in the model
  useEffect(() => {
    fbx.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;
        const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];

        const updatedMaterials = materials.map((mat) => {
          // Initialize userData storage if it doesn't exist
          if (!mat.userData.originalProps) {
            mat.userData.originalProps = {
              transparent: mat.transparent,
              opacity: mat.opacity !== undefined ? mat.opacity : 1,
              alphaTest: mat.alphaTest || 0,
              color: mat instanceof THREE.MeshStandardMaterial ? mat.color.clone() : 
                     ('color' in mat ? (mat as any).color.clone() : new THREE.Color(0xffffff))
            };
          }

          const { originalTransparent, originalOpacity, originalAlphaTest } = mat.userData.originalProps;

          // Always ensure we are working with a MeshStandardMaterial for PBR
          let standardMat: THREE.MeshStandardMaterial;

          if (!(mat instanceof THREE.MeshStandardMaterial)) {
            standardMat = new THREE.MeshStandardMaterial();
            // Copy properties from old material
            if ('color' in mat) standardMat.color.copy((mat as any).color);
            if ('map' in mat) standardMat.map = (mat as any).map;
            if ('normalMap' in mat) standardMat.normalMap = (mat as any).normalMap;
            if ('emissive' in mat) standardMat.emissive.copy((mat as any).emissive);
            if (mesh.geometry.attributes.color) standardMat.vertexColors = true;
            standardMat.userData = mat.userData; // Keep the original props reference
          } else {
            standardMat = mat;
          }

          // Apply override textures from props
          if (loadedTextures.map) standardMat.map = loadedTextures.map;
          if (loadedTextures.metalnessMap) standardMat.metalnessMap = loadedTextures.metalnessMap;
          if (loadedTextures.roughnessMap) standardMat.roughnessMap = loadedTextures.roughnessMap;
          if (loadedTextures.alphaMap) standardMat.alphaMap = loadedTextures.alphaMap;

          // DETERMINING TRANSPARENCY
          // Use the global checkbox (settings.transparent) or if a specific transparency map is provided
          const hasUploadedAlphaMap = !!loadedTextures.alphaMap;
          const isTransparentActive = settings.transparent || settings.opacity < 1.0 || hasUploadedAlphaMap || originalTransparent;

          standardMat.transparent = isTransparentActive;

          // IMPORTANT: opacity calculation must be based on original stored opacity, not the current one
          // to prevent cumulative multiplication leading to 0 (disappearing model)
          standardMat.opacity = originalOpacity * settings.opacity;

          // DepthWrite is critical for transparency. If transparent, we usually turn depthWrite off 
          // or handle it carefully to avoid sorting issues.
          standardMat.depthWrite = !isTransparentActive || standardMat.opacity >= 1.0;

          // Alpha test helps with "cutout" textures
          standardMat.alphaTest = hasUploadedAlphaMap ? 0.05 : (originalAlphaTest > 0 ? originalAlphaTest : 0.01);

          // PBR Factors
          standardMat.metalness = settings.metalness;
          standardMat.roughness = settings.roughness;
          standardMat.side = THREE.DoubleSide; // Render both sides for better transparency look
          standardMat.envMapIntensity = 1.5;

          // Color Tints
          if (settings.color !== '#ffffff') {
            standardMat.color.set(settings.color);
          } else {
            standardMat.color.copy(mat.userData.originalProps.color);
          }

          // Force Three.js to re-evaluate the material properties
          standardMat.needsUpdate = true;

          return standardMat;
        });

        mesh.material = Array.isArray(mesh.material) ? updatedMaterials : updatedMaterials[0];
        mesh.castShadow = true;
        mesh.receiveShadow = true;
      }
    });
  }, [fbx, settings, loadedTextures]);

  const processedModel = useMemo(() => {
    fbx.position.set(0, 0, 0);
    fbx.scale.setScalar(1);
    fbx.updateMatrixWorld();

    const box = new THREE.Box3().setFromObject(fbx);
    const size = box.getSize(new THREE.Vector3());
    const maxDim = Math.max(size.x, size.y, size.z);

    // Auto-scale to a reasonable size
    const targetScale = 6 / (maxDim || 1);
    fbx.scale.setScalar(targetScale);

    // Center the model
    const scaledBox = new THREE.Box3().setFromObject(fbx);
    const scaledCenter = scaledBox.getCenter(new THREE.Vector3());
    fbx.position.x -= scaledCenter.x;
    fbx.position.y -= scaledCenter.y;
    fbx.position.z -= scaledCenter.z;

    return fbx;
  }, [fbx, url]); // Re-process only when FBX or URL changes

  return <primitive object={processedModel} />;
};

export default FBXModel;

