  useEffect(() => {
    fbx.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;
        const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];

        const updatedMaterials = materials.map((mat) => {
          // שמירת מאפיינים מקוריים ב-userData כדי למנוע איבוד נתונים בחישובים חוזרים
          if (!mat.userData.originalProps) {
            mat.userData.originalProps = {
              transparent: mat.transparent,
              opacity: (mat.opacity !== undefined && mat.opacity > 0) ? mat.opacity : 1,
              alphaTest: mat.alphaTest || 0,
              color: mat instanceof THREE.MeshStandardMaterial ? mat.color.clone() : 
                     ('color' in mat ? (mat as any).color.clone() : new THREE.Color(0xffffff))
            };
          }

          const { originalTransparent, originalOpacity, originalAlphaTest } = mat.userData.originalProps;

