  // טעינת טקסטורות - מבטיח שכל ערוץ (Diffuse, Metal, etc) נטען בנפרד
  useEffect(() => {
    const loader = new THREE.TextureLoader();
    const mapConfigs = [
      { key: 'map', url: settings.textureUrl, isColor: true },
      { key: 'metalnessMap', url: settings.metalnessUrl, isColor: false },
      { key: 'roughnessMap', url: settings.roughnessUrl, isColor: false },
      { key: 'alphaMap', url: settings.transparencyUrl, isColor: false },
    ];

    mapConfigs.forEach(({ key, url, isColor }) => {
      if (url) {
        loader.load(url, (tex) => {
          if (isColor) tex.colorSpace = THREE.SRGBColorSpace;
          tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
          tex.needsUpdate = true;
          setLoadedTextures(prev => ({ ...prev, [key]: tex }));
        });
      }
    });
  }, [settings.textureUrl, settings.metalnessUrl, settings.roughnessUrl, settings.transparencyUrl]);

  // החלת ההגדרות והשילוב על המודל
  useEffect(() => {
    fbx.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;
        const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];

        const updatedMaterials = materials.map((mat) => {
          // שמירת נתוני מקור כדי לא לדרוס אותם בטעות בפריימים הבאים
          if (!mat.userData.pbrStudio) {
            const originalColor = (mat as any).color ? (mat as any).color.clone() : new THREE.Color(0xffffff);
            // הגנה: אם ה-Opacity המקורי הוא 0, נגדיר אותו כ-1 כדי שלא ייעלם
            const originalOpacity = (mat.opacity !== undefined && mat.opacity > 0.01) ? mat.opacity : 1.0;

            // המרה לחומר Standard PBR מודרני
            const standardMat = new THREE.MeshStandardMaterial({
              color: originalColor,
              map: (mat as any).map || null,
              transparent: mat.transparent,
              opacity: originalOpacity,
              metalness: (mat as any).metalness || 0,
              roughness: (mat as any).roughness || 1,
            });

            mat.userData.pbrStudio = {
              originalColor,
              originalOpacity,
              standardMat
            };
          }

          const { standardMat, originalColor, originalOpacity } = mat.userData.pbrStudio;

          // 1. שילוב טקסטורות
          if (loadedTextures.map) standardMat.map = loadedTextures.map;
          if (loadedTextures.metalnessMap) standardMat.metalnessMap = loadedTextures.metalnessMap;
          if (loadedTextures.roughnessMap) standardMat.roughnessMap = loadedTextures.roughnessMap;
          if (loadedTextures.alphaMap) standardMat.alphaMap = loadedTextures.alphaMap;

          // 2. שילוב צבע (Color Tint) - המודל "משלב" את הצבע הנבחר עם הטקסטורה
          if (settings.color !== '#ffffff') {
            standardMat.color.set(settings.color);
          } else {
            standardMat.color.copy(originalColor);
          }

          // 3. לוגיקת שקיפות חסינה
          // המודל יהיה שקוף אם המשתמש סימן Checkbox, או אם האופסיטי נמוך מ-1, או אם יש מפת אלפא
          const isTransparentMode = settings.transparent || settings.opacity < 0.99 || !!standardMat.alphaMap;

          standardMat.transparent = isTransparentMode;
          standardMat.opacity = originalOpacity * settings.opacity;

          // מניעת היעלמות - אם המודל כמעט אטום, נשמור על DepthWrite דלוק
          standardMat.depthWrite = !isTransparentMode || standardMat.opacity > 0.8;

          // הגדרות PBR
          standardMat.metalness = settings.metalness;
          standardMat.roughness = settings.roughness;
          standardMat.side = THREE.DoubleSide; // חשוב כדי לראות "תוך" המודל כשהוא שקוף

          standardMat.needsUpdate = true;
          return standardMat;
        });

        mesh.material = Array.isArray(mesh.material) ? updatedMaterials : updatedMaterials[0];
        mesh.castShadow = true;
        mesh.receiveShadow = true;
      }
    });
  }, [fbx, settings, loadedTextures]);

  // מרכוז וקנה מידה
  const processedModel = useMemo(() => {
    fbx.updateMatrixWorld(true);
    const box = new THREE.Box3().setFromObject(fbx);
    const size = box.getSize(new THREE.Vector3());
    const maxDim = Math.max(size.x, size.y, size.z);

    // נרמול גודל ל-6 יחידות
    const scale = 6 / (maxDim || 1);
    fbx.scale.setScalar(scale);

    // הזזה למרכז
    const centeredBox = new THREE.Box3().setFromObject(fbx);
    const center = centeredBox.getCenter(new THREE.Vector3());
    fbx.position.sub(center);

    return fbx;
  }, [fbx, url]);

  return <primitive object={processedModel} />;
};

export default FBXModel;

import React, { useEffect, useMemo, useState } from 'react';
import { useLoader } from '@react-three/fiber';
import { FBXLoader } from 'three/examples/jsm/loaders/FBXLoader';
import * as THREE from 'three';
import { MaterialSettings } from '../types';

interface FBXModelProps {
  url: string;
  settings: MaterialSettings;
}

const FBXModel: React.FC<FBXModelProps> = ({ url, settings }) => {
  const fbx = useLoader(FBXLoader, url);
  const [textureCache, setTextureCache] = useState<{ [url: string]: THREE.Texture }>({});

  // טעינת כל הטקסטורות והכנסתן למטמון
  useEffect(() => {
    const loader = new THREE.TextureLoader();
    const allUrls = [...settings.allDiffuseMaps];
    if (settings.metalnessUrl) allUrls.push(settings.metalnessUrl);
    if (settings.roughnessUrl) allUrls.push(settings.roughnessUrl);
    if (settings.transparencyUrl) allUrls.push(settings.transparencyUrl);

    allUrls.forEach(u => {
      if (u && !textureCache[u]) {
        loader.load(u, (tex) => {
          tex.colorSpace = THREE.SRGBColorSpace;
          tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
          setTextureCache(prev => ({ ...prev, [u]: tex }));
        });
      }
    });
  }, [settings.allDiffuseMaps, settings.metalnessUrl, settings.roughnessUrl, settings.transparencyUrl]);

  useEffect(() => {
    let materialCounter = 0;

    fbx.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;
        const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];

        const updatedMaterials = materials.map((mat, index) => {
          const matId = `mat_${child.uuid}_${index}`;

          if (!mat.userData.initialized) {
            // שמירת ערכי מקור והמרת חומר ל-Standard PBR
            const originalColor = (mat as any).color ? (mat as any).color.clone() : new THREE.Color(0xffffff);
            const originalOpacity = (mat.opacity > 0) ? mat.opacity : 1.0;

            const newMat = new THREE.MeshStandardMaterial({
              color: originalColor,
              transparent: false,
              opacity: originalOpacity,
              roughness: 0.5,
              metalness: 0.5,
              side: THREE.DoubleSide
            });

            mat.userData.initialized = true;
            mat.userData.originalColor = originalColor;
            mat.userData.originalOpacity = originalOpacity;
            mat.userData.pbr = newMat;
            mat.userData.matIndex = materialCounter++;
          }

          const pbr = mat.userData.pbr as THREE.MeshStandardMaterial;
          const mIndex = mat.userData.matIndex;

          // שיוך טקסטורות - אם יש כמה טקסטורות diffuse, נחלק אותן לפי אינדקס החומר
          if (settings.allDiffuseMaps.length > 0) {
            const texUrl = settings.allDiffuseMaps[mIndex % settings.allDiffuseMaps.length];
            if (textureCache[texUrl]) pbr.map = textureCache[texUrl];
          }

          // טקסטורות ערוצים נוספים
          if (settings.metalnessUrl && textureCache[settings.metalnessUrl]) pbr.metalnessMap = textureCache[settings.metalnessUrl];
          if (settings.roughnessUrl && textureCache[settings.roughnessUrl]) pbr.roughnessMap = textureCache[settings.roughnessUrl];
          if (settings.transparencyUrl && textureCache[settings.transparencyUrl]) pbr.alphaMap = textureCache[settings.transparencyUrl];

          // שילוב צבע (Tint)
          if (settings.color !== '#ffffff') {
            pbr.color.set(settings.color);
          } else {
            pbr.color.copy(mat.userData.originalColor);
          }

          // לוגיקת שקיפות מתוקנת - מונע היעלמות
          pbr.transparent = settings.transparent;
          // אם שקיפות דלוקה, נשתמש בערך הסליידר. אם כבויה, תמיד 1.0
          pbr.opacity = settings.transparent ? settings.opacity : 1.0;

          // הגדרות רינדור קריטיות למניעת באגים ויזואליים
          pbr.depthWrite = !settings.transparent; // עוזר לראות חלקים פנימיים בלי "שבירה"
          pbr.alphaTest = settings.transparent ? 0.01 : 0;

          pbr.metalness = settings.metalness;
          pbr.roughness = settings.roughness;
          pbr.needsUpdate = true;

          return pbr;
        });

        mesh.material = Array.isArray(mesh.material) ? updatedMaterials : updatedMaterials[0];
        mesh.castShadow = true;
        mesh.receiveShadow = true;
      }
    });
  }, [fbx, settings, textureCache]);

  const processedModel = useMemo(() => {
    fbx.updateMatrixWorld(true);
    const box = new THREE.Box3().setFromObject(fbx);
    const size = box.getSize(new THREE.Vector3());
    const maxDim = Math.max(size.x, size.y, size.z);
    const scale = 6 / (maxDim || 1);
    fbx.scale.setScalar(scale);

    const centeredBox = new THREE.Box3().setFromObject(fbx);
    const center = centeredBox.getCenter(new THREE.Vector3());
    fbx.position.sub(center);

    return fbx;
  }, [fbx, url]);

  return <primitive object={processedModel} />;
};

export default FBXModel;

