    roughnessUrl: null,
    transparencyUrl: null
  });

  const handleFileUpload = (file: File) => {
    const url = URL.createObjectURL(file);
    setModelUrl(url);
    setDetectedMaterials([]); // Reset for new model
    setMaterialSettings(prev => ({ 
      ...prev,
      allDiffuseMaps: [],
      materialMappings: {},
      transparent: false,
      opacity: 1.0
    }));
  };

  const handleTextureUpload = (file: File, type: 'base' | 'metal' | 'rough' | 'transparency') => {
