import { ThreeElements } from '@react-three/fiber';

/**
 * Standard JSX augmentation for React Three Fiber.
 * This ensures that intrinsic lowercase elements like <mesh />, <group />, <ambientLight />, etc. 
 * are correctly typed and recognized by the TypeScript compiler.
 */
declare global {
  namespace JSX {
    interface IntrinsicElements extends ThreeElements {}
  }
}

/**
 * React 18+ specific augmentation. In modern React types, intrinsic elements are
 * often looked up within the React.JSX namespace. This ensures compatibility
 * across various project setups and React versions.
 */
declare global {
  namespace React {
    namespace JSX {
      interface IntrinsicElements extends ThreeElements {}
    }
  }
}

/**
 * Direct module augmentation for 'react' as an extra layer of compatibility
 * for strict TypeScript environments or specific build tool configurations.
 */
