import React, { useState, Suspense } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, PerspectiveCamera, Environment, ContactShadows, Float, Html } from '@react-three/drei';
import './types';
import Room from './components/Room';
import FBXModel from './components/FBXModel';
import UIOverlay from './components/UIOverlay';
import { MaterialSettings } from './types';

const App: React.FC = () => {
  const [modelUrl, setModelUrl] = useState<string | null>(null);
  const [detectedMaterials, setDetectedMaterials] = useState<string[]>([]);
  const [materialSettings, setMaterialSettings] = useState<MaterialSettings>({
    opacity: 1.0,
    metalness: 0.5,
    roughness: 0.5,
    emissiveIntensity: 0.2,
    color: '#ffffff',
    transparent: false,
    materialMappings: {},
    hoveredMaterial: null,
    metalnessUrl: null,
    roughnessUrl: null,
    transparencyUrl: null
  });

  const handleFileUpload = (file: File) => {
    const url = URL.createObjectURL(file);
    setModelUrl(url);
    setDetectedMaterials([]);
    setMaterialSettings(prev => ({ 
      ...prev,
      materialMappings: {},
      transparent: false,
      opacity: 1.0,
      metalnessUrl: null,
      roughnessUrl: null,
      transparencyUrl: null
    }));
  };

  const handleTextureUpload = (file: File, type: 'base' | 'metal' | 'rough' | 'transparency', matName?: string) => {
    const url = URL.createObjectURL(file);

    setMaterialSettings(prev => {
      if (type === 'base') {
        const newMappings = { ...prev.materialMappings };
        if (matName) {
          newMappings[matName] = url;
        } else if (prev.hoveredMaterial) {
          newMappings[prev.hoveredMaterial] = url;
        } else {
          detectedMaterials.forEach(mat => {
            newMappings[mat] = url;
          });
        }
        return { ...prev, materialMappings: newMappings };
      }

      const fieldMap = { 
        metal: 'metalnessUrl', 
        rough: 'roughnessUrl', 
        transparency: 'transparencyUrl' 
      } as const;

      const newState = { ...prev, [fieldMap[type]]: url };

      // אם העלנו מפת שקיפות, נדליק את מצב השקיפות אוטומטית
      if (type === 'transparency') {
        newState.transparent = true;
      }

      return newState;
    });
  };

  return (
    <div className="relative w-screen h-screen bg-[#020617] overflow-hidden">
      <Canvas shadows dpr={[1, 2]} gl={{ antialias: true }}>
        <PerspectiveCamera makeDefault position={[8, 4, 8]} fov={35} />

        <Suspense fallback={<Html center><div className="text-blue-500 animate-spin text-4xl font-black tracking-widest">LOADING ENGINE...</div></Html>}>
          <ambientLight intensity={0.4} />
          <spotLight position={[10, 15, 10]} angle={0.3} penumbra={1} intensity={2} castShadow />
          <pointLight position={[-10, -10, -10]} intensity={1} color="#3b82f6" />
          <Environment preset="city" />

          <Room />

          <group position={[0, 0, 0]}>
            <Float speed={1.5} rotationIntensity={0.2} floatIntensity={0.5}>
              {modelUrl && (
                <FBXModel 
                  url={modelUrl} 
                  settings={materialSettings} 
                  onMaterialsLoaded={setDetectedMaterials} 
                />
              )}
            </Float>
            <ContactShadows position={[0, -4.9, 0]} opacity={0.4} scale={15} blur={2.5} far={10} color="#000000" />
          </group>
        </Suspense>

        <OrbitControls enableDamping minDistance={2} maxDistance={20} />
      </Canvas>

      <UIOverlay 
        settings={materialSettings} 
        setSettings={setMaterialSettings} 
        onFileUpload={handleFileUpload}
        onTextureUpload={handleTextureUpload}
        detectedMaterials={detectedMaterials}
      />
    </div>
  );
};

export default App;

