          } else {
            pbr.metalnessMap = null;
            pbr.metalness = settings.metalness;
          }

          if (settings.roughnessUrl && textureCache[settings.roughnessUrl]) {
            pbr.roughnessMap = textureCache[settings.roughnessUrl];
            pbr.roughness = 1.0;
          } else {
            pbr.roughnessMap = null;
            pbr.roughness = settings.roughness;
          }

          // 3. Transparency & Alpha Map
          pbr.transparent = settings.transparent;
          if (settings.transparencyUrl && textureCache[settings.transparencyUrl]) {
            pbr.alphaMap = textureCache[settings.transparencyUrl];
          } else {
            pbr.alphaMap = null;
          }

          pbr.opacity = settings.transparent ? settings.opacity : 1.0;
          pbr.depthWrite = !settings.transparent;

          // 4. Emissive & Hover
          if (isHovered) {
            pbr.emissive.setHex(0x3b82f6);
            pbr.emissiveIntensity = Math.max(pulse * 2, settings.emissiveIntensity);
          } else {
            pbr.emissive.setHex(0x000000);
            pbr.emissiveIntensity = 0;
          }

          pbr.color.copy(settings.color === '#ffffff' ? mat.userData.originalColor : new THREE.Color(settings.color));
          pbr.needsUpdate = true;
          return pbr;
        });

        mesh.material = Array.isArray(mesh.material) ? updatedMaterials : updatedMaterials[0];
      }
    });
  }, [fbx, settings, textureCache, pulse]);

  const processedModel = useMemo(() => {
    fbx.updateMatrixWorld(true);
    const box = new THREE.Box3().setFromObject(fbx);
    const size = box.getSize(new THREE.Vector3());
    const scale = 6 / (Math.max(size.x, size.y, size.z) || 1);
    fbx.scale.setScalar(scale);
    const center = new THREE.Box3().setFromObject(fbx).getCenter(new THREE.Vector3());
    fbx.position.sub(center);
    return fbx;
  }, [fbx, url]);

  return <primitive object={processedModel} />;
};

export default FBXModel;

import React, { useEffect, useMemo, useState } from 'react';
import { useLoader, useFrame } from '@react-three/fiber';
import { FBXLoader } from 'three/examples/jsm/loaders/FBXLoader';
import * as THREE from 'three';
import '../types';
import { MaterialSettings } from '../types';

interface FBXModelProps {
  url: string;
  settings: MaterialSettings;
  onMaterialsLoaded?: (materials: string[]) => void;
}

const FBXModel: React.FC<FBXModelProps> = ({ url, settings, onMaterialsLoaded }) => {
  const fbx = useLoader(FBXLoader, url);
  const [textureCache, setTextureCache] = useState<{ [url: string]: THREE.Texture }>({});

  const [pulse, setPulse] = useState(0);
  useFrame((state) => {
    setPulse(Math.sin(state.clock.elapsedTime * 10) * 0.5 + 0.5);
  });

  // טעינת טקסטורות
  useEffect(() => {
    const loader = new THREE.TextureLoader();

    // טקסטורות צבע
    Object.values(settings.materialMappings).forEach(u => {
      if (u && !textureCache[u]) {
        loader.load(u, (tex) => {
          tex.colorSpace = THREE.SRGBColorSpace;
          tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
          tex.needsUpdate = true;
          setTextureCache(prev => ({ ...prev, [u as string]: tex }));
        });
      }
    });

    // מפות PBR
    [settings.metalnessUrl, settings.roughnessUrl, settings.transparencyUrl].forEach(u => {
      if (u && !textureCache[u as string]) {
        loader.load(u as string, (tex) => {
          tex.colorSpace = THREE.NoColorSpace;
          tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
          tex.needsUpdate = true;
          setTextureCache(prev => ({ ...prev, [u as string]: tex }));
        });
      }
    });
  }, [settings.materialMappings, settings.metalnessUrl, settings.roughnessUrl, settings.transparencyUrl]);

  useEffect(() => {
    const materialNames: string[] = [];
    fbx.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;
        const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
        materials.forEach((m) => {
          if (m && !m.name) m.name = `Material_${materialNames.length}`;
          if (m && !materialNames.includes(m.name)) materialNames.push(m.name);
        });
      }
    });
    if (onMaterialsLoaded) onMaterialsLoaded(materialNames);
  }, [fbx, url, onMaterialsLoaded]);

  useEffect(() => {
    fbx.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;
        const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];

        const updatedMaterials = materials.map((mat) => {
          if (!mat.userData.pbr || mat.type !== 'MeshStandardMaterial') {
            const originalColor = (mat as any).color ? (mat as any).color.clone() : new THREE.Color(0xffffff);
            const newMat = new THREE.MeshStandardMaterial({
              name: mat.name,
              color: originalColor,
              side: THREE.DoubleSide
            });
            mat.userData.pbr = newMat;
            mat.userData.originalColor = originalColor;
          }

          const pbr = mat.userData.pbr as THREE.MeshStandardMaterial;
          const isHovered = settings.hoveredMaterial === mat.name;

          // 1. צבע בסיס
          const texUrl = settings.materialMappings[mat.name];
          pbr.map = (texUrl && textureCache[texUrl]) ? textureCache[texUrl] : null;

          // 2. מטאליות וחספוס
          if (settings.metalnessUrl && textureCache[settings.metalnessUrl]) {
            pbr.metalnessMap = textureCache[settings.metalnessUrl];
            pbr.metalness = 1.0; 
          } else {
            pbr.metalnessMap = null;
            pbr.metalness = settings.metalness;
          }

          if (settings.roughnessUrl && textureCache[settings.roughnessUrl]) {
            pbr.roughnessMap = textureCache[settings.roughnessUrl];
            pbr.roughness = 1.0;
          } else {
            pbr.roughnessMap = null;
            pbr.roughness = settings.roughness;
          }

          // 3. לוגיקת שקיפות משופרת
          // אם המפסק כבוי - החומר חייב להיות אטום לחלוטין
          if (!settings.transparent) {
            if (pbr.transparent) {
              pbr.transparent = false;
              pbr.needsUpdate = true; // הכרחי כדי ש-Three.js יחליף Shader
            }
            pbr.opacity = 1.0;
            pbr.alphaMap = null;
            pbr.depthWrite = true;
          } else {
            // אם המפסק דלוק - משתמשים בהגדרות השקיפות
            if (!pbr.transparent) {
              pbr.transparent = true;
              pbr.needsUpdate = true;
            }
            pbr.opacity = settings.opacity;
            pbr.depthWrite = false;

            // שימוש במפת אלפא אם קיימת
            if (settings.transparencyUrl && textureCache[settings.transparencyUrl]) {
              pbr.alphaMap = textureCache[settings.transparencyUrl];
            } else {
              pbr.alphaMap = null;
            }
          }

          // 4. אפקטים נוספים
          if (isHovered) {
            pbr.emissive.setHex(0x3b82f6);
            pbr.emissiveIntensity = Math.max(pulse * 2, settings.emissiveIntensity);
          } else {
            pbr.emissive.setHex(0x000000);
            pbr.emissiveIntensity = 0;
          }

          pbr.color.copy(settings.color === '#ffffff' ? mat.userData.originalColor : new THREE.Color(settings.color));

          return pbr;
        });

        mesh.material = Array.isArray(mesh.material) ? updatedMaterials : updatedMaterials[0];
      }
    });
  }, [fbx, settings, textureCache, pulse]);

  const processedModel = useMemo(() => {
    fbx.updateMatrixWorld(true);
    const box = new THREE.Box3().setFromObject(fbx);
    const size = box.getSize(new THREE.Vector3());
    const scale = 6 / (Math.max(size.x, size.y, size.z) || 1);
    fbx.scale.setScalar(scale);
    const center = new THREE.Box3().setFromObject(fbx).getCenter(new THREE.Vector3());
    fbx.position.sub(center);
    return fbx;
  }, [fbx, url]);

  return <primitive object={processedModel} />;
};

export default FBXModel;

import React, { useState, Suspense } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, PerspectiveCamera, Environment, ContactShadows, Float, Html } from '@react-three/drei';
import './types';
import Room from './components/Room';
import FBXModel from './components/FBXModel';
import UIOverlay from './components/UIOverlay';
import { MaterialSettings } from './types';

const App: React.FC = () => {
  const [modelUrl, setModelUrl] = useState<string | null>(null);
  const [detectedMaterials, setDetectedMaterials] = useState<string[]>([]);
  const [materialSettings, setMaterialSettings] = useState<MaterialSettings>({
    opacity: 1.0,
    metalness: 0.5,
    roughness: 0.5,
    emissiveIntensity: 0.2,
    color: '#ffffff',
    transparent: false,
    materialMappings: {},
    hoveredMaterial: null,
    metalnessUrl: null,
    roughnessUrl: null,
    transparencyUrl: null
  });

  const handleFileUpload = (file: File) => {
    const url = URL.createObjectURL(file);
    setModelUrl(url);
    setDetectedMaterials([]);
    setMaterialSettings(prev => ({ 
      ...prev,
      materialMappings: {},
      transparent: false,
      opacity: 1.0,
      metalnessUrl: null,
      roughnessUrl: null,
      transparencyUrl: null
    }));
  };

  const handleTextureUpload = (file: File, type: 'base' | 'metal' | 'rough' | 'transparency', matName?: string) => {
    const url = URL.createObjectURL(file);

    setMaterialSettings(prev => {
      if (type === 'base') {
        const newMappings = { ...prev.materialMappings };
        if (matName) {
          newMappings[matName] = url;
        } else if (prev.hoveredMaterial) {
          newMappings[prev.hoveredMaterial] = url;
        } else {
          detectedMaterials.forEach(mat => {
            newMappings[mat] = url;
          });
        }
        return { ...prev, materialMappings: newMappings };
      }

      const fieldMap = { 
        metal: 'metalnessUrl', 
        rough: 'roughnessUrl', 
        transparency: 'transparencyUrl' 
      } as const;

      // אנחנו רק מעדכנים את ה-URL של המפה, לא משנים את הסטטוס של transparent אוטומטית יותר
      return { ...prev, [fieldMap[type]]: url };
    });
  };

  return (
    <div className="relative w-screen h-screen bg-[#020617] overflow-hidden">
      <Canvas shadows dpr={[1, 2]} gl={{ antialias: true }}>
        <PerspectiveCamera makeDefault position={[8, 4, 8]} fov={35} />

        <Suspense fallback={<Html center><div className="text-blue-500 animate-spin text-4xl font-black tracking-widest">LOADING ENGINE...</div></Html>}>
          <ambientLight intensity={0.4} />
          <spotLight position={[10, 15, 10]} angle={0.3} penumbra={1} intensity={2} castShadow />
          <pointLight position={[-10, -10, -10]} intensity={1} color="#3b82f6" />
          <Environment preset="city" />

          <Room />

          <group position={[0, 0, 0]}>
            <Float speed={1.5} rotationIntensity={0.2} floatIntensity={0.5}>
              {modelUrl && (
                <FBXModel 
                  url={modelUrl} 
                  settings={materialSettings} 
                  onMaterialsLoaded={setDetectedMaterials} 
                />
              )}
            </Float>
            <ContactShadows position={[0, -4.9, 0]} opacity={0.4} scale={15} blur={2.5} far={10} color="#000000" />
          </group>
        </Suspense>

        <OrbitControls enableDamping minDistance={2} maxDistance={20} />
      </Canvas>

      <UIOverlay 
        settings={materialSettings} 
        setSettings={setMaterialSettings} 
        onFileUpload={handleFileUpload}
        onTextureUpload={handleTextureUpload}
        detectedMaterials={detectedMaterials}
      />
    </div>
  );
};

export default App;

