import * as THREE from 'three';
import '../types';
import { MaterialSettings } from '../types';

interface FBXModelProps {
  url: string;
  settings: MaterialSettings;
  onMaterialsLoaded?: (materials: string[]) => void;
}

const FBXModel: React.FC<FBXModelProps> = ({ url, settings, onMaterialsLoaded }) => {
  const fbx = useLoader(FBXLoader, url);
  const [textureCache, setTextureCache] = useState<{ [url: string]: THREE.Texture }>({});
  const loaderRef = useRef(new THREE.TextureLoader());

  const [pulse, setPulse] = useState(0);
  useFrame((state) => {
    setPulse(Math.sin(state.clock.elapsedTime * 10) * 0.5 + 0.5);
  });

  // טעינת טקסטורות למטמון
  useEffect(() => {
    const urlsToLoad: { url: string; isColor: boolean }[] = [];

    // איסוף כל ה-URLs שצריך לטעון
    Object.values(settings.materialMappings).forEach(u => u && urlsToLoad.push({ url: u, isColor: true }));
    if (settings.metalnessUrl) urlsToLoad.push({ url: settings.metalnessUrl, isColor: false });
    if (settings.roughnessUrl) urlsToLoad.push({ url: settings.roughnessUrl, isColor: false });
    if (settings.transparencyUrl) urlsToLoad.push({ url: settings.transparencyUrl, isColor: false });

    urlsToLoad.forEach(({ url: u, isColor }) => {
      if (!textureCache[u]) {
        loaderRef.current.load(u, (tex) => {
          tex.colorSpace = isColor ? THREE.SRGBColorSpace : THREE.NoColorSpace;
          tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
          tex.needsUpdate = true;
          setTextureCache(prev => ({ ...prev, [u]: tex }));
        });
      }
    });
  }, [settings.materialMappings, settings.metalnessUrl, settings.roughnessUrl, settings.transparencyUrl]);

  // זיהוי חומרים מהמודל
  useEffect(() => {
    const materialNames: string[] = [];
    fbx.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;
        const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
        materials.forEach((m) => {
          if (m) {
            if (!m.name) m.name = `Material_${materialNames.length}`;
            if (!materialNames.includes(m.name)) materialNames.push(m.name);
          }
        });
      }
    });
    if (onMaterialsLoaded) onMaterialsLoaded(materialNames);
  }, [fbx, url, onMaterialsLoaded]);

  // עדכון חומרים בזמן אמת
  useEffect(() => {
    fbx.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;
        const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];

        const updatedMaterials = materials.map((mat) => {
          // המרה ל-MeshStandardMaterial אם זה לא הסוג הנכון (תמיכת PBR)
          if (!mat.userData.pbr || mat.type !== 'MeshStandardMaterial') {
            const originalColor = (mat as any).color ? (mat as any).color.clone() : new THREE.Color(0xffffff);
            const newMat = new THREE.MeshStandardMaterial({
              name: mat.name,
              color: originalColor,
              side: THREE.DoubleSide,
              alphaTest: 0.01 // עוזר במניעת בעיות רינדור של שקיפות
            });
            mat.userData.pbr = newMat;
            mat.userData.originalColor = originalColor;
          }

          const pbr = mat.userData.pbr as THREE.MeshStandardMaterial;
          const isHovered = settings.hoveredMaterial === mat.name;

          // 1. Base Color Map
          const texUrl = settings.materialMappings[mat.name];
          pbr.map = (texUrl && textureCache[texUrl]) ? textureCache[texUrl] : null;

          // 2. Metalness & Roughness
          if (settings.metalnessUrl && textureCache[settings.metalnessUrl]) {
            pbr.metalnessMap = textureCache[settings.metalnessUrl];
            pbr.metalness = 1.0; 
          } else {
            pbr.metalnessMap = null;
            pbr.metalness = settings.metalness;
          }

          if (settings.roughnessUrl && textureCache[settings.roughnessUrl]) {
            pbr.roughnessMap = textureCache[settings.roughnessUrl];
            pbr.roughness = 1.0;
          } else {
            pbr.roughnessMap = null;
            pbr.roughness = settings.roughness;
          }

          // 3. MASTER TRANSPARENCY LOGIC
          const hasAlphaMap = !!(settings.transparencyUrl && textureCache[settings.transparencyUrl]);

          if (!settings.transparent) {
            // מצב אטום - התעלמות מוחלטת מהגדרות שקיפות
            if (pbr.transparent) {
              pbr.transparent = false;
              pbr.needsUpdate = true;
            }
            pbr.opacity = 1.0;
            pbr.alphaMap = null;
            pbr.depthWrite = true;
          } else {
            // מצב שקיפות פעיל
            if (!pbr.transparent) {
              pbr.transparent = true;
              pbr.needsUpdate = true;
            }
            pbr.depthWrite = false;

            // עדיפות למפת אלפא אם קיימת, אחרת שימוש בסליידר
            if (hasAlphaMap) {
              pbr.alphaMap = textureCache[settings.transparencyUrl!];
              pbr.opacity = 1.0; // במפת אלפא לרוב נרצה אופסיטי מלא כדי שהמפה תשלוט
            } else {
              pbr.alphaMap = null;
              pbr.opacity = settings.opacity;
            }
          }

          // 4. Hover & Emissive
          if (isHovered) {
            pbr.emissive.setHex(0x3b82f6);
            pbr.emissiveIntensity = Math.max(pulse * 2, settings.emissiveIntensity);
          } else {
            pbr.emissive.setHex(0x000000);
            pbr.emissiveIntensity = 0;
          }

          pbr.color.copy(settings.color === '#ffffff' ? mat.userData.originalColor : new THREE.Color(settings.color));

          return pbr;
        });

        mesh.material = Array.isArray(mesh.material) ? updatedMaterials : updatedMaterials[0];
      }
    });
  }, [fbx, settings, textureCache, pulse]);

  const processedModel = useMemo(() => {
    fbx.updateMatrixWorld(true);
    const box = new THREE.Box3().setFromObject(fbx);
    const size = box.getSize(new THREE.Vector3());
    const scale = 6 / (Math.max(size.x, size.y, size.z) || 1);
    fbx.scale.setScalar(scale);
    const center = new THREE.Box3().setFromObject(fbx).getCenter(new THREE.Vector3());
    fbx.position.sub(center);
    return fbx;
  }, [fbx, url]);

  return <primitive object={processedModel} />;
};

export default FBXModel;

import React from 'react';
import { ThreeElements } from '@react-three/fiber';

/**
 * Standard JSX augmentation for React Three Fiber.
 * By merging with both global JSX and React.JSX namespaces, we ensure compatibility with 
 * various TypeScript configurations (including React 18+ and older transforms).
 * We explicitly extend React.JSX.IntrinsicElements in the global JSX namespace to preserve 
 * standard HTML elements like 'div' and 'span' while adding Three.js elements.
 */
declare global {
  namespace React {
    namespace JSX {
      interface IntrinsicElements extends ThreeElements {}
    }
  }
  namespace JSX {
    interface IntrinsicElements extends ThreeElements, React.JSX.IntrinsicElements {}
  }
}

export interface MaterialSettings {
  opacity: number;
  metalness: number;
  roughness: number;
  emissiveIntensity: number;
  color: string;
  transparent: boolean;
  materialMappings: Record<string, string>; // שם חומר -> URL של טקסטורה
  hoveredMaterial: string | null;
  metalnessUrl?: string | null;
  roughnessUrl?: string | null;
  transparencyUrl?: string | null;
}

export interface ModelMetadata {
  name: string;
  size: string;
  triangleCount: number;
  materials: string[];
}

