import React from 'react';
import { ThreeElements } from '@react-three/fiber';

/**
 * Standard JSX augmentation for React Three Fiber.
 * We augment the React.JSX namespace to include Three.js elements.
 * This ensures compatibility with React 18+ while preserving standard HTML elements like 'div' and 'span'.
 * We extend the IntrinsicElements interface to add Three.js specific tags without shadowing the global JSX namespace.
 */
declare global {
  namespace React {
    namespace JSX {
      // Augment React's IntrinsicElements to include Three.js elements.
      // By using 'extends ThreeElements', we merge Three.js tags into the existing HTML tags.
      interface IntrinsicElements extends ThreeElements {}
    }
  }
}

