import React, { useState, Suspense } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, PerspectiveCamera, Environment, ContactShadows, Float, Html } from '@react-three/drei';
import './types';
import Room from './components/Room';
import FBXModel from './components/FBXModel';
import UIOverlay from './components/UIOverlay';
import { MaterialSettings } from './types';

const App: React.FC = () => {
  const [modelUrl, setModelUrl] = useState<string | null>(null);
  const [detectedMaterials, setDetectedMaterials] = useState<string[]>([]);
  const [materialSettings, setMaterialSettings] = useState<MaterialSettings>({
    opacity: 1.0,
    metalness: 0.5,
    roughness: 0.5,
    emissiveIntensity: 0.0,
    color: '#ffffff',
    transparent: false,
    materialMappings: {},
    hoveredMaterial: null,
    metalnessUrl: null,
    roughnessUrl: null,
    transparencyUrl: null
  });

  const handleFileUpload = (file: File) => {
    const url = URL.createObjectURL(file);
    setModelUrl(url);
    setDetectedMaterials([]);
    setMaterialSettings(prev => ({ 
      ...prev,
      materialMappings: {},
      transparent: false,
      opacity: 1.0,
      metalnessUrl: null,
      roughnessUrl: null,
      transparencyUrl: null
    }));
  };

  const handleTextureUpload = (file: File, type: 'base' | 'metal' | 'rough' | 'transparency', matName?: string) => {
    const url = URL.createObjectURL(file);

    setMaterialSettings(prev => {
      if (type === 'base') {
        const newMappings = { ...prev.materialMappings };
        if (matName) {
          newMappings[matName] = url;
        } else if (prev.hoveredMaterial) {
          newMappings[prev.hoveredMaterial] = url;
        } else {
          detectedMaterials.forEach(mat => {
            newMappings[mat] = url;
          });
        }
        return { ...prev, materialMappings: newMappings };
      }

      const fieldMap = { 
        metal: 'metalnessUrl', 
        rough: 'roughnessUrl', 
        transparency: 'transparencyUrl' 
      } as const;

      return { ...prev, [fieldMap[type]]: url };
    });
  };

  return (
    <div className="relative w-screen h-screen bg-[#f1f1f4] overflow-hidden">
      <Canvas shadows dpr={[1, 2]} gl={{ antialias: true, alpha: true }}>
        <PerspectiveCamera makeDefault position={[12, 6, 12]} fov={35} />

        <Suspense fallback={
          <Html center>
            <div className="flex flex-col items-center gap-4">
               <div className="w-12 h-12 border-2 border-slate-200 border-t-blue-500 rounded-full animate-spin"></div>
               <div className="text-slate-400 text-[10px] font-black tracking-[0.5em] uppercase">Refining Studio</div>
            </div>
          </Html>
        }>
          {/* Softened Lighting Mix */}
          <ambientLight intensity={0.7} />
          <spotLight position={[15, 20, 15]} angle={0.3} penumbra={1} intensity={1.8} castShadow color="#fffaf0" />
          <directionalLight position={[-10, 10, -5]} intensity={0.6} color="#e0f2fe" />
          <Environment preset="city" />

          <Room />

          <group position={[0, 0, 0]}>
            {modelUrl ? (
              <Float speed={1.2} rotationIntensity={0.05} floatIntensity={0.2}>
                <FBXModel 
                  url={modelUrl} 
                  settings={materialSettings} 
                  onMaterialsLoaded={setDetectedMaterials} 
                />
              </Float>
            ) : (
              <mesh position={[0, -4.8, 0]} rotation={[-Math.PI/2, 0, 0]}>
                <ringGeometry args={[1.8, 1.85, 64]} />
                <meshBasicMaterial color="#94a3b8" transparent opacity={0.3} />
              </mesh>
            )}
            <ContactShadows 
              position={[0, -4.95, 0]} 
              opacity={0.15} 
              scale={25} 
              blur={4} 
              far={10} 
              color="#334155" 
            />
          </group>
        </Suspense>

        <OrbitControls enableDamping minDistance={4} maxDistance={35} dampingFactor={0.05} rotateSpeed={0.5} />
      </Canvas>

      <UIOverlay 
        settings={materialSettings} 
        setSettings={setMaterialSettings} 
        onFileUpload={handleFileUpload}
        onTextureUpload={handleTextureUpload}
        detectedMaterials={detectedMaterials}
        isModelLoaded={!!modelUrl}
      />
    </div>
  );
};

export default App;

