            <span className="text-[8px] text-slate-300 font-medium">{detectedMaterials.length} nodes</span>
          </div>

          <div className="flex-1 space-y-2 overflow-y-auto pr-2">
            {detectedMaterials.map((mat) => (
              <div 
                key={mat}
                onMouseEnter={() => setSettings({...settings, hoveredMaterial: mat})}
                onMouseLeave={() => setSettings({...settings, hoveredMaterial: null})}
                className={`p-4 rounded-[1.5rem] transition-all duration-300 ${settings.hoveredMaterial === mat ? 'bg-white/80 border-slate-200' : 'bg-white/10 border-transparent'} border`}
              >
                <div className="flex flex-col gap-3">
                  <span className="text-[9px] text-slate-500 font-bold truncate tracking-tight uppercase">{mat}</span>
                  <label className="block">
                    <div className="w-full py-2 bg-slate-50/50 rounded-xl border border-slate-100 flex items-center justify-center gap-2 cursor-pointer hover:bg-white transition-all text-slate-300">
                      <span className="text-[7px] font-bold uppercase tracking-widest">Texture</span>
                    </div>
                    <input type="file" className="hidden" accept="image/*" onChange={(e) => e.target.files?.[0] && onTextureUpload(e.target.files[0], 'base', mat)} />
