          {[
            { label: 'Met', type: 'metal' as const },
            { label: 'Rgh', type: 'rough' as const },
            { label: 'Alp', type: 'transparency' as const }
          ].map((btn) => (
            <label key={btn.type} className={`w-12 h-12 rounded-full border border-slate-100 flex items-center justify-center cursor-pointer transition-all ${settings[`${btn.type}Url` as keyof MaterialSettings] ? 'bg-slate-200 border-slate-300' : 'bg-white/40 hover:bg-white'}`}>
              <span className="text-[8px] font-bold uppercase text-slate-400">{btn.label}</span>
              <input type="file" className="hidden" accept="image/*" onChange={(e) => e.target.files?.[0] && onTextureUpload(e.target.files[0], btn.type)} />
