import React, { useState, Suspense } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, PerspectiveCamera, Environment, ContactShadows, Float, Html, PivotControls } from '@react-three/drei';
import * as THREE from 'three';
import './types';
import Room from './components/Room';
import FBXModel from './components/FBXModel';
import UIOverlay from './components/UIOverlay';
import Sidebar from './components/Sidebar';
import { MaterialSettings, SceneModelInstance } from './types';

const App: React.FC = () => {
  const [models, setModels] = useState<SceneModelInstance[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);

  const createDefaultSettings = (): MaterialSettings => ({
    opacity: 1.0,
    metalness: 0.5,
    roughness: 0.5,
    emissiveIntensity: 0.0,
    color: '#ffffff',
    transparent: false,
    materialMappings: {},
    hoveredMaterial: null,
    metalnessUrl: null,
    roughnessUrl: null,
    transparencyUrl: null
  });

  const handleAddFile = (file: File) => {
    const url = URL.createObjectURL(file);
    const id = Math.random().toString(36).substr(2, 9);
    const newModel: SceneModelInstance = {
      id,
      name: file.name.replace('.fbx', ''),
      url,
      settings: createDefaultSettings(),
      detectedMaterials: [],
      position: [0, 0, 0] // Default to center
    };
    setModels(prev => [...prev, newModel]);
    setSelectedId(id);
  };

  const updateModelData = (id: string, updates: Partial<SceneModelInstance>) => {
    setModels(prev => prev.map(m => m.id === id ? { ...m, ...updates } : m));
  };

  const updateSelectedSettings = (newSettings: MaterialSettings) => {
    if (!selectedId) return;
    updateModelData(selectedId, { settings: newSettings });
  };

  const handleMaterialsDetected = (id: string, mats: string[]) => {
    updateModelData(id, { detectedMaterials: mats });
  };

  const handleTextureUpload = (file: File, type: 'base' | 'metal' | 'rough' | 'transparency', matName?: string) => {
    const url = URL.createObjectURL(file);
    const selectedModel = models.find(m => m.id === selectedId);
    if (!selectedModel) return;

    const currentSettings = selectedModel.settings;
    let newSettings = { ...currentSettings };

    if (type === 'base') {
      const newMappings = { ...currentSettings.materialMappings };
      if (matName) {
        newMappings[matName] = url;
      } else if (currentSettings.hoveredMaterial) {
        newMappings[currentSettings.hoveredMaterial] = url;
      } else {
        selectedModel.detectedMaterials.forEach(mat => {
          newMappings[mat] = url;
        });
      }
      newSettings.materialMappings = newMappings;
    } else {
      const fieldMap = { 
        metal: 'metalnessUrl', 
        rough: 'roughnessUrl', 
        transparency: 'transparencyUrl' 
      } as const;
      newSettings = { ...newSettings, [fieldMap[type]]: url };
    }

    updateSelectedSettings(newSettings);
  };

  const selectedModel = models.find(m => m.id === selectedId);

  return (
    <div className="relative w-screen h-screen overflow-hidden flex">
      {/* 3D Viewport */}
      <div className="flex-1 relative bg-[#020617]">
        <Canvas shadows dpr={[1, 2]} gl={{ antialias: true, alpha: true }}>
          <PerspectiveCamera makeDefault position={[12, 10, 15]} fov={40} />

          <Suspense fallback={<Html center><div className="text-indigo-400 font-black uppercase tracking-[0.5em] animate-pulse text-xs">Studio Core Loading...</div></Html>}>
            <ambientLight intensity={0.5} />
            <spotLight position={[20, 30, 10]} angle={0.2} penumbra={1} intensity={2} castShadow color="#818cf8" />
            <Environment preset="night" />

            <Room />

            {models.map((model) => {
              const isSelected = selectedId === model.id;

              return (
                <group key={model.id}>
                  {isSelected ? (
                    <PivotControls
                      autoTransform
                      depthTest={false}
                      fixed={false}
                      scale={2.5}
                      anchor={[0, 0, 0]}
                      onDragEnd={() => {
                        // After drag, we could sync back if needed, but autoTransform handles visual.
                        // To keep react state in sync for exports:
                        // Here we'd ideally capture the matrix, but for simplicity we let autoTransform work.
                      }}
                    >
                      <group position={model.position}>
                        <FBXModel 
                          url={model.url} 
                          settings={model.settings} 
                          onMaterialsLoaded={(mats) => handleMaterialsDetected(model.id, mats)} 
                        />
                      </group>
                    </PivotControls>
                  ) : (
                    <group position={model.position} onClick={(e) => {
                      e.stopPropagation();
                      setSelectedId(model.id);
                    }}>
                      <FBXModel 
                        url={model.url} 
                        settings={model.settings} 
                        onMaterialsLoaded={(mats) => handleMaterialsDetected(model.id, mats)} 
                      />
                    </group>
                  )}

                  {isSelected && (
                    <ContactShadows position={[model.position[0], -4.95, model.position[2]]} opacity={0.6} scale={15} blur={2} far={10} color="#000000" />
                  )}
                </group>
              );
            })}

            {!selectedId && <ContactShadows position={[0, -4.95, 0]} opacity={0.3} scale={40} blur={3} far={10} color="#000000" />}
          </Suspense>

          <OrbitControls 
            makeDefault 
            enableDamping 
            minDistance={2} 
            maxDistance={80} 
            dampingFactor={0.05}
            // Disable orbit controls while interacting with pivot
            enabled={true} 
          />
        </Canvas>

        {/* Global Overlays */}
        <UIOverlay 
          settings={selectedModel?.settings || createDefaultSettings()} 
          setSettings={updateSelectedSettings}
          onFileUpload={handleAddFile}
          onTextureUpload={handleTextureUpload}
          detectedMaterials={selectedModel?.detectedMaterials || []}
          isModelLoaded={!!selectedId}
        />
      </div>

      {/* Sidebar - Scene Management */}
      <Sidebar 
        models={models} 
        selectedId={selectedId} 
        onSelect={setSelectedId} 
        onAddFile={handleAddFile}
        onRemove={(id) => {
          setModels(prev => prev.filter(m => m.id !== id));
          if (selectedId === id) setSelectedId(null);
        }}
      />
    </div>
  );
};

export default App;

