import React, { useState, Suspense, useCallback } from 'react';
import { Canvas, useThree } from '@react-three/fiber';
import { OrbitControls, PerspectiveCamera, Environment, ContactShadows, Float, Html } from '@react-three/drei';
import * as THREE from 'three';
import './types';
import Room from './components/Room';
import FBXModel from './components/FBXModel';
import UIOverlay from './components/UIOverlay';
import Sidebar from './components/Sidebar';
import { MaterialSettings, SceneModelInstance } from './types';

const App: React.FC = () => {
  const [models, setModels] = useState<SceneModelInstance[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [isDragging, setIsDragging] = useState(false);

  const createDefaultSettings = (): MaterialSettings => ({
    opacity: 1.0,
    metalness: 0.5,
    roughness: 0.5,
    emissiveIntensity: 0.0,
    color: '#ffffff',
    transparent: false,
    materialMappings: {},
    hoveredMaterial: null,
    metalnessUrl: null,
    roughnessUrl: null,
    transparencyUrl: null
  });

  const handleAddFile = (file: File) => {
    const url = URL.createObjectURL(file);
    const id = Math.random().toString(36).substr(2, 9);
    const newModel: SceneModelInstance = {
      id,
      name: file.name.replace('.fbx', ''),
      url,
      settings: createDefaultSettings(),
      detectedMaterials: [],
      position: [0, 0, 0]
    };
    setModels(prev => [...prev, newModel]);
    setSelectedId(id);
    setIsDragging(true); // Start dragging immediately for placement
  };

  const updateModelData = (id: string, updates: Partial<SceneModelInstance>) => {
    setModels(prev => prev.map(m => m.id === id ? { ...m, ...updates } : m));
  };

  const updateSelectedSettings = (newSettings: MaterialSettings) => {
    if (!selectedId) return;
    updateModelData(selectedId, { settings: newSettings });
  };

  const handlePointerMove = (e: any) => {
    if (!isDragging || !selectedId) return;

    // We want the intersection with the floor (y=0)
    // The Room component floor is at y=-5, let's aim for that or slightly above
    const intersect = e.intersections.find((i: any) => i.object.name === "floor-plane");
    if (intersect) {
      const { x, z } = intersect.point;
      updateModelData(selectedId, { position: [x, 0, z] });
    }
  };

  const handlePointerUp = () => {
    if (isDragging) setIsDragging(false);
  };

  const handleModelClick = (id: string) => {
    if (selectedId === id) {
      setIsDragging(true); // Toggle dragging on second click or hold
    } else {
      setSelectedId(id);
    }
  };

  const selectedModel = models.find(m => m.id === selectedId);

  return (
    <div className="relative w-screen h-screen overflow-hidden flex bg-[#171717]">
      {/* 3D Viewport */}
      <div className="flex-1 relative">
        <Canvas 
          shadows 
          dpr={[1, 2]} 
          gl={{ antialias: true, alpha: true }}
          onPointerMove={handlePointerMove}
          onPointerUp={handlePointerUp}
          onPointerLeave={handlePointerUp}
        >
          <PerspectiveCamera makeDefault position={[15, 12, 20]} fov={35} />

          <Suspense fallback={<Html center><div className="text-indigo-400 font-bold uppercase tracking-[0.4em] animate-pulse text-[10px]">Harmonizing Scene...</div></Html>}>
            <ambientLight intensity={0.4} />
            <spotLight position={[10, 20, 10]} angle={0.15} penumbra={1} intensity={3} castShadow color="#c4b5fd" />
            <pointLight position={[-10, 10, -10]} intensity={1} color="#312e81" />
            <Environment preset="night" />

            <Room />

            {/* Invisible large plane for raycasting movement */}
            <mesh 
              name="floor-plane" 
              rotation={[-Math.PI / 2, 0, 0]} 
              position={[0, -5, 0]} 
              visible={false}
            >
              <planeGeometry args={[500, 500]} />
            </mesh>

            {models.map((model) => {
              const isSelected = selectedId === model.id;

              return (
                <group 
                  key={model.id} 
                  position={model.position}
                  onPointerDown={(e) => {
                    e.stopPropagation();
                    handleModelClick(model.id);
                  }}
                >
                  <Float speed={isDragging && isSelected ? 0 : 1.5} rotationIntensity={0.1} floatIntensity={0.2}>
                    {/* Fixed: Replaced non-existent handleModelData with updateModelData to update detected materials */}
                    <FBXModel 
                      url={model.url} 
                      settings={model.settings} 
                      onMaterialsLoaded={(mats) => updateModelData(model.id, { detectedMaterials: mats })} 
                    />
                  </Float>

                  {isSelected && (
                    <group position={[0, -4.9, 0]}>
                      <mesh rotation={[-Math.PI/2, 0, 0]}>
                        <ringGeometry args={[2.5, 2.6, 64]} />
                        <meshBasicMaterial color={isDragging ? "#818cf8" : "#4b5563"} transparent opacity={0.4} />
                      </mesh>
                      {isDragging && (
                         <mesh rotation={[-Math.PI/2, 0, 0]}>
                           <circleGeometry args={[2.5, 64]} />
                           <meshBasicMaterial color="#818cf8" transparent opacity={0.05} />
                         </mesh>
                      )}
                    </group>
                  )}

                  <ContactShadows 
                    position={[0, -4.95, 0]} 
                    opacity={isSelected ? 0.8 : 0.4} 
                    scale={12} 
                    blur={2.5} 
                    far={10} 
                    color="#000000" 
                  />
                </group>
              );
            })}
          </Suspense>

          <OrbitControls 
            makeDefault 
            enableDamping 
            enabled={!isDragging} // Lock orbit while dragging model
            minDistance={5} 
            maxDistance={100} 
            dampingFactor={0.05} 
          />
        </Canvas>

        <UIOverlay 
          settings={selectedModel?.settings || createDefaultSettings()} 
          setSettings={updateSelectedSettings}
          onFileUpload={handleAddFile}
          onTextureUpload={(file, type, mat) => {
            const url = URL.createObjectURL(file);
            if (!selectedModel) return;
            const currentSettings = selectedModel.settings;
            let newSettings = { ...currentSettings };
            if (type === 'base') {
              const newMappings = { ...currentSettings.materialMappings };
              if (mat) newMappings[mat] = url;
              else if (currentSettings.hoveredMaterial) newMappings[currentSettings.hoveredMaterial] = url;
              else selectedModel.detectedMaterials.forEach(m => newMappings[m] = url);
              newSettings.materialMappings = newMappings;
            } else {
              const fieldMap = { metal: 'metalnessUrl', rough: 'roughnessUrl', transparency: 'transparencyUrl' } as const;
              newSettings = { ...newSettings, [fieldMap[type]]: url };
            }
            updateSelectedSettings(newSettings);
          }}
          detectedMaterials={selectedModel?.detectedMaterials || []}
          isModelLoaded={!!selectedId}
        />
      </div>

      <Sidebar 
        models={models} 
        selectedId={selectedId} 
        onSelect={setSelectedId} 
        onAddFile={handleAddFile}
        onRemove={(id) => {
          setModels(prev => prev.filter(m => m.id !== id));
          if (selectedId === id) setSelectedId(null);
        }}
      />
    </div>
  );
};

export default App;

import React, { useEffect, useMemo, useState, useRef } from 'react';
import { useLoader, useFrame } from '@react-three/fiber';
import { FBXLoader } from 'three/examples/jsm/loaders/FBXLoader';
import * as THREE from 'three';
import '../types';
import { MaterialSettings } from '../types';

interface FBXModelProps {
  url: string;
  settings: MaterialSettings;
  onMaterialsLoaded?: (materials: string[]) => void;
}

const FBXModel: React.FC<FBXModelProps> = ({ url, settings, onMaterialsLoaded }) => {
  const fbx = useLoader(FBXLoader, url);
  const [textureCache, setTextureCache] = useState<{ [url: string]: THREE.Texture }>({});
  const loaderRef = useRef(new THREE.TextureLoader());

  const [pulse, setPulse] = useState(0);
  useFrame((state) => {
    setPulse(Math.sin(state.clock.elapsedTime * 8) * 0.5 + 0.5);
  });

  // Texture Loading
  useEffect(() => {
    const urlsToLoad: { url: string; isColor: boolean }[] = [];
    (Object.values(settings.materialMappings) as string[]).forEach(u => {
      if (u) urlsToLoad.push({ url: u, isColor: true });
    });
    if (settings.metalnessUrl) urlsToLoad.push({ url: settings.metalnessUrl, isColor: false });
    if (settings.roughnessUrl) urlsToLoad.push({ url: settings.roughnessUrl, isColor: false });
    if (settings.transparencyUrl) urlsToLoad.push({ url: settings.transparencyUrl, isColor: false });

    urlsToLoad.forEach(({ url: u, isColor }) => {
      if (!textureCache[u]) {
        loaderRef.current.load(u, (tex) => {
          tex.colorSpace = isColor ? THREE.SRGBColorSpace : THREE.NoColorSpace;
          tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
          tex.needsUpdate = true;
          setTextureCache(prev => ({ ...prev, [u]: tex }));
        });
      }
    });
  }, [settings.materialMappings, settings.metalnessUrl, settings.roughnessUrl, settings.transparencyUrl]);

  // Material Detection
  useEffect(() => {
    const materialNames: string[] = [];
    fbx.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;
        const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
        materials.forEach((m) => {
          if (m) {
            if (!m.name) m.name = `Node_${materialNames.length}`;
            if (!materialNames.includes(m.name)) materialNames.push(m.name);
          }
        });
      }
    });
    if (onMaterialsLoaded) onMaterialsLoaded(materialNames);
  }, [fbx, url, onMaterialsLoaded]);

  // PBR Engine
  useEffect(() => {
    fbx.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;
        const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];

        const updatedMaterials = materials.map((mat) => {
          if (!mat.userData.pbr || mat.type !== 'MeshStandardMaterial') {
            const originalColor = (mat as any).color ? (mat as any).color.clone() : new THREE.Color(0xffffff);
            const newMat = new THREE.MeshStandardMaterial({
              name: mat.name,
              color: originalColor,
              side: THREE.DoubleSide
            });
            mat.userData.pbr = newMat;
            mat.userData.originalColor = originalColor;
          }

          const pbr = mat.userData.pbr as THREE.MeshStandardMaterial;
          const isHovered = settings.hoveredMaterial === mat.name;

          // Base Texture
          const texUrl = settings.materialMappings[mat.name];
          pbr.map = (texUrl && textureCache[texUrl]) ? textureCache[texUrl] : null;

          // Metal / Rough
          pbr.metalness = (settings.metalnessUrl && textureCache[settings.metalnessUrl]) ? 1 : settings.metalness;
          pbr.metalnessMap = (settings.metalnessUrl && textureCache[settings.metalnessUrl]) || null;
          pbr.roughness = (settings.roughnessUrl && textureCache[settings.roughnessUrl]) ? 1 : settings.roughness;
          pbr.roughnessMap = (settings.roughnessUrl && textureCache[settings.roughnessUrl]) || null;

          // Transparency
          const alphaTex = settings.transparencyUrl ? textureCache[settings.transparencyUrl] : null;
          if (settings.transparent || alphaTex || settings.opacity < 1.0) {
            pbr.transparent = true;
            pbr.opacity = settings.opacity;
            pbr.alphaMap = alphaTex;
            pbr.alphaTest = 0.5; 
            pbr.depthWrite = settings.opacity > 0.8; 
          } else {
            pbr.transparent = false;
            pbr.opacity = 1.0;
            pbr.alphaMap = null;
            pbr.alphaTest = 0;
            pbr.depthWrite = true;
          }

          if (isHovered) {
            pbr.emissive.setHex(0x94a3b8);
            pbr.emissiveIntensity = pulse * 0.2;
          } else {
            pbr.emissive.setHex(0x000000);
            pbr.emissiveIntensity = 0;
          }

          const baseColor = settings.color === '#ffffff' ? mat.userData.originalColor : new THREE.Color(settings.color);
          pbr.color.copy(baseColor);
          pbr.needsUpdate = true;
          return pbr;
        });

        mesh.material = Array.isArray(mesh.material) ? updatedMaterials : updatedMaterials[0];
      }
    });
  }, [fbx, settings, textureCache, pulse]);

  const processedModel = useMemo(() => {
    fbx.updateMatrixWorld(true);
    const box = new THREE.Box3().setFromObject(fbx);
    const size = box.getSize(new THREE.Vector3());
    const scale = 5 / (Math.max(size.x, size.y, size.z) || 1);
    fbx.scale.setScalar(scale);

    // Recalculate box after scale
    const scaledBox = new THREE.Box3().setFromObject(fbx);
    const center = scaledBox.getCenter(new THREE.Vector3());

    // Aligns bottom-center to origin [0,0,0]
    // So if the group is at y=-5, the bottom of the model is exactly at y=-5
    fbx.position.set(-center.x, -scaledBox.min.y, -center.z);

    return fbx;
  }, [fbx, url]);

  return <primitive object={processedModel} />;
};

export default FBXModel;

import React, { useState, Suspense, useCallback, useRef } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, PerspectiveCamera, Environment, ContactShadows, Float, Html } from '@react-three/drei';
import * as THREE from 'three';
import './types';
import Room from './components/Room';
import FBXModel from './components/FBXModel';
import UIOverlay from './components/UIOverlay';
import Sidebar from './components/Sidebar';
import { MaterialSettings, SceneModelInstance } from './types';

const App: React.FC = () => {
  const [models, setModels] = useState<SceneModelInstance[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [isDragging, setIsDragging] = useState(false);

  const createDefaultSettings = (): MaterialSettings => ({
    opacity: 1.0,
    metalness: 0.5,
    roughness: 0.5,
    emissiveIntensity: 0.0,
    color: '#ffffff',
    transparent: false,
    materialMappings: {},
    hoveredMaterial: null,
    metalnessUrl: null,
    roughnessUrl: null,
    transparencyUrl: null
  });

  const handleAddFile = (file: File) => {
    const url = URL.createObjectURL(file);
    const id = Math.random().toString(36).substr(2, 9);
    const newModel: SceneModelInstance = {
      id,
      name: file.name.replace('.fbx', ''),
      url,
      settings: createDefaultSettings(),
      detectedMaterials: [],
      position: [0, -5, 0] // Start at floor level
    };
    setModels(prev => [...prev, newModel]);
    setSelectedId(id);
    setIsDragging(true); // "Pick up" immediately
  };

  const updateModelData = (id: string, updates: Partial<SceneModelInstance>) => {
    setModels(prev => prev.map(m => m.id === id ? { ...m, ...updates } : m));
  };

  const handlePointerMove = (e: any) => {
    if (!isDragging || !selectedId) return;

    // Find floor intersection
    const intersect = e.intersections.find((i: any) => i.object.name === "floor-plane");
    if (intersect) {
      const { x, z } = intersect.point;
      updateModelData(selectedId, { position: [x, -5, z] });
    }
  };

  const handlePointerDown = (e: any) => {
    // If we were dragging and clicked anything, "Drop" the model
    if (isDragging) {
      setIsDragging(false);
      e.stopPropagation();
      return;
    }
  };

  const handleModelClick = (id: string) => {
    if (selectedId === id) {
      // Second click on selected model "Picks it up" again
      setIsDragging(true);
    } else {
      setSelectedId(id);
    }
  };

  const selectedModel = models.find(m => m.id === selectedId);

  return (
    <div className="relative w-screen h-screen overflow-hidden flex bg-[#171717]">
      {/* 3D Viewport */}
      <div className="flex-1 relative cursor-crosshair">
        <Canvas 
          shadows 
          dpr={[1, 2]} 
          gl={{ antialias: true, alpha: true }}
          onPointerMove={handlePointerMove}
          onPointerDown={handlePointerDown}
        >
          <PerspectiveCamera makeDefault position={[18, 15, 25]} fov={35} />

          <Suspense fallback={<Html center><div className="text-indigo-400 font-bold uppercase tracking-[0.4em] animate-pulse text-[10px]">Materializing Workspace...</div></Html>}>
            <ambientLight intensity={0.4} />
            <spotLight position={[15, 25, 15]} angle={0.2} penumbra={1} intensity={4} castShadow color="#c4b5fd" />
            <pointLight position={[-15, 10, -15]} intensity={1.5} color="#312e81" />
            <Environment preset="night" />

            <Room />

            {/* Invisible large plane for raycasting movement at floor level (y=-5) */}
            <mesh 
              name="floor-plane" 
              rotation={[-Math.PI / 2, 0, 0]} 
              position={[0, -5, 0]} 
              visible={false}
            >
              <planeGeometry args={[1000, 1000]} />
            </mesh>

            {models.map((model) => {
              const isSelected = selectedId === model.id;

              return (
                <group 
                  key={model.id} 
                  position={model.position}
                  onPointerDown={(e) => {
                    e.stopPropagation();
                    handleModelClick(model.id);
                  }}
                >
                  <Float speed={isDragging && isSelected ? 0 : 1.5} rotationIntensity={0.05} floatIntensity={0.1}>
                    <FBXModel 
                      url={model.url} 
                      settings={model.settings} 
                      onMaterialsLoaded={(mats) => updateModelData(model.id, { detectedMaterials: mats })} 
                    />
                  </Float>

                  {isSelected && (
                    <group position={[0, 0.05, 0]}>
                      {/* Selection Ring */}
                      <mesh rotation={[-Math.PI/2, 0, 0]}>
                        <ringGeometry args={[2.8, 3, 64]} />
                        <meshBasicMaterial color={isDragging ? "#818cf8" : "#4b5563"} transparent opacity={0.6} />
                      </mesh>
                      {/* Drop Shadow/Indicator when dragging */}
                      {isDragging && (
                         <mesh rotation={[-Math.PI/2, 0, 0]}>
                           <circleGeometry args={[2.8, 64]} />
                           <meshBasicMaterial color="#818cf8" transparent opacity={0.1} />
                         </mesh>
                      )}
                    </group>
                  )}

                  <ContactShadows 
                    position={[0, 0, 0]} 
                    opacity={isSelected ? 0.9 : 0.5} 
                    scale={15} 
                    blur={3} 
                    far={5} 
                    color="#000000" 
                  />
                </group>
              );
            })}
          </Suspense>

          <OrbitControls 
            makeDefault 
            enableDamping 
            enabled={!isDragging} // Lock orbit while placing or moving models
            minDistance={5} 
            maxDistance={120} 
            dampingFactor={0.05} 
          />
        </Canvas>

        <UIOverlay 
          settings={selectedModel?.settings || createDefaultSettings()} 
          setSettings={(newSettings) => {
            if (selectedId) updateModelData(selectedId, { settings: newSettings });
          }}
          onFileUpload={handleAddFile}
          onTextureUpload={(file, type, mat) => {
            const url = URL.createObjectURL(file);
            if (!selectedModel) return;
            const currentSettings = selectedModel.settings;
            let newSettings = { ...currentSettings };
            if (type === 'base') {
              const newMappings = { ...currentSettings.materialMappings };
              if (mat) newMappings[mat] = url;
              else if (currentSettings.hoveredMaterial) newMappings[currentSettings.hoveredMaterial] = url;
              else selectedModel.detectedMaterials.forEach(m => newMappings[m] = url);
              newSettings.materialMappings = newMappings;
            } else {
              const fieldMap = { metal: 'metalnessUrl', rough: 'roughnessUrl', transparency: 'transparencyUrl' } as const;
              newSettings = { ...newSettings, [fieldMap[type]]: url };
            }
            if (selectedId) updateModelData(selectedId, { settings: newSettings });
          }}
          detectedMaterials={selectedModel?.detectedMaterials || []}
          isModelLoaded={!!selectedId}
        />
      </div>

      <Sidebar 
        models={models} 
        selectedId={selectedId} 
        onSelect={(id) => {
            setSelectedId(id);
            setIsDragging(false); // Reset dragging when manually selecting from sidebar
        }} 
        onAddFile={handleAddFile}
        onRemove={(id) => {
          setModels(prev => prev.filter(m => m.id !== id));
          if (selectedId === id) setSelectedId(null);
        }}
      />
    </div>
  );
};

export default App;

