                        <meshBasicMaterial 
                           color="#4f46e5" 
                           transparent 
                           opacity={isDragging ? 0.03 : 0.01} 
                        />
                      </mesh>

                      {/* Concentric Design Rings */}
                      {[10, 30, 60, 100].map((radius, i) => (
                        <mesh key={i} rotation={[-Math.PI/2, 0, 0]}>
                          <ringGeometry args={[radius, radius + 0.1, 128]} />
                          <meshBasicMaterial 
