                        <circleGeometry args={[4, 64]} />
                        <meshBasicMaterial color="#818cf8" transparent opacity={0.05} />
                      </mesh>
                    </group>
                  )}

                  <ContactShadows 
                    position={[0, 0, 0]} 
                    opacity={isSelected ? 1 : 0.4} 
                    scale={20} 
                    blur={4} 
                    far={5} 
                    color="#000000" 
                  />
                </group>
              );
            })}
          </Suspense>

          <OrbitControls 
