            >
              <div className="flex flex-col min-w-0">
                <span className={`text-[10px] font-bold truncate tracking-tight ${selectedId === model.id ? 'text-zinc-100' : 'text-zinc-500'}`}>
                  {model.name}
                </span>
                <span className="text-[7px] text-zinc-600 uppercase font-black tracking-widest mt-0.5">{model.detectedMaterials.length} Materials</span>
              </div>
              <button 
                onClick={(e) => { e.stopPropagation(); onRemove(model.id); }}
                className="opacity-0 group-hover:opacity-100 p-1.5 text-zinc-600 hover:text-red-400 transition-all"
              >
                <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
              </button>
            </div>

            {/* Sub-menu for individual Base Color files */}
            {selectedId === model.id && (
              <div className="pl-3 space-y-1.5 animate-in slide-in-from-left-2 duration-300">
                {model.detectedMaterials.map((mat) => (
                  <div 
                    key={mat}
                    onMouseEnter={() => onHoverMaterial(mat)}
                    onMouseLeave={() => onHoverMaterial(null)}
                    className={`flex items-center justify-between p-2.5 rounded-lg border transition-all ${hoveredMaterial === mat ? 'bg-indigo-500/10 border-indigo-500/30' : 'bg-white/5 border-transparent'}`}
                  >
                    <span className="text-[8px] text-zinc-400 font-bold truncate flex-1 pr-2 uppercase">{mat}</span>
                    <label className="cursor-pointer shrink-0">
                      <div className="px-2 py-1 bg-indigo-500/10 hover:bg-indigo-500/30 border border-indigo-500/20 rounded text-[7px] font-black text-indigo-300 uppercase tracking-tighter transition-colors">
                        Base Color
                      </div>
                      <input 
                        type="file" 
                        className="hidden" 
                        accept="image/*" 
                        onChange={(e) => e.target.files?.[0] && onTextureUpload(e.target.files[0], 'base', mat)} 
                      />
                    </label>
                  </div>
                ))}
              </div>
            )}
          </div>
        ))}
      </div>

      <div className="mt-6 pt-6 border-t border-white/5 text-[9px] text-zinc-700 uppercase font-bold tracking-[0.2em] leading-relaxed text-center">
        Material Studio v2.7
      </div>
    </div>
  );
};

