              >
                <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
              </button>
            </div>

            {/* Material Specific Map Slots */}
            {selectedId === model.id && (
              <div className="pl-2 space-y-4 mt-2 animate-in slide-in-from-left-2 duration-300 max-h-[400px] overflow-y-auto custom-scroll pr-2">
                {model.detectedMaterials.map((mat) => (
                  <div 
                    key={mat}
                    onMouseEnter={() => onHoverMaterial(mat)}
                    onMouseLeave={() => onHoverMaterial(null)}
                    className={`p-3 rounded-xl border transition-all ${hoveredMaterial === mat ? 'bg-indigo-500/5 border-indigo-500/20' : 'bg-white/5 border-transparent'}`}
                  >
                    <div className="text-[8px] text-zinc-400 font-black truncate uppercase mb-2 tracking-widest">{mat}</div>

                    <div className="grid grid-cols-5 gap-1.5">
                      {[
                        { id: 'base', label: 'COL', tip: 'Base Color' },
                        { id: 'normal', label: 'NRM', tip: 'Normal Map' },
                        { id: 'metal', label: 'MET', tip: 'Metallic' },
                        { id: 'rough', label: 'RGH', tip: 'Roughness' },
                        { id: 'alpha', label: 'TRN', tip: 'Transparency' }
                      ].map((slot) => (
                        <label key={slot.id} className="cursor-pointer group/slot relative">
                          <div className={`aspect-square rounded-lg flex flex-col items-center justify-center transition-all border ${
                            (slot.id === 'base' && model.settings.materialMappings[mat]) ||
                            (slot.id === 'normal' && model.settings.normalMappings[mat]) ||
                            (slot.id === 'metal' && model.settings.metalMappings[mat]) ||
                            (slot.id === 'rough' && model.settings.roughMappings[mat]) ||
                            (slot.id === 'alpha' && model.settings.alphaMappings[mat])
                              ? 'bg-indigo-500/20 border-indigo-500/40 shadow-[0_0_10px_rgba(99,102,241,0.2)]' : 'bg-zinc-800/50 border-white/5 hover:bg-zinc-700/50'
                          }`}>
                            <span className="text-[7px] font-black tracking-tighter text-zinc-500 group-hover/slot:text-indigo-400">{slot.label}</span>
                            <div className={`w-1 h-1 rounded-full mt-1 ${
                                (slot.id === 'base' && model.settings.materialMappings[mat]) ||
                                (slot.id === 'normal' && model.settings.normalMappings[mat]) ||
                                (slot.id === 'metal' && model.settings.metalMappings[mat]) ||
                                (slot.id === 'rough' && model.settings.roughMappings[mat]) ||
                                (slot.id === 'alpha' && model.settings.alphaMappings[mat])
                                ? 'bg-indigo-400 animate-pulse' : 'bg-zinc-600 opacity-0 group-hover/slot:opacity-100'
                            }`} />
                          </div>
                          <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 px-2 py-1 bg-black text-[6px] text-white rounded opacity-0 group-hover/slot:opacity-100 pointer-events-none whitespace-nowrap z-30 uppercase font-black">
                            {slot.tip}
                          </div>
                          <input 
                            type="file" 
                            className="hidden" 
                            accept="image/*" 
                            onChange={(e) => e.target.files?.[0] && onTextureUpload(e.target.files[0], slot.id, mat)} 
                          />
                        </label>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        ))}
      </div>

      <div className="mt-6 pt-6 border-t border-white/5 text-[9px] text-zinc-700 uppercase font-bold tracking-[0.2em] leading-relaxed text-center">
        Material Studio v3.1
      </div>
    </div>
  );
};

