import React, { useEffect, useMemo, useState, useRef } from 'react';
import { useLoader, useFrame } from '@react-three/fiber';
import { FBXLoader } from 'three/examples/jsm/loaders/FBXLoader';
import * as THREE from 'three';
import '../types';
import { MaterialSettings } from '../types';

interface FBXModelProps {
  url: string;
  settings: MaterialSettings;
  onMaterialsLoaded?: (materials: string[]) => void;
}

const FBXModel: React.FC<FBXModelProps> = ({ url, settings, onMaterialsLoaded }) => {
  const fbx = useLoader(FBXLoader, url);
  const [textureCache, setTextureCache] = useState<{ [url: string]: THREE.Texture }>({});
  const loaderRef = useRef(new THREE.TextureLoader());

  const [pulse, setPulse] = useState(0);
  useFrame((state) => {
    setPulse(Math.sin(state.clock.elapsedTime * 8) * 0.5 + 0.5);
  });

  // Texture Loading
  useEffect(() => {
    const urlsToLoad: { url: string; isColor: boolean }[] = [];

    const maps = [
      { obj: settings.materialMappings, color: true },
      { obj: settings.normalMappings, color: false },
      { obj: settings.metalMappings, color: false },
      { obj: settings.roughMappings, color: false },
      { obj: settings.alphaMappings, color: false }
    ];

    maps.forEach(({ obj, color }) => {
      Object.values(obj).forEach(u => {
        if (u) urlsToLoad.push({ url: u as string, isColor: color });
      });
    });

    if (settings.metalnessUrl) urlsToLoad.push({ url: settings.metalnessUrl as string, isColor: false });
    if (settings.roughnessUrl) urlsToLoad.push({ url: settings.roughnessUrl as string, isColor: false });
    if (settings.transparencyUrl) urlsToLoad.push({ url: settings.transparencyUrl as string, isColor: false });
    if (settings.shadowUrl) urlsToLoad.push({ url: settings.shadowUrl as string, isColor: false });
    if (settings.eyesUrl) urlsToLoad.push({ url: settings.eyesUrl as string, isColor: true });

    urlsToLoad.forEach(({ url: u, isColor }) => {
      if (!textureCache[u]) {
        loaderRef.current.load(u, (tex) => {
          tex.colorSpace = isColor ? THREE.SRGBColorSpace : THREE.NoColorSpace;
          tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
          tex.needsUpdate = true;
          setTextureCache(prev => ({ ...prev, [u]: tex }));
        });
      }
    });
  }, [settings]);

  // Material Detection
  useEffect(() => {
    const materialNames: string[] = [];
    fbx.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;
        const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
        materials.forEach((m) => {
          if (m) {
            if (!m.name) m.name = `Node_${materialNames.length}`;
            if (!materialNames.includes(m.name)) materialNames.push(m.name);
          }
        });
      }
    });
    if (onMaterialsLoaded) onMaterialsLoaded(materialNames);
  }, [fbx, url, onMaterialsLoaded]);

  // PBR Engine
  useEffect(() => {
    fbx.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;
        const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];

        const updatedMaterials = materials.map((mat) => {
          if (!mat.userData.pbr || mat.type !== 'MeshStandardMaterial') {
            const originalColor = (mat as any).color ? (mat as any).color.clone() : new THREE.Color(0xffffff);
            const newMat = new THREE.MeshStandardMaterial({
              name: mat.name,
              color: originalColor,
              side: THREE.DoubleSide
            });
            mat.userData.pbr = newMat;
            mat.userData.originalColor = originalColor;
          }

          const pbr = mat.userData.pbr as THREE.MeshStandardMaterial;
          const isHovered = settings.hoveredMaterial === mat.name;

          pbr.map = settings.materialMappings[mat.name] ? textureCache[settings.materialMappings[mat.name]] : null;
          pbr.normalMap = settings.normalMappings[mat.name] ? textureCache[settings.normalMappings[mat.name]] : null;
          pbr.normalScale.set(1, 1);

          const metalTexUrl = settings.metalMappings[mat.name] || settings.metalnessUrl;
          pbr.metalness = metalTexUrl ? 1 : settings.metalness;
          pbr.metalnessMap = (metalTexUrl && textureCache[metalTexUrl]) || null;

          const roughTexUrl = settings.roughMappings[mat.name] || settings.roughnessUrl;
          pbr.roughness = roughTexUrl ? 1 : settings.roughness;
          pbr.roughnessMap = (roughTexUrl && textureCache[roughTexUrl]) || null;

          pbr.aoMap = (settings.shadowUrl && textureCache[settings.shadowUrl]) || null;
          pbr.aoMapIntensity = settings.shadowUrl ? 1.0 : 0.0;

          if (settings.eyesUrl && textureCache[settings.eyesUrl]) {
            pbr.emissiveMap = textureCache[settings.eyesUrl];
            pbr.emissive = new THREE.Color(0xffffff);
            pbr.emissiveIntensity = settings.emissiveIntensity || 1.0;
          } else {
            pbr.emissiveMap = null;
          }

          const alphaTexUrl = settings.alphaMappings[mat.name] || settings.transparencyUrl;
          const alphaTex = alphaTexUrl ? textureCache[alphaTexUrl] : null;

          if (settings.transparent || alphaTex || settings.opacity < 1.0) {
            pbr.transparent = true;
            pbr.opacity = settings.opacity;
            pbr.alphaMap = alphaTex;
            pbr.alphaTest = 0.5; 
            pbr.depthWrite = settings.opacity > 0.8; 
          } else {
            pbr.transparent = false;
            pbr.opacity = 1.0;
            pbr.alphaMap = null;
            pbr.alphaTest = 0;
            pbr.depthWrite = true;
          }

          if (isHovered) {
            pbr.emissive.setHex(0x94a3b8);
            pbr.emissiveIntensity = Math.max(pbr.emissiveIntensity, pulse * 0.2);
          } else if (!settings.eyesUrl) {
            pbr.emissive.setHex(0x000000);
            pbr.emissiveIntensity = 0;
          }

          const baseColor = settings.color === '#ffffff' ? mat.userData.originalColor : new THREE.Color(settings.color);
          pbr.color.copy(baseColor);
          pbr.needsUpdate = true;
          return pbr;
        });

        mesh.material = Array.isArray(mesh.material) ? updatedMaterials : updatedMaterials[0];
      }
    });
  }, [fbx, settings, textureCache, pulse]);

  const processedModel = useMemo(() => {
    fbx.updateMatrixWorld(true);
    const box = new THREE.Box3().setFromObject(fbx);
    const size = new THREE.Vector3();
    box.getSize(size);
    const maxDim = Math.max(size.x, size.y, size.z);
    const targetSize = 35; 
    const scaleFactor = targetSize / maxDim;
    fbx.scale.setScalar(scaleFactor);

    // מרכוז אבסולוטי - המרכז הגיאומטרי של המודל יהיה ב-0,0,0
    const scaledBox = new THREE.Box3().setFromObject(fbx);
    const center = scaledBox.getCenter(new THREE.Vector3());
    fbx.position.set(-center.x, -center.y, -center.z); 

    return fbx;
  }, [fbx, url]);

  return <primitive object={processedModel} />;
};

export default FBXModel;

import React, { useState, Suspense, useCallback, useRef } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, PerspectiveCamera, Environment, ContactShadows, Float, Html } from '@react-three/drei';
import * as THREE from 'three';
import './types';
import Room from './components/Room';
import FBXModel from './components/FBXModel';
import UIOverlay from './components/UIOverlay';
import Sidebar from './components/Sidebar';
import { MaterialSettings, SceneModelInstance } from './types';

const App: React.FC = () => {
  const [models, setModels] = useState<SceneModelInstance[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [isMoveMode, setIsMoveMode] = useState(false);
  const controlsRef = useRef<any>(null);

  const createDefaultSettings = (): MaterialSettings => ({
    opacity: 1.0,
    metalness: 0.5,
    roughness: 0.5,
    emissiveIntensity: 0.0,
    color: '#ffffff',
    transparent: false,
    materialMappings: {},
    normalMappings: {},
    metalMappings: {},
    roughMappings: {},
    alphaMappings: {},
    hoveredMaterial: null,
    metalnessUrl: null,
    roughnessUrl: null,
    transparencyUrl: null,
    shadowUrl: null,
    eyesUrl: null
  });

  const handleAddFile = (file: File) => {
    const url = URL.createObjectURL(file);
    const id = Math.random().toString(36).substr(2, 9);
    const newModel: SceneModelInstance = {
      id,
      name: file.name.replace('.fbx', ''),
      url,
      settings: createDefaultSettings(),
      detectedMaterials: [],
      position: [0, 0, 0] // המודל מתחיל במרכז החלל
    };
    setModels(prev => [...prev, newModel]);
    setSelectedId(id);
    // איפוס מצלמה למודל החדש
    if (controlsRef.current) {
      controlsRef.current.reset();
    }
  };

  const updateModelData = (id: string, updates: Partial<SceneModelInstance>) => {
    setModels(prev => prev.map(m => m.id === id ? { ...m, ...updates } : m));
  };

  const handlePointerDown = (e: any) => {
    if (isMoveMode) {
      setIsMoveMode(false);
    }
  };

  const handleModelClick = (id: string) => {
    setSelectedId(id);
  };

  const handleCameraAction = (action: string) => {
    if (!controlsRef.current) return;
    const controls = controlsRef.current;
    const moveStep = 5;
    const zoomStep = 0.8;

    switch (action) {
      case 'zoomIn':
        controls.object.position.multiplyScalar(zoomStep);
        break;
      case 'zoomOut':
        controls.object.position.divideScalar(zoomStep);
        break;
      case 'panLeft':
        controls.target.x -= moveStep;
        break;
      case 'panRight':
        controls.target.x += moveStep;
        break;
      case 'panUp':
        controls.target.y += moveStep;
        break;
      case 'panDown':
        controls.target.y -= moveStep;
        break;
      case 'reset':
        controls.reset();
        controls.target.set(0, 0, 0);
        break;
    }
    controls.update();
  };

  const selectedModel = models.find(m => m.id === selectedId);

  const handleTextureUpload = (file: File, type: string, mat?: string) => {
    const url = URL.createObjectURL(file);
    if (!selectedModel) return;
    const currentSettings = selectedModel.settings;
    let newSettings = { ...currentSettings };

    if (mat) {
      if (type === 'base') newSettings.materialMappings = { ...currentSettings.materialMappings, [mat]: url };
      if (type === 'normal') newSettings.normalMappings = { ...currentSettings.normalMappings, [mat]: url };
      if (type === 'metal') newSettings.metalMappings = { ...currentSettings.metalMappings, [mat]: url };
      if (type === 'rough') newSettings.roughMappings = { ...currentSettings.roughMappings, [mat]: url };
      if (type === 'alpha') newSettings.alphaMappings = { ...currentSettings.alphaMappings, [mat]: url };
    } else {
      const fieldMap = { 
        metal: 'metalnessUrl', 
        rough: 'roughnessUrl', 
        transparency: 'transparencyUrl',
        shadow: 'shadowUrl',
        eyes: 'eyesUrl'
      } as const;
      if (type in fieldMap) {
        newSettings = { ...newSettings, [fieldMap[type as keyof typeof fieldMap]]: url };
      }
    }

    updateModelData(selectedModel.id, { settings: newSettings });
  };

  return (
    <div className="relative w-screen h-screen overflow-hidden flex bg-[#0a0a0a]">
      <div className="flex-1 relative cursor-crosshair">
        <Canvas 
          shadows 
          dpr={[1, 2]} 
          gl={{ antialias: true, alpha: true }}
          onPointerDown={handlePointerDown}
        >
          <PerspectiveCamera makeDefault position={[40, 30, 70]} fov={35} />
          <Suspense fallback={<Html center><div className="text-indigo-500 font-bold uppercase tracking-[0.5em] animate-pulse text-[10px]">Architecting...</div></Html>}>
            <ambientLight intensity={0.5} />
            <spotLight position={[50, 50, 50]} angle={0.15} penumbra={1} intensity={2} castShadow />
            <pointLight position={[-50, -50, -50]} intensity={1} color="#4f46e5" />
            <Environment preset="studio" />
            <Room />
            {models.map((model) => {
              const isSelected = selectedId === model.id;
              return (
                <group key={model.id} position={model.position} onPointerDown={(e) => { e.stopPropagation(); handleModelClick(model.id); }}>
                  <Float speed={1.5} rotationIntensity={0.2} floatIntensity={0.2}>
                    <FBXModel url={model.url} settings={model.settings} onMaterialsLoaded={(mats) => updateModelData(model.id, { detectedMaterials: mats })} />
                  </Float>
                  {isSelected && (
                    <group position={[0, 0, 0]}>
                      {/* טבעת סימון מרכזית */}
                      <mesh rotation={[-Math.PI/2, 0, 0]}><ringGeometry args={[19, 19.8, 64]} /><meshBasicMaterial color="#818cf8" transparent opacity={0.3} /></mesh>
                    </group>
                  )}
                </group>
              );
            })}
          </Suspense>
          <OrbitControls 
            ref={controlsRef}
            makeDefault 
            enableDamping 
            enabled={true} 
            minDistance={5} 
            maxDistance={500} 
          />
        </Canvas>
        <UIOverlay 
          settings={selectedModel?.settings || createDefaultSettings()} 
          setSettings={(newSettings) => { if (selectedId) updateModelData(selectedId, { settings: newSettings }); }}
          onFileUpload={handleAddFile}
          onTextureUpload={handleTextureUpload}
          onCameraAction={handleCameraAction}
          detectedMaterials={selectedModel?.detectedMaterials || []}
          isModelLoaded={!!selectedId}
          isMoveMode={isMoveMode}
          setMoveMode={setIsMoveMode}
        />
      </div>
      <Sidebar 
        models={models} 
        selectedId={selectedId} 
        onSelect={(id) => { setSelectedId(id); setIsMoveMode(false); }} 
        onAddFile={handleAddFile}
        onRemove={(id) => { setModels(prev => prev.filter(m => m.id !== id)); if (selectedId === id) setSelectedId(null); }}
        onTextureUpload={handleTextureUpload}
        hoveredMaterial={selectedModel?.settings.hoveredMaterial || null}
        onHoverMaterial={(mat) => {
          if (selectedId) {
            const current = models.find(m => m.id === selectedId);
            if (current) updateModelData(selectedId, { settings: { ...current.settings, hoveredMaterial: mat } });
          }
        }}
      />
    </div>
  );
};

export default App;

import React, { useState, Suspense, useCallback, useRef } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, PerspectiveCamera, Environment, ContactShadows, Float, Html } from '@react-three/drei';
import * as THREE from 'three';
import './types';
import Room from './components/Room';
import FBXModel from './components/FBXModel';
import UIOverlay from './components/UIOverlay';
import Sidebar from './components/Sidebar';
import { MaterialSettings, SceneModelInstance } from './types';

const App: React.FC = () => {
  const [models, setModels] = useState<SceneModelInstance[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [isMoveMode, setIsMoveMode] = useState(false);
  const controlsRef = useRef<any>(null);

  const createDefaultSettings = (): MaterialSettings => ({
    opacity: 1.0,
    metalness: 0.5,
    roughness: 0.5,
    emissiveIntensity: 0.0,
    color: '#ffffff',
    transparent: false,
    materialMappings: {},
    normalMappings: {},
    metalMappings: {},
    roughMappings: {},
    alphaMappings: {},
    hoveredMaterial: null,
    metalnessUrl: null,
    roughnessUrl: null,
    transparencyUrl: null,
    shadowUrl: null,
    eyesUrl: null
  });

  const handleAddFile = (file: File) => {
    const url = URL.createObjectURL(file);
    const id = Math.random().toString(36).substr(2, 9);
    const newModel: SceneModelInstance = {
      id,
      name: file.name.replace('.fbx', ''),
      url,
      settings: createDefaultSettings(),
      detectedMaterials: [],
      position: [0, 0, 0]
    };
    setModels(prev => [...prev, newModel]);
    setSelectedId(id);
    if (controlsRef.current) {
      controlsRef.current.reset();
    }
  };

  const updateModelData = (id: string, updates: Partial<SceneModelInstance>) => {
    setModels(prev => prev.map(m => m.id === id ? { ...m, ...updates } : m));
  };

  const handlePointerDown = (e: any) => {
    if (isMoveMode) {
      setIsMoveMode(false);
    }
  };

  const handleModelClick = (id: string) => {
    setSelectedId(id);
  };

  const handleCameraAction = (action: string) => {
    if (!controlsRef.current) return;
    const controls = controlsRef.current;
    const moveStep = 5;
    const zoomStep = 0.8;

    switch (action) {
      case 'zoomIn':
        controls.object.position.multiplyScalar(zoomStep);
        break;
      case 'zoomOut':
        controls.object.position.divideScalar(zoomStep);
        break;
      case 'panLeft':
        controls.target.x -= moveStep;
        break;
      case 'panRight':
        controls.target.x += moveStep;
        break;
      case 'panUp':
        controls.target.y += moveStep;
        break;
      case 'panDown':
        controls.target.y -= moveStep;
        break;
      case 'reset':
        controls.reset();
        controls.target.set(0, 0, 0);
        break;
    }
    controls.update();
  };

  const selectedModel = models.find(m => m.id === selectedId);

  const handleTextureUpload = (file: File, type: string, mat?: string) => {
    const url = URL.createObjectURL(file);
    if (!selectedModel) return;
    const currentSettings = selectedModel.settings;
    let newSettings = { ...currentSettings };

    if (mat) {
      if (type === 'base') newSettings.materialMappings = { ...currentSettings.materialMappings, [mat]: url };
      if (type === 'normal') newSettings.normalMappings = { ...currentSettings.normalMappings, [mat]: url };
      if (type === 'metal') newSettings.metalMappings = { ...currentSettings.metalMappings, [mat]: url };
      if (type === 'rough') newSettings.roughMappings = { ...currentSettings.roughMappings, [mat]: url };
      if (type === 'alpha') newSettings.alphaMappings = { ...currentSettings.alphaMappings, [mat]: url };
    } else {
      const fieldMap = { 
        metal: 'metalnessUrl', 
        rough: 'roughnessUrl', 
        transparency: 'transparencyUrl',
        shadow: 'shadowUrl',
        eyes: 'eyesUrl'
      } as const;
      if (type in fieldMap) {
        newSettings = { ...newSettings, [fieldMap[type as keyof typeof fieldMap]]: url };
      }
    }

    updateModelData(selectedModel.id, { settings: newSettings });
  };

  return (
    <div className="relative w-screen h-screen overflow-hidden flex bg-[#fdfbf7]">
      <div className="flex-1 relative cursor-crosshair">
        <Canvas 
          shadows 
          dpr={[1, 2]} 
          gl={{ antialias: true, alpha: true }}
          onPointerDown={handlePointerDown}
        >
          <PerspectiveCamera makeDefault position={[40, 30, 70]} fov={35} />
          <Suspense fallback={<Html center><div className="text-indigo-600 font-bold uppercase tracking-[0.5em] animate-pulse text-[10px]">Architecting...</div></Html>}>
            <ambientLight intensity={0.8} />
            <spotLight position={[50, 50, 50]} angle={0.15} penumbra={1} intensity={1.5} castShadow />
            <pointLight position={[-50, -50, -50]} intensity={0.8} color="#818cf8" />
            <Environment preset="city" />
            <Room />
            {models.map((model) => {
              const isSelected = selectedId === model.id;
              return (
                <group key={model.id} position={model.position} onPointerDown={(e) => { e.stopPropagation(); handleModelClick(model.id); }}>
                  <Float speed={1.5} rotationIntensity={0.2} floatIntensity={0.2}>
                    <FBXModel url={model.url} settings={model.settings} onMaterialsLoaded={(mats) => updateModelData(model.id, { detectedMaterials: mats })} />
                  </Float>
                  {isSelected && (
                    <group position={[0, 0, 0]}>
                      <mesh rotation={[-Math.PI/2, 0, 0]}><ringGeometry args={[19, 19.8, 64]} /><meshBasicMaterial color="#6366f1" transparent opacity={0.4} /></mesh>
                    </group>
                  )}
                </group>
              );
            })}
          </Suspense>
          <OrbitControls 
            ref={controlsRef}
            makeDefault 
            enableDamping 
            enabled={true} 
            minDistance={5} 
            maxDistance={500} 
          />
        </Canvas>
        <UIOverlay 
          settings={selectedModel?.settings || createDefaultSettings()} 
          setSettings={(newSettings) => { if (selectedId) updateModelData(selectedId, { settings: newSettings }); }}
          onFileUpload={handleAddFile}
          onTextureUpload={handleTextureUpload}
          onCameraAction={handleCameraAction}
          detectedMaterials={selectedModel?.detectedMaterials || []}
          isModelLoaded={!!selectedId}
          isMoveMode={isMoveMode}
          setMoveMode={setIsMoveMode}
        />
      </div>
      <Sidebar 
        models={models} 
        selectedId={selectedId} 
        onSelect={(id) => { setSelectedId(id); setIsMoveMode(false); }} 
        onAddFile={handleAddFile}
        onRemove={(id) => { setModels(prev => prev.filter(m => m.id !== id)); if (selectedId === id) setSelectedId(null); }}
        onTextureUpload={handleTextureUpload}
        hoveredMaterial={selectedModel?.settings.hoveredMaterial || null}
        onHoverMaterial={(mat) => {
          if (selectedId) {
            const current = models.find(m => m.id === selectedId);
            if (current) updateModelData(selectedId, { settings: { ...current.settings, hoveredMaterial: mat } });
          }
        }}
      />
    </div>
  );
};

export default App;

import React from 'react';
import { SceneModelInstance } from '../types';

interface SidebarProps {
  models: SceneModelInstance[];
  selectedId: string | null;
  onSelect: (id: string) => void;
  onAddFile: (file: File) => void;
  onRemove: (id: string) => void;
  onTextureUpload: (file: File, type: string, matName: string) => void;
  onHoverMaterial: (matName: string | null) => void;
  hoveredMaterial: string | null;
}

const Sidebar: React.FC<SidebarProps> = ({ 
  models, selectedId, onSelect, onAddFile, onRemove, onTextureUpload, onHoverMaterial, hoveredMaterial 
}) => {
  const selectedModel = models.find(m => m.id === selectedId);

  const handleBatchFiles = (e: React.ChangeEvent<HTMLInputElement>, type: string) => {
    const files = e.target.files;
    if (!files || !selectedModel) return;
    const fileArray = Array.from(files) as File[];

    fileArray.forEach(file => {
      const fileName = file.name.toLowerCase();
      const matchedMat = selectedModel.detectedMaterials.find(mat => {
        const lowMat = mat.toLowerCase();
        return fileName.includes(lowMat) || lowMat.includes(fileName.split('.')[0]);
      });

      if (matchedMat) {
        onTextureUpload(file, type, matchedMat);
      }
    });
  };

  return (
    <div className="w-96 h-full glass-panel border-l border-black/5 flex flex-col p-6 pointer-events-auto z-20 overflow-y-auto custom-scroll">

      {/* 1. MODEL IMPORT */}
      <div className="mb-6">
        <h2 className="text-zinc-400 text-[9px] font-black uppercase tracking-[0.4em] mb-3">Model Asset</h2>
        <label className="flex flex-col items-center justify-center w-full py-8 bg-indigo-500/5 border-2 border-dashed border-indigo-500/20 rounded-2xl hover:border-indigo-500 hover:bg-indigo-500/10 cursor-pointer transition-all group">
          <div className="mb-2 p-2.5 bg-indigo-500/10 rounded-xl group-hover:scale-110 transition-transform">
            <svg className="w-5 h-5 text-indigo-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M10 14l2-2m0 0l2 2m-2-2v6" />
            </svg>
          </div>
          <span className="text-[10px] font-black text-zinc-800 uppercase tracking-[0.2em]">Import FBX</span>
          <input type="file" className="hidden" accept=".fbx" onChange={(e) => e.target.files?.[0] && onAddFile(e.target.files[0])} />
        </label>
      </div>

      {/* 2. BATCH UPLOAD SECTION */}
      {selectedId && (
        <div className="mb-8 p-4 bg-black/5 rounded-2xl border border-black/5">
          <h2 className="text-indigo-600 text-[9px] font-black uppercase tracking-[0.4em] mb-4">Batch Import (Auto-Map)</h2>
          <div className="grid grid-cols-2 gap-2">
            {[
              { id: 'base', label: 'All Base' },
              { id: 'normal', label: 'All Normal' },
              { id: 'metal', label: 'All Metal' },
              { id: 'rough', label: 'All Rough' },
              { id: 'alpha', label: 'All Alpha' }
            ].map((btn) => (
              <label key={btn.id} className="cursor-pointer group">
                <div className="flex items-center gap-2 px-3 py-2 bg-indigo-500/10 hover:bg-indigo-500/20 border border-indigo-500/20 rounded-lg transition-all">
                  <svg className="w-3 h-3 text-indigo-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-8l-4-4m0 0L8 8m4-4v12" />
                  </svg>
                  <span className="text-[7px] font-black uppercase text-indigo-800 tracking-widest">{btn.label}</span>
                </div>
                <input type="file" multiple className="hidden" accept="image/*" onChange={(e) => handleBatchFiles(e, btn.id)} />
              </label>
            ))}
          </div>
        </div>
      )}

      {/* 3. ACTIVE OBJECTS */}
      <div className="flex-1 space-y-4">
        <h3 className="text-zinc-400 text-[8px] font-black uppercase tracking-[0.3em] mb-2 border-b border-black/5 pb-2">Active Hierarchy</h3>
        {models.map((model) => (
          <div key={model.id} className="space-y-2">
            <div 
              onClick={() => onSelect(model.id)}
              className={`group p-4 rounded-xl border transition-all cursor-pointer flex items-center justify-between ${selectedId === model.id ? 'bg-indigo-600/5 border-indigo-500/20 shadow-sm' : 'bg-black/5 border-transparent hover:bg-black/10'}`}
            >
              <div className="flex flex-col min-w-0">
                <span className={`text-[10px] font-bold truncate tracking-tight ${selectedId === model.id ? 'text-indigo-900' : 'text-zinc-600'}`}>
                  {model.name}
                </span>
                <span className="text-[7px] text-zinc-400 uppercase font-black tracking-widest mt-0.5">{model.detectedMaterials.length} Materials</span>
              </div>
              <button onClick={(e) => { e.stopPropagation(); onRemove(model.id); }} className="opacity-0 group-hover:opacity-100 p-1.5 text-zinc-400 hover:text-red-500 transition-all">
                <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
              </button>
            </div>

            {selectedId === model.id && (
              <div className="pl-2 space-y-4 mt-2 animate-in slide-in-from-left-2 duration-300 max-h-[400px] overflow-y-auto custom-scroll pr-2">
                {model.detectedMaterials.map((mat) => (
                  <div key={mat} onMouseEnter={() => onHoverMaterial(mat)} onMouseLeave={() => onHoverMaterial(null)} className={`p-3 rounded-xl border transition-all ${hoveredMaterial === mat ? 'bg-indigo-500/5 border-indigo-500/10' : 'bg-black/5 border-transparent'}`}>
                    <div className="text-[8px] text-zinc-500 font-black truncate uppercase mb-2 tracking-widest">{mat}</div>
                    <div className="grid grid-cols-5 gap-1.5">
                      {[
                        { id: 'base', label: 'COL', tip: 'Base Color' },
                        { id: 'normal', label: 'NRM', tip: 'Normal Map' },
                        { id: 'metal', label: 'MET', tip: 'Metallic' },
                        { id: 'rough', label: 'RGH', tip: 'Roughness' },
                        { id: 'alpha', label: 'TRN', tip: 'Transparency' }
                      ].map((slot) => (
                        <label key={slot.id} className="cursor-pointer group/slot relative">
                          <div className={`aspect-square rounded-lg flex flex-col items-center justify-center transition-all border ${
                            (slot.id === 'base' && model.settings.materialMappings[mat]) ||
                            (slot.id === 'normal' && model.settings.normalMappings[mat]) ||
                            (slot.id === 'metal' && model.settings.metalMappings[mat]) ||
                            (slot.id === 'rough' && model.settings.roughMappings[mat]) ||
                            (slot.id === 'alpha' && model.settings.alphaMappings[mat])
                              ? 'bg-indigo-500/20 border-indigo-500/30' : 'bg-white/80 border-black/5 hover:bg-white'
                          }`}>
                            <span className="text-[7px] font-black tracking-tighter text-zinc-500 group-hover/slot:text-indigo-600">{slot.label}</span>
                          </div>
                          <input type="file" className="hidden" accept="image/*" onChange={(e) => e.target.files?.[0] && onTextureUpload(e.target.files[0], slot.id, mat)} />
                        </label>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

