              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M20 12H4" /></svg>
            </button>
            <button onClick={() => onCameraAction('zoomIn')} className="flex-1 py-2 bg-indigo-600/10 hover:bg-indigo-600/20 rounded-xl text-indigo-600 transition-all flex justify-center">
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4" /></svg>
            </button>
          </div>
        </div>
      </div>

      {!isModelLoaded && (
        <div className="flex-1 flex flex-col items-center justify-center animate-in fade-in zoom-in duration-1000">
          <div className="text-center">
            <h2 className="text-zinc-500 text-[11px] font-bold uppercase tracking-[0.5em] mb-3">Workspace Empty</h2>
            <p className="text-zinc-400 text-[9px] font-medium uppercase tracking-[0.3em]">Import an asset to begin</p>
          </div>
        </div>
      )}
    </div>
  );
};

export default UIOverlay;

import React from 'react';
import { ThreeElements } from '@react-three/fiber';

declare global {
  namespace React {
    namespace JSX {
      interface IntrinsicElements extends ThreeElements {}
    }
  }
}

export interface MaterialSettings {
  opacity: number;
  metalness: number;
  roughness: number;
  emissiveIntensity: number;
  color: string;
  transparent: boolean;
  materialMappings: Record<string, string>; // Base Color mappings
  normalMappings: Record<string, string>;   // Normal map mappings
  metalMappings: Record<string, string>;    // Metalness mappings
  roughMappings: Record<string, string>;    // Roughness mappings
  alphaMappings: Record<string, string>;    // Opacity/Alpha mappings
  hoveredMaterial: string | null;
  metalnessUrl?: string | null;
  roughnessUrl?: string | null;
  transparencyUrl?: string | null;
  shadowUrl?: string | null;
  eyesUrl?: string | null;
  // Exploded view controls
  isExploded: boolean;
  explodeFactor: number;
}

export interface SceneModelInstance {
  id: string;
  name: string;
  url: string;
  settings: MaterialSettings;
  detectedMaterials: string[];
  position: [number, number, number];
}

export interface ModelMetadata {
  name: string;
  size: string;
  triangleCount: number;
  materials: string[];
}

import React, { useState, Suspense, useCallback, useRef } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, PerspectiveCamera, Environment, ContactShadows, Float, Html } from '@react-three/drei';
import * as THREE from 'three';
import './types';
import Room from './components/Room';
import FBXModel from './components/FBXModel';
import UIOverlay from './components/UIOverlay';
import Sidebar from './components/Sidebar';
import { MaterialSettings, SceneModelInstance } from './types';

const App: React.FC = () => {
  const [models, setModels] = useState<SceneModelInstance[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [isMoveMode, setIsMoveMode] = useState(false);
  const controlsRef = useRef<any>(null);

  const createDefaultSettings = (): MaterialSettings => ({
    opacity: 1.0,
    metalness: 0.5,
    roughness: 0.5,
    emissiveIntensity: 0.0,
    color: '#ffffff',
    transparent: false,
    materialMappings: {},
    normalMappings: {},
    metalMappings: {},
    roughMappings: {},
    alphaMappings: {},
    hoveredMaterial: null,
    metalnessUrl: null,
    roughnessUrl: null,
    transparencyUrl: null,
    shadowUrl: null,
    eyesUrl: null,
    isExploded: false,
    explodeFactor: 0
  });

  const handleAddFile = (file: File) => {
    const url = URL.createObjectURL(file);
    const id = Math.random().toString(36).substr(2, 9);
    const newModel: SceneModelInstance = {
      id,
      name: file.name.replace('.fbx', ''),
      url,
      settings: createDefaultSettings(),
      detectedMaterials: [],
      position: [0, 0, 0]
    };
    setModels(prev => [...prev, newModel]);
    setSelectedId(id);
    if (controlsRef.current) {
      controlsRef.current.reset();
    }
  };

  const updateModelData = (id: string, updates: Partial<SceneModelInstance>) => {
    setModels(prev => prev.map(m => m.id === id ? { ...m, ...updates } : m));
  };

  const handlePointerDown = (e: any) => {
    if (isMoveMode) {
      setIsMoveMode(false);
    }
  };

  const handleModelClick = (id: string) => {
    setSelectedId(id);
  };

  const handleCameraAction = (action: string) => {
    if (!controlsRef.current) return;
    const controls = controlsRef.current;
    const moveStep = 5;
    const zoomStep = 0.8;

    switch (action) {
      case 'zoomIn':
        controls.object.position.multiplyScalar(zoomStep);
        break;
      case 'zoomOut':
        controls.object.position.divideScalar(zoomStep);
        break;
      case 'panLeft':
        controls.target.x -= moveStep;
        break;
      case 'panRight':
        controls.target.x += moveStep;
        break;
      case 'panUp':
        controls.target.y += moveStep;
        break;
      case 'panDown':
        controls.target.y -= moveStep;
        break;
      case 'reset':
        controls.reset();
        controls.target.set(0, 0, 0);
        break;
    }
    controls.update();
  };

  const selectedModel = models.find(m => m.id === selectedId);

  const handleTextureUpload = (file: File, type: string, mat?: string) => {
    const url = URL.createObjectURL(file);
    if (!selectedModel) return;
    const currentSettings = selectedModel.settings;
    let newSettings = { ...currentSettings };

    if (mat) {
      if (type === 'base') newSettings.materialMappings = { ...currentSettings.materialMappings, [mat]: url };
      if (type === 'normal') newSettings.normalMappings = { ...currentSettings.normalMappings, [mat]: url };
      if (type === 'metal') newSettings.metalMappings = { ...currentSettings.metalMappings, [mat]: url };
      if (type === 'rough') newSettings.roughMappings = { ...currentSettings.roughMappings, [mat]: url };
      if (type === 'alpha') newSettings.alphaMappings = { ...currentSettings.alphaMappings, [mat]: url };
    } else {
      const fieldMap = { 
        metal: 'metalnessUrl', 
        rough: 'roughnessUrl', 
        transparency: 'transparencyUrl',
        shadow: 'shadowUrl',
        eyes: 'eyesUrl'
      } as const;
      if (type in fieldMap) {
        newSettings = { ...newSettings, [fieldMap[type as keyof typeof fieldMap]]: url };
      }
    }

    updateModelData(selectedModel.id, { settings: newSettings });
  };

  return (
    <div className="relative w-screen h-screen overflow-hidden flex bg-[#fdfbf7]">
      <div className="flex-1 relative cursor-crosshair">
        <Canvas 
          shadows 
          dpr={[1, 2]} 
          gl={{ antialias: true, alpha: true }}
          onPointerDown={handlePointerDown}
        >
          <PerspectiveCamera makeDefault position={[40, 30, 70]} fov={35} />
          <Suspense fallback={<Html center><div className="text-indigo-600 font-bold uppercase tracking-[0.5em] animate-pulse text-[10px]">Architecting...</div></Html>}>
            <ambientLight intensity={0.8} />
            <spotLight position={[50, 50, 50]} angle={0.15} penumbra={1} intensity={1.5} castShadow />
            <pointLight position={[-50, -50, -50]} intensity={0.8} color="#818cf8" />
            <Environment preset="city" />
            <Room />
            {models.map((model) => {
              const isSelected = selectedId === model.id;
              return (
                <group key={model.id} position={model.position} onPointerDown={(e) => { e.stopPropagation(); handleModelClick(model.id); }}>
                  <Float speed={1.5} rotationIntensity={0.2} floatIntensity={0.2}>
                    <FBXModel url={model.url} settings={model.settings} onMaterialsLoaded={(mats) => updateModelData(model.id, { detectedMaterials: mats })} />
                  </Float>
                  {isSelected && (
                    <group position={[0, 0, 0]}>
                      <mesh rotation={[-Math.PI/2, 0, 0]}><ringGeometry args={[19, 19.8, 64]} /><meshBasicMaterial color="#6366f1" transparent opacity={0.4} /></mesh>
                    </group>
                  )}
                </group>
              );
            })}
          </Suspense>
          <OrbitControls 
            ref={controlsRef}
            makeDefault 
            enableDamping 
            enabled={true} 
            minDistance={5} 
            maxDistance={500} 
          />
        </Canvas>
        <UIOverlay 
          settings={selectedModel?.settings || createDefaultSettings()} 
          setSettings={(newSettings) => { if (selectedId) updateModelData(selectedId, { settings: newSettings }); }}
          onFileUpload={handleAddFile}
          onTextureUpload={handleTextureUpload}
          onCameraAction={handleCameraAction}
          detectedMaterials={selectedModel?.detectedMaterials || []}
          isModelLoaded={!!selectedId}
          isMoveMode={isMoveMode}
          setMoveMode={setIsMoveMode}
        />
      </div>
      <Sidebar 
        models={models} 
        selectedId={selectedId} 
        onSelect={(id) => { setSelectedId(id); setIsMoveMode(false); }} 
        onAddFile={handleAddFile}
        onRemove={(id) => { setModels(prev => prev.filter(m => m.id !== id)); if (selectedId === id) setSelectedId(null); }}
        onTextureUpload={handleTextureUpload}
        hoveredMaterial={selectedModel?.settings.hoveredMaterial || null}
        onHoverMaterial={(mat) => {
          if (selectedId) {
            const current = models.find(m => m.id === selectedId);
            if (current) updateModelData(selectedId, { settings: { ...current.settings, hoveredMaterial: mat } });
          }
        }}
      />
    </div>
  );
};

export default App;

import React, { useEffect, useMemo, useState, useRef } from 'react';
import { useLoader, useFrame } from '@react-three/fiber';
import { FBXLoader } from 'three/examples/jsm/loaders/FBXLoader';
import * as THREE from 'three';
import '../types';
import { MaterialSettings } from '../types';

interface FBXModelProps {
  url: string;
  settings: MaterialSettings;
  onMaterialsLoaded?: (materials: string[]) => void;
}

const FBXModel: React.FC<FBXModelProps> = ({ url, settings, onMaterialsLoaded }) => {
  const fbx = useLoader(FBXLoader, url);
  const [textureCache, setTextureCache] = useState<{ [url: string]: THREE.Texture }>({});
  const loaderRef = useRef(new THREE.TextureLoader());
  const initialPositions = useRef<Map<THREE.Object3D, THREE.Vector3>>(new Map());
  const explodeDirections = useRef<Map<THREE.Object3D, THREE.Vector3>>(new Map());

  const [pulse, setPulse] = useState(0);

  useFrame((state) => {
    setPulse(Math.sin(state.clock.elapsedTime * 8) * 0.5 + 0.5);

    // Explode logic: Smoothly interpolate between original and exploded positions
    const targetFactor = settings.isExploded ? 1.0 : 0.0;
    // Simple smooth stepping for the internal factor
    const currentFactor = THREE.MathUtils.lerp(settings.explodeFactor || 0, targetFactor, 0.1);

    // Note: Since we are in a fiber loop, we usually want to update state or refs.
    // However, to keep it performant, we'll directly mutate local positions here
    // But we need to communicate the factor back if needed or just use it as is.

    fbx.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const original = initialPositions.current.get(child);
        const direction = explodeDirections.current.get(child);
        if (original && direction) {
          const offset = direction.clone().multiplyScalar(currentFactor * 30); // 30 is the explosion magnitude
          child.position.copy(original).add(offset);
        }
      }
    });
  });

  // Texture Loading
  useEffect(() => {
    const urlsToLoad: { url: string; isColor: boolean }[] = [];

    const maps = [
      { obj: settings.materialMappings, color: true },
      { obj: settings.normalMappings, color: false },
      { obj: settings.metalMappings, color: false },
      { obj: settings.roughMappings, color: false },
      { obj: settings.alphaMappings, color: false }
    ];

    maps.forEach(({ obj, color }) => {
      Object.values(obj).forEach(u => {
        if (u) urlsToLoad.push({ url: u as string, isColor: color });
      });
    });

    if (settings.metalnessUrl) urlsToLoad.push({ url: settings.metalnessUrl as string, isColor: false });
    if (settings.roughnessUrl) urlsToLoad.push({ url: settings.roughnessUrl as string, isColor: false });
    if (settings.transparencyUrl) urlsToLoad.push({ url: settings.transparencyUrl as string, isColor: false });
    if (settings.shadowUrl) urlsToLoad.push({ url: settings.shadowUrl as string, isColor: false });
    if (settings.eyesUrl) urlsToLoad.push({ url: settings.eyesUrl as string, isColor: true });

    urlsToLoad.forEach(({ url: u, isColor }) => {
      if (!textureCache[u]) {
        loaderRef.current.load(u, (tex) => {
          tex.colorSpace = isColor ? THREE.SRGBColorSpace : THREE.NoColorSpace;
          tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
          tex.needsUpdate = true;
          setTextureCache(prev => ({ ...prev, [u]: tex }));
        });
      }
    });
  }, [settings]);

  // Material Detection and Initial Position Caching
  useEffect(() => {
    const materialNames: string[] = [];
    initialPositions.current.clear();
    explodeDirections.current.clear();

    fbx.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;
        const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
        materials.forEach((m) => {
          if (m) {
            if (!m.name) m.name = `Node_${materialNames.length}`;
            if (!materialNames.includes(m.name)) materialNames.push(m.name);
          }
        });

        // Store initial position for explosion
        initialPositions.current.set(child, child.position.clone());

        // Calculate explosion direction (vector from model center to mesh center)
        const box = new THREE.Box3().setFromObject(child);
        const center = box.getCenter(new THREE.Vector3());
        const direction = center.clone().normalize();
        explodeDirections.current.set(child, direction);
      }
    });
    if (onMaterialsLoaded) onMaterialsLoaded(materialNames);
  }, [fbx, url, onMaterialsLoaded]);

  // PBR Engine
  useEffect(() => {
    fbx.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;
        const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];

        const updatedMaterials = materials.map((mat) => {
          if (!mat.userData.pbr || mat.type !== 'MeshStandardMaterial') {
            const originalColor = (mat as any).color ? (mat as any).color.clone() : new THREE.Color(0xffffff);
            const newMat = new THREE.MeshStandardMaterial({
              name: mat.name,
              color: originalColor,
              side: THREE.DoubleSide
            });
            mat.userData.pbr = newMat;
            mat.userData.originalColor = originalColor;
          }

          const pbr = mat.userData.pbr as THREE.MeshStandardMaterial;
          const isHovered = settings.hoveredMaterial === mat.name;

          pbr.map = settings.materialMappings[mat.name] ? textureCache[settings.materialMappings[mat.name]] : null;
          pbr.normalMap = settings.normalMappings[mat.name] ? textureCache[settings.normalMappings[mat.name]] : null;
          pbr.normalScale.set(1, 1);

          const metalTexUrl = settings.metalMappings[mat.name] || settings.metalnessUrl;
          pbr.metalness = metalTexUrl ? 1 : settings.metalness;
          pbr.metalnessMap = (metalTexUrl && textureCache[metalTexUrl]) || null;

          const roughTexUrl = settings.roughMappings[mat.name] || settings.roughnessUrl;
          pbr.roughness = roughTexUrl ? 1 : settings.roughness;
          pbr.roughnessMap = (roughTexUrl && textureCache[roughTexUrl]) || null;

          pbr.aoMap = (settings.shadowUrl && textureCache[settings.shadowUrl]) || null;
          pbr.aoMapIntensity = settings.shadowUrl ? 1.0 : 0.0;

          if (settings.eyesUrl && textureCache[settings.eyesUrl]) {
            pbr.emissiveMap = textureCache[settings.eyesUrl];
            pbr.emissive = new THREE.Color(0xffffff);
            pbr.emissiveIntensity = settings.emissiveIntensity || 1.0;
          } else {
            pbr.emissiveMap = null;
          }

          const alphaTexUrl = settings.alphaMappings[mat.name] || settings.transparencyUrl;
          const alphaTex = alphaTexUrl ? textureCache[alphaTexUrl] : null;

          if (settings.transparent || alphaTex || settings.opacity < 1.0) {
            pbr.transparent = true;
            pbr.opacity = settings.opacity;
            pbr.alphaMap = alphaTex;
            pbr.alphaTest = 0.5; 
            pbr.depthWrite = settings.opacity > 0.8; 
          } else {
            pbr.transparent = false;
            pbr.opacity = 1.0;
            pbr.alphaMap = null;
            pbr.alphaTest = 0;
            pbr.depthWrite = true;
          }

          if (isHovered) {
            pbr.emissive.setHex(0x94a3b8);
            pbr.emissiveIntensity = Math.max(pbr.emissiveIntensity, pulse * 0.2);
          } else if (!settings.eyesUrl) {
            pbr.emissive.setHex(0x000000);
            pbr.emissiveIntensity = 0;
          }

          const baseColor = settings.color === '#ffffff' ? mat.userData.originalColor : new THREE.Color(settings.color);
          pbr.color.copy(baseColor);
          pbr.needsUpdate = true;
          return pbr;
        });

        mesh.material = Array.isArray(mesh.material) ? updatedMaterials : updatedMaterials[0];
      }
    });
  }, [fbx, settings, textureCache, pulse]);

  const processedModel = useMemo(() => {
    fbx.updateMatrixWorld(true);
    const box = new THREE.Box3().setFromObject(fbx);
    const size = new THREE.Vector3();
    box.getSize(size);
    const maxDim = Math.max(size.x, size.y, size.z);
    const targetSize = 35; 
    const scaleFactor = targetSize / maxDim;
    fbx.scale.setScalar(scaleFactor);

    // מרכוז אבסולוטי - המרכז הגיאומטרי של המודל יהיה ב-0,0,0
    const scaledBox = new THREE.Box3().setFromObject(fbx);
    const center = scaledBox.getCenter(new THREE.Vector3());
    fbx.position.set(-center.x, -center.y, -center.z); 

    return fbx;
  }, [fbx, url]);

  return <primitive object={processedModel} />;
};

export default FBXModel;

import React from 'react';
import { MaterialSettings } from '../types';
import '../types';

interface UIOverlayProps {
  settings: MaterialSettings;
