import React, { useState, Suspense, useCallback, useRef } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, PerspectiveCamera, Environment, ContactShadows, Float, Html } from '@react-three/drei';
import * as THREE from 'three';
import './types';
import Room from './components/Room';
import FBXModel from './components/FBXModel';
import UIOverlay from './components/UIOverlay';
import Sidebar from './components/Sidebar';
import { MaterialSettings, SceneModelInstance } from './types';

const App: React.FC = () => {
  const [models, setModels] = useState<SceneModelInstance[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [isMoveMode, setIsMoveMode] = useState(false);
  const controlsRef = useRef<any>(null);

  const createDefaultSettings = (): MaterialSettings => ({
    opacity: 1.0,
    metalness: 0.5,
    roughness: 0.5,
    emissiveIntensity: 0.0,
    color: '#ffffff',
    transparent: false,
    materialMappings: {},
    normalMappings: {},
    metalMappings: {},
    roughMappings: {},
    alphaMappings: {},
    hoveredMaterial: null,
    metalnessUrl: null,
    roughnessUrl: null,
    transparencyUrl: null,
    shadowUrl: null,
    eyesUrl: null,
    isExploded: false,
    explodeFactor: 0,
    activeAnnotationId: null,
    showHotspots: true
  });

  const handleAddFile = (file: File) => {
    const url = URL.createObjectURL(file);
    const id = Math.random().toString(36).substr(2, 9);
    const newModel: SceneModelInstance = {
      id,
      name: file.name.replace('.fbx', ''),
      url,
      settings: createDefaultSettings(),
      detectedMaterials: [],
      position: [0, 0, 0]
    };
    setModels(prev => [...prev, newModel]);
    setSelectedId(id);
    if (controlsRef.current) {
      controlsRef.current.reset();
    }
  };

  const updateModelData = (id: string, updates: Partial<SceneModelInstance>) => {
    setModels(prev => prev.map(m => m.id === id ? { ...m, ...updates } : m));
  };

  const handleModelClick = (id: string) => {
    setSelectedId(id);
  };

  const handleCameraAction = (action: string, point?: THREE.Vector3) => {
    if (!controlsRef.current) return;
    const controls = controlsRef.current;

    if (action === 'focus' && point) {
      // Smoothly zoom to point
      const targetPos = point.clone();
      const cameraOffset = new THREE.Vector3(15, 10, 15);
      const newCamPos = targetPos.clone().add(cameraOffset);

      // We manually update to simulate a smooth transition
      controls.target.lerp(targetPos, 0.1);
      controls.object.position.lerp(newCamPos, 0.1);
      return;
    }

    const moveStep = 5;
    const zoomStep = 0.8;

    switch (action) {
      case 'zoomIn':
        controls.object.position.multiplyScalar(zoomStep);
        break;
      case 'zoomOut':
        controls.object.position.divideScalar(zoomStep);
        break;
      case 'panLeft':
        controls.target.x -= moveStep;
        break;
      case 'panRight':
        controls.target.x += moveStep;
        break;
      case 'panUp':
        controls.target.y += moveStep;
        break;
      case 'panDown':
        controls.target.y -= moveStep;
        break;
      case 'reset':
        controls.reset();
        controls.target.set(0, 0, 0);
        break;
    }
    controls.update();
  };

  const selectedModel = models.find(m => m.id === selectedId);

  return (
    <div className="relative w-screen h-screen overflow-hidden flex bg-[#fdfbf7]">
      <div className="flex-1 relative cursor-crosshair">
        <Canvas 
          shadows 
          dpr={[1, 2]} 
          gl={{ antialias: true, alpha: true }}
          onPointerDown={() => isMoveMode && setIsMoveMode(false)}
        >
          <PerspectiveCamera makeDefault position={[40, 30, 70]} fov={35} />
          <Suspense fallback={<Html center><div className="text-indigo-600 font-bold uppercase tracking-[0.5em] animate-pulse text-[10px]">Architecting...</div></Html>}>
            <ambientLight intensity={0.8} />
            <spotLight position={[50, 50, 50]} angle={0.15} penumbra={1} intensity={1.5} castShadow />
            <Environment preset="city" />
            <Room />
            {models.map((model) => (
              <group key={model.id} position={model.position} onPointerDown={(e) => { e.stopPropagation(); handleModelClick(model.id); }}>
                <Float speed={1.5} rotationIntensity={0.2} floatIntensity={0.2}>
                  <FBXModel 
                    url={model.url} 
                    settings={model.settings} 
                    onMaterialsLoaded={(mats) => updateModelData(model.id, { detectedMaterials: mats })} 
                    onHotspotClick={(matName, pos) => {
                      updateModelData(model.id, { settings: { ...model.settings, activeAnnotationId: matName } });
                      handleCameraAction('focus', pos);
                    }}
                  />
                </Float>
              </group>
            ))}
          </Suspense>
          <OrbitControls 
            ref={controlsRef}
            makeDefault 
            enableDamping 
            minDistance={5} 
            maxDistance={500} 
          />
        </Canvas>
        <UIOverlay 
          settings={selectedModel?.settings || createDefaultSettings()} 
          setSettings={(newSettings) => { if (selectedId) updateModelData(selectedId, { settings: newSettings }); }}
          onFileUpload={handleAddFile}
          onTextureUpload={() => {}} 
          onCameraAction={handleCameraAction}
          detectedMaterials={selectedModel?.detectedMaterials || []}
          isModelLoaded={!!selectedId}
          isMoveMode={isMoveMode}
          setMoveMode={setIsMoveMode}
        />
      </div>
      <Sidebar 
        models={models} 
        selectedId={selectedId} 
        onSelect={(id) => setSelectedId(id)} 
        onAddFile={handleAddFile}
        onRemove={(id) => { setModels(prev => prev.filter(m => m.id !== id)); if (selectedId === id) setSelectedId(null); }}
        onTextureUpload={() => {}}
        hoveredMaterial={selectedModel?.settings.hoveredMaterial || null}
        onHoverMaterial={(mat) => {
          if (selectedId) {
            const current = models.find(m => m.id === selectedId);
            if (current) updateModelData(selectedId, { settings: { ...current.settings, hoveredMaterial: mat } });
          }
        }}
      />
    </div>
  );
};

export default App;

import React, { useEffect, useMemo, useState, useRef } from 'react';
import { useLoader, useFrame } from '@react-three/fiber';
import { FBXLoader } from 'three/examples/jsm/loaders/FBXLoader';
import { Html } from '@react-three/drei';
import * as THREE from 'three';
import '../types';
import { MaterialSettings } from '../types';

interface FBXModelProps {
  url: string;
  settings: MaterialSettings;
  onMaterialsLoaded?: (materials: string[]) => void;
  onHotspotClick?: (matName: string, position: THREE.Vector3) => void;
}

const FBXModel: React.FC<FBXModelProps> = ({ url, settings, onMaterialsLoaded, onHotspotClick }) => {
  const fbx = useLoader(FBXLoader, url);
  const [textureCache, setTextureCache] = useState<{ [url: string]: THREE.Texture }>({});
  const loaderRef = useRef(new THREE.TextureLoader());
  const initialPositions = useRef<Map<THREE.Object3D, THREE.Vector3>>(new Map());
  const explodeDirections = useRef<Map<THREE.Object3D, THREE.Vector3>>(new Map());
  const hotspotPositions = useRef<Map<string, THREE.Vector3>>(new Map());

  const [pulse, setPulse] = useState(0);
  const [internalExplodeFactor, setInternalExplodeFactor] = useState(0);

  useFrame((state) => {
    setPulse(Math.sin(state.clock.elapsedTime * 8) * 0.5 + 0.5);
    const target = settings.isExploded ? 1.0 : 0.0;
    const nextFactor = THREE.MathUtils.lerp(internalExplodeFactor, target, 0.1);
    setInternalExplodeFactor(nextFactor);

    fbx.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const original = initialPositions.current.get(child);
        const direction = explodeDirections.current.get(child);
        if (original && direction) {
          const magnitude = nextFactor * 25; 
          child.position.x = original.x + direction.x * magnitude;
          child.position.y = original.y + direction.y * magnitude;
          child.position.z = original.z + direction.z * magnitude;
        }
      }
    });
  });

  // Texture Loader remains the same...
  useEffect(() => {
    const urlsToLoad: { url: string; isColor: boolean }[] = [];
    const maps = [{ obj: settings.materialMappings, color: true }, { obj: settings.normalMappings, color: false }, { obj: settings.metalMappings, color: false }, { obj: settings.roughMappings, color: false }, { obj: settings.alphaMappings, color: false }];
    maps.forEach(({ obj, color }) => Object.values(obj).forEach(u => u && urlsToLoad.push({ url: u as string, isColor: color })));
    urlsToLoad.forEach(({ url: u, isColor }) => {
      if (!textureCache[u]) loaderRef.current.load(u, (tex) => {
        tex.colorSpace = isColor ? THREE.SRGBColorSpace : THREE.NoColorSpace;
        tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
        setTextureCache(prev => ({ ...prev, [u]: tex }));
      });
    });
  }, [settings, textureCache]);

  const processedModel = useMemo(() => {
    fbx.scale.setScalar(1);
    fbx.position.set(0, 0, 0);
    fbx.updateMatrixWorld(true);

    const box = new THREE.Box3().setFromObject(fbx);
    const center = box.getCenter(new THREE.Vector3());
    const size = box.getSize(new THREE.Vector3());

    fbx.position.set(-center.x, -center.y, -center.z);
    fbx.updateMatrixWorld(true);

    const targetSize = 35; 
    const scaleFactor = targetSize / Math.max(size.x, size.y, size.z);
    fbx.scale.setScalar(scaleFactor);
    fbx.updateMatrixWorld(true);

    const materialNames: string[] = [];
    hotspotPositions.current.clear();

    fbx.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;
        const mat = Array.isArray(mesh.material) ? mesh.material[0] : mesh.material;
        if (mat) {
          if (!mat.name) mat.name = `Part_${materialNames.length}`;
          if (!materialNames.includes(mat.name)) {
            materialNames.push(mat.name);
            const worldPos = new THREE.Vector3();
            child.getWorldPosition(worldPos);
            hotspotPositions.current.set(mat.name, worldPos);
          }
        }
        initialPositions.current.set(child, child.position.clone());
        const direction = new THREE.Vector3();
        child.getWorldPosition(direction);
        explodeDirections.current.set(child, direction.normalize());
      }
    });

    if (onMaterialsLoaded) onMaterialsLoaded(materialNames);
    return fbx;
  }, [fbx, url]);

  // Material update logic remains the same...
  useEffect(() => {
    processedModel.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;
        const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
        const updatedMaterials = materials.map((mat) => {
          if (!mat.userData.pbr) {
            const originalColor = (mat as any).color ? (mat as any).color.clone() : new THREE.Color(0xffffff);
            mat.userData.pbr = new THREE.MeshStandardMaterial({ name: mat.name, color: originalColor, side: THREE.DoubleSide });
            mat.userData.originalColor = originalColor;
          }
          const pbr = mat.userData.pbr;
          pbr.metalness = settings.metalness;
          pbr.roughness = settings.roughness;
          const baseColor = settings.color === '#ffffff' ? mat.userData.originalColor : new THREE.Color(settings.color);
          pbr.color.copy(baseColor);
          if (settings.hoveredMaterial === mat.name) {
            pbr.emissive.setHex(0x6366f1);
            pbr.emissiveIntensity = pulse * 0.5;
          } else {
            pbr.emissive.setHex(0x000000);
          }
          return pbr;
        });
        mesh.material = Array.isArray(mesh.material) ? updatedMaterials : updatedMaterials[0];
      }
    });
  }, [processedModel, settings, pulse]);

  return (
    <group>
      <primitive object={processedModel} />
      {settings.showHotspots && Array.from(hotspotPositions.current.entries()).map(([name, pos]) => (
        <Html key={name} position={pos} distanceFactor={50} occlude>
          <div className="relative flex items-center justify-center group">
            <button 
              onClick={() => onHotspotClick?.(name, pos)}
              className="w-4 h-4 rounded-full bg-indigo-600 border-2 border-white shadow-lg shadow-indigo-500/50 hover:scale-125 transition-transform animate-pulse cursor-pointer pointer-events-auto"
            />

            {settings.activeAnnotationId === name && (
              <div className="absolute left-6 glass-panel rounded-2xl p-4 w-48 pointer-events-auto border-indigo-500/20 animate-in fade-in slide-in-from-left-2 shadow-2xl">
                <div className="flex justify-between items-start mb-2">
                  <span className="text-[8px] font-black text-indigo-600 uppercase tracking-widest">Detail View</span>
                  <button 
                    onClick={(e) => { e.stopPropagation(); onHotspotClick?.('', new THREE.Vector3(0,0,0)); }}
                    className="text-zinc-400 hover:text-red-500"
                  >
                    <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12" /></svg>
                  </button>
                </div>
                <h4 className="text-[10px] font-bold text-zinc-800 mb-1 truncate">{name}</h4>
                <p className="text-[8px] text-zinc-500 leading-relaxed">
                  Focused analysis of material properties. This component is optimized for PBR rendering and lighting interactions.
                </p>
              </div>
            )}
          </div>
        </Html>
      ))}
    </group>
  );
};

