import React, { useState, Suspense, useCallback, useRef } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, PerspectiveCamera, Environment, ContactShadows, Float, Html } from '@react-three/drei';
import * as THREE from 'three';
import './types';
import Room from './components/Room';
import FBXModel from './components/FBXModel';
import UIOverlay from './components/UIOverlay';
import Sidebar from './components/Sidebar';
import { MaterialSettings, SceneModelInstance } from './types';

const App: React.FC = () => {
  const [models, setModels] = useState<SceneModelInstance[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [isMoveMode, setIsMoveMode] = useState(false);
  const controlsRef = useRef<any>(null);

  const createDefaultSettings = (): MaterialSettings => ({
    opacity: 1.0,
    metalness: 0.5,
    roughness: 0.5,
    emissiveIntensity: 0.0,
    color: '#ffffff',
    transparent: false,
    materialMappings: {},
    normalMappings: {},
    metalMappings: {},
    roughMappings: {},
    alphaMappings: {},
    hoveredMaterial: null,
    metalnessUrl: null,
    roughnessUrl: null,
    transparencyUrl: null,
    shadowUrl: null,
    eyesUrl: null,
    isExploded: false,
    explodeFactor: 0,
    activeAnnotationId: null,
    showHotspots: true
  });

  const handleAddFile = (file: File) => {
    const url = URL.createObjectURL(file);
    const id = Math.random().toString(36).substr(2, 9);
    const newModel: SceneModelInstance = {
      id,
      name: file.name.replace('.fbx', ''),
      url,
      settings: createDefaultSettings(),
      detectedMaterials: [],
      position: [0, 0, 0]
    };
    setModels(prev => [...prev, newModel]);
    setSelectedId(id);
    if (controlsRef.current) {
      controlsRef.current.reset();
    }
  };

  const updateModelData = (id: string, updates: Partial<SceneModelInstance>) => {
    setModels(prev => prev.map(m => m.id === id ? { ...m, ...updates } : m));
  };

  const handleTextureUpload = (file: File, type: string, mat?: string) => {
    const url = URL.createObjectURL(file);
    const selectedModel = models.find(m => m.id === selectedId);
    if (!selectedModel) return;

    const currentSettings = { ...selectedModel.settings };

    if (mat) {
      if (type === 'base') currentSettings.materialMappings = { ...currentSettings.materialMappings, [mat]: url };
      if (type === 'normal') currentSettings.normalMappings = { ...currentSettings.normalMappings, [mat]: url };
      if (type === 'metal') currentSettings.metalMappings = { ...currentSettings.metalMappings, [mat]: url };
      if (type === 'rough') currentSettings.roughMappings = { ...currentSettings.roughMappings, [mat]: url };
      if (type === 'alpha') currentSettings.alphaMappings = { ...currentSettings.alphaMappings, [mat]: url };
    } else {
      if (type === 'metal') currentSettings.metalnessUrl = url;
      if (type === 'rough') currentSettings.roughnessUrl = url;
      if (type === 'transparency') currentSettings.transparencyUrl = url;
    }

    updateModelData(selectedModel.id, { settings: currentSettings });
  };

  const handleCameraAction = (action: string, point?: THREE.Vector3) => {
    if (!controlsRef.current) return;
    const controls = controlsRef.current;

    if (action === 'focus' && point) {
      const targetPos = point.clone();
      const cameraOffset = new THREE.Vector3(25, 18, 25);
      const newCamPos = targetPos.clone().add(cameraOffset);

      // We use simple set for now; for production, a lerp/tween would be better
      controls.target.copy(targetPos);
      controls.object.position.copy(newCamPos);
      controls.update();
      return;
    }

    const moveStep = 5;
    const zoomStep = 0.8;

    switch (action) {
      case 'zoomIn': controls.object.position.multiplyScalar(zoomStep); break;
      case 'zoomOut': controls.object.position.divideScalar(zoomStep); break;
      case 'panLeft': controls.target.x -= moveStep; break;
      case 'panRight': controls.target.x += moveStep; break;
      case 'panUp': controls.target.y += moveStep; break;
      case 'panDown': controls.target.y -= moveStep; break;
      case 'reset':
        controls.reset();
        controls.target.set(0, 0, 0);
        controls.object.position.set(40, 30, 70);
        break;
    }
    controls.update();
  };

  const selectedModel = models.find(m => m.id === selectedId);

  return (
    <div className="relative w-screen h-screen overflow-hidden flex bg-[#fdfbf7]">
      <div className="flex-1 relative cursor-crosshair">
        <Canvas 
          shadows 
          dpr={[1, 2]} 
          gl={{ antialias: true, alpha: true }}
          onPointerDown={() => isMoveMode && setIsMoveMode(false)}
        >
          <PerspectiveCamera makeDefault position={[40, 30, 70]} fov={35} />
          <Suspense fallback={<Html center><div className="text-indigo-600 font-bold uppercase tracking-[0.5em] animate-pulse text-[10px]">Architecting...</div></Html>}>
            <ambientLight intensity={0.8} />
            <spotLight position={[50, 50, 50]} angle={0.15} penumbra={1} intensity={1.5} castShadow />
            <Environment preset="city" />
            <Room />
            {models.map((model) => (
              <group key={model.id} position={model.position} onPointerDown={(e) => { e.stopPropagation(); setSelectedId(model.id); }}>
                <Float speed={1.5} rotationIntensity={0.2} floatIntensity={0.2}>
                  <FBXModel 
                    url={model.url} 
                    settings={model.settings} 
                    onMaterialsLoaded={(mats) => updateModelData(model.id, { detectedMaterials: mats })} 
                    onHotspotClick={(matName, pos) => {
                      updateModelData(model.id, { settings: { ...model.settings, activeAnnotationId: matName } });
                      if (matName) {
                        handleCameraAction('focus', pos);
                      } else {
                        handleCameraAction('reset');
                      }
                    }}
                  />
                </Float>
              </group>
            ))}
          </Suspense>
          <OrbitControls 
            ref={controlsRef}
            makeDefault 
            enableDamping 
            minDistance={5} 
            maxDistance={500} 
          />
        </Canvas>
        <UIOverlay 
          settings={selectedModel?.settings || createDefaultSettings()} 
          setSettings={(newSettings) => { if (selectedId) updateModelData(selectedId, { settings: newSettings }); }}
          onFileUpload={handleAddFile}
          onTextureUpload={handleTextureUpload} 
          onCameraAction={handleCameraAction}
          detectedMaterials={selectedModel?.detectedMaterials || []}
          isModelLoaded={!!selectedId}
          isMoveMode={isMoveMode}
          setMoveMode={setIsMoveMode}
        />
      </div>
      <Sidebar 
        models={models} 
        selectedId={selectedId} 
        onSelect={(id) => setSelectedId(id)} 
        onAddFile={handleAddFile}
        onRemove={(id) => { setModels(prev => prev.filter(m => m.id !== id)); if (selectedId === id) setSelectedId(null); }}
        onTextureUpload={handleTextureUpload}
        hoveredMaterial={selectedModel?.settings.hoveredMaterial || null}
        onHoverMaterial={(mat) => {
          if (selectedId) {
            const current = models.find(m => m.id === selectedId);
            if (current) updateModelData(selectedId, { settings: { ...current.settings, hoveredMaterial: mat } });
          }
        }}
      />
    </div>
  );
};

export default App;

import React, { useEffect, useMemo, useState, useRef } from 'react';
import { useLoader, useFrame } from '@react-three/fiber';
import { FBXLoader } from 'three/examples/jsm/loaders/FBXLoader';
import { Html } from '@react-three/drei';
import * as THREE from 'three';
import '../types';
import { MaterialSettings } from '../types';

interface FBXModelProps {
  url: string;
  settings: MaterialSettings;
  onMaterialsLoaded?: (materials: string[]) => void;
  onHotspotClick?: (matName: string, position: THREE.Vector3) => void;
}

const FBXModel: React.FC<FBXModelProps> = ({ url, settings, onMaterialsLoaded, onHotspotClick }) => {
  const fbx = useLoader(FBXLoader, url);
  const [textureCache, setTextureCache] = useState<{ [url: string]: THREE.Texture }>({});
  const loaderRef = useRef(new THREE.TextureLoader());
  const initialPositions = useRef<Map<THREE.Object3D, THREE.Vector3>>(new Map());
  const explodeDirections = useRef<Map<THREE.Object3D, THREE.Vector3>>(new Map());

  // Ref to store the latest world positions for hotspots
  const hotspotRefs = useRef<Map<string, { mesh: THREE.Mesh; worldPos: THREE.Vector3 }>>(new Map());
  const [activeHotspots, setActiveHotspots] = useState<{ name: string; position: THREE.Vector3 }[]>([]);

  const [pulse, setPulse] = useState(0);
  const [internalExplodeFactor, setInternalExplodeFactor] = useState(0);

  useFrame((state) => {
    setPulse(Math.sin(state.clock.elapsedTime * 6) * 0.5 + 0.5);
    const target = settings.isExploded ? 1.0 : 0.0;
    const nextFactor = THREE.MathUtils.lerp(internalExplodeFactor, target, 0.05);
    setInternalExplodeFactor(nextFactor);

    const updatedHotspots: { name: string; position: THREE.Vector3 }[] = [];

    fbx.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;

        // 1. Handle Explode Animation
        const original = initialPositions.current.get(child);
        const direction = explodeDirections.current.get(child);
        if (original && direction) {
          const magnitude = nextFactor * 25; 
          child.position.x = original.x + direction.x * magnitude;
          child.position.y = original.y + direction.y * magnitude;
          child.position.z = original.z + direction.z * magnitude;
        }

        // 2. Update Hotspot positions based on current world position
        const mat = Array.isArray(mesh.material) ? mesh.material[0] : mesh.material;
        if (mat && hotspotRefs.current.has(mat.name)) {
          const entry = hotspotRefs.current.get(mat.name);
          if (entry && entry.mesh === mesh) {
            const wp = new THREE.Vector3();
            // Get current world position of the mesh
            mesh.getWorldPosition(wp);
            updatedHotspots.push({ name: mat.name, position: wp });
          }
        }
      }
    });

    if (settings.showHotspots) {
      setActiveHotspots(updatedHotspots);
    }
  });

  // Texture Loading
  useEffect(() => {
    const mapsToLoad: { url: string; isColor: boolean }[] = [];
    const addUrl = (u: any, isColor = false) => {
      if (u && typeof u === 'string') mapsToLoad.push({ url: u, isColor });
    };

    Object.values(settings.materialMappings).forEach(u => addUrl(u, true));
    Object.values(settings.normalMappings).forEach(u => addUrl(u, false));
    Object.values(settings.metalMappings).forEach(u => addUrl(u, false));
    Object.values(settings.roughMappings).forEach(u => addUrl(u, false));
    Object.values(settings.alphaMappings).forEach(u => addUrl(u, false));
    addUrl(settings.metalnessUrl, false);
    addUrl(settings.roughnessUrl, false);
    addUrl(settings.transparencyUrl, false);

    mapsToLoad.forEach(({ url: u, isColor }) => {
      if (!textureCache[u]) {
        loaderRef.current.load(u, (tex) => {
          tex.colorSpace = isColor ? THREE.SRGBColorSpace : THREE.NoColorSpace;
          tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
          tex.needsUpdate = true;
          setTextureCache(prev => ({ ...prev, [u]: tex }));
        });
      }
    });
  }, [settings, textureCache]);

  const processedModel = useMemo(() => {
    fbx.scale.setScalar(1);
    fbx.position.set(0, 0, 0);
    fbx.updateMatrixWorld(true);

    const box = new THREE.Box3().setFromObject(fbx);
    const center = box.getCenter(new THREE.Vector3());
    const size = box.getSize(new THREE.Vector3());

    fbx.position.set(-center.x, -center.y, -center.z);
    fbx.updateMatrixWorld(true);

    const targetSize = 35; 
    const scaleFactor = targetSize / Math.max(size.x, size.y, size.z);
    fbx.scale.setScalar(scaleFactor);
    fbx.updateMatrixWorld(true);

    const materialNames: string[] = [];
    hotspotRefs.current.clear();

    fbx.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;
        const mat = Array.isArray(mesh.material) ? mesh.material[0] : mesh.material;

        if (mat) {
          if (!mat.name) mat.name = `Part_${materialNames.length}`;
          if (!materialNames.includes(mat.name)) {
            materialNames.push(mat.name);
            // Assign this mesh as the "anchor" for this material's hotspot
            hotspotRefs.current.set(mat.name, { mesh, worldPos: new THREE.Vector3() });
          }
        }

        initialPositions.current.set(child, child.position.clone());
        const direction = new THREE.Vector3();
        child.getWorldPosition(direction);
        explodeDirections.current.set(child, direction.normalize());
      }
    });

    if (onMaterialsLoaded) onMaterialsLoaded(materialNames);
    return fbx;
  }, [fbx, url]);

  useEffect(() => {
    processedModel.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;
        const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
        const updatedMaterials = materials.map((mat) => {
          if (!mat.userData.pbr || mat.type !== 'MeshStandardMaterial') {
            const originalColor = (mat as any).color ? (mat as any).color.clone() : new THREE.Color(0xffffff);
            mat.userData.pbr = new THREE.MeshStandardMaterial({ name: mat.name, color: originalColor, side: THREE.DoubleSide });
            mat.userData.originalColor = originalColor;
          }
          const pbr = mat.userData.pbr as THREE.MeshStandardMaterial;
          pbr.map = (settings.materialMappings[mat.name] && textureCache[settings.materialMappings[mat.name]]) || null;
          pbr.normalMap = (settings.normalMappings[mat.name] && textureCache[settings.normalMappings[mat.name]]) || null;
          pbr.metalnessMap = (settings.metalMappings[mat.name] && textureCache[settings.metalMappings[mat.name]]) || (settings.metalnessUrl && textureCache[settings.metalnessUrl]) || null;
          pbr.roughnessMap = (settings.roughMappings[mat.name] && textureCache[settings.roughMappings[mat.name]]) || (settings.roughnessUrl && textureCache[settings.roughnessUrl]) || null;
          pbr.alphaMap = (settings.alphaMappings[mat.name] && textureCache[settings.alphaMappings[mat.name]]) || (settings.transparencyUrl && textureCache[settings.transparencyUrl]) || null;
          pbr.metalness = pbr.metalnessMap ? 1.0 : settings.metalness;
          pbr.roughness = pbr.roughnessMap ? 1.0 : settings.roughness;
          pbr.transparent = !!pbr.alphaMap || settings.opacity < 1.0;
          pbr.opacity = settings.opacity;
          const baseColor = settings.color === '#ffffff' ? mat.userData.originalColor : new THREE.Color(settings.color);
          pbr.color.copy(baseColor);
          if (settings.hoveredMaterial === mat.name) {
            pbr.emissive.setHex(0x6366f1);
            pbr.emissiveIntensity = pulse * 0.4;
          } else {
            pbr.emissive.setHex(0x000000);
            pbr.emissiveIntensity = 0;
          }
          pbr.needsUpdate = true;
          return pbr;
        });
        mesh.material = Array.isArray(mesh.material) ? updatedMaterials : updatedMaterials[0];
      }
    });
  }, [processedModel, settings, textureCache, pulse]);

  return (
    <group>
      <primitive object={processedModel} />
      {settings.showHotspots && activeHotspots.map((h) => (
        <Html key={h.name} position={h.position} distanceFactor={40} zIndexRange={[10, 0]}>
          <div className="relative flex items-center justify-center">
            <button 
              onClick={(e) => {
                e.stopPropagation();
                onHotspotClick?.(h.name, h.position);
              }}
              className="w-6 h-6 rounded-full bg-white/20 backdrop-blur-md border-2 border-white shadow-xl hover:scale-125 transition-all cursor-pointer pointer-events-auto flex items-center justify-center group"
            >
               <div className="w-2 h-2 bg-indigo-600 rounded-full animate-pulse" />
            </button>

            {settings.activeAnnotationId === h.name && (
              <div className="absolute left-10 glass-panel rounded-3xl p-5 w-64 pointer-events-auto border-white/40 animate-in fade-in zoom-in-95 slide-in-from-left-4 shadow-2xl z-50">
                <div className="flex justify-between items-start mb-3">
                  <div className="flex flex-col">
                    <span className="text-[7px] font-black text-indigo-600 uppercase tracking-[0.2em] mb-0.5">Component</span>
                    <h4 className="text-[12px] font-bold text-zinc-900 truncate max-w-[140px]">{h.name}</h4>
                  </div>
                  <button 
                    onClick={(e) => { 
                      e.stopPropagation(); 
                      onHotspotClick?.('', new THREE.Vector3()); 
                    }}
                    className="p-1.5 hover:bg-black/5 rounded-full text-zinc-400 hover:text-indigo-600 transition-all"
                  >
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12" />
                    </svg>
                  </button>
                </div>
                <p className="text-[10px] text-zinc-500 leading-relaxed font-medium mb-3">
                  Material parameters applied. Use the top Studio Control bar to adjust physical properties in real-time.
                </p>
                <div className="flex items-center gap-2 pt-3 border-t border-black/5">
                  <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse"></div>
                  <span className="text-[8px] font-bold text-zinc-400 uppercase tracking-widest">Tracking Live</span>
                </div>
              </div>
            )}
          </div>
        </Html>
      ))}
    </group>
  );
};

export default FBXModel;

import React, { useEffect, useMemo, useState, useRef } from 'react';
import { useLoader, useFrame } from '@react-three/fiber';
import { FBXLoader } from 'three/examples/jsm/loaders/FBXLoader';
import { Html } from '@react-three/drei';
import * as THREE from 'three';
import '../types';
import { MaterialSettings } from '../types';

interface FBXModelProps {
  url: string;
  settings: MaterialSettings;
  onMaterialsLoaded?: (materials: string[]) => void;
  onHotspotClick?: (matName: string, position: THREE.Vector3) => void;
}

const FBXModel: React.FC<FBXModelProps> = ({ url, settings, onMaterialsLoaded, onHotspotClick }) => {
  const fbx = useLoader(FBXLoader, url);
  const [textureCache, setTextureCache] = useState<{ [url: string]: THREE.Texture }>({});
  const loaderRef = useRef(new THREE.TextureLoader());
  const initialPositions = useRef<Map<THREE.Object3D, THREE.Vector3>>(new Map());
  const explodeDirections = useRef<Map<THREE.Object3D, THREE.Vector3>>(new Map());

  // Ref to track which mesh is associated with which hotspot
  const meshAnchorRefs = useRef<Map<string, { mesh: THREE.Mesh; id: string; name: string }>>(new Map());
  const [activeHotspots, setActiveHotspots] = useState<{ id: string; name: string; position: THREE.Vector3 }[]>([]);

  const [pulse, setPulse] = useState(0);
  const [internalExplodeFactor, setInternalExplodeFactor] = useState(0);

  useFrame((state) => {
    setPulse(Math.sin(state.clock.elapsedTime * 6) * 0.5 + 0.5);
    const target = settings.isExploded ? 1.0 : 0.0;
    const nextFactor = THREE.MathUtils.lerp(internalExplodeFactor, target, 0.05);
    setInternalExplodeFactor(nextFactor);

    const updatedHotspots: { id: string; name: string; position: THREE.Vector3 }[] = [];

    fbx.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;

        // 1. Handle Explode Animation
        const original = initialPositions.current.get(child);
        const direction = explodeDirections.current.get(child);
        if (original && direction) {
          const magnitude = nextFactor * 25; 
          child.position.x = original.x + direction.x * magnitude;
          child.position.y = original.y + direction.y * magnitude;
          child.position.z = original.z + direction.z * magnitude;
        }

        // 2. Track Hotspots in real-time
        // We look for any mesh that was registered as a hotspot anchor
        meshAnchorRefs.current.forEach((anchor) => {
          if (anchor.mesh === mesh) {
            const wp = new THREE.Vector3();
            mesh.getWorldPosition(wp);
            updatedHotspots.push({ id: anchor.id, name: anchor.name, position: wp });
          }
        });
      }
    });

    if (settings.showHotspots) {
      // Only update state if needed to prevent excessive re-renders
      setActiveHotspots(updatedHotspots);
    }
  });

  // Texture Loading
  useEffect(() => {
    const mapsToLoad: { url: string; isColor: boolean }[] = [];
    const addUrl = (u: any, isColor = false) => {
      if (u && typeof u === 'string') mapsToLoad.push({ url: u, isColor });
    };

    Object.values(settings.materialMappings).forEach(u => addUrl(u, true));
    Object.values(settings.normalMappings).forEach(u => addUrl(u, false));
    Object.values(settings.metalMappings).forEach(u => addUrl(u, false));
    Object.values(settings.roughMappings).forEach(u => addUrl(u, false));
    Object.values(settings.alphaMappings).forEach(u => addUrl(u, false));
    addUrl(settings.metalnessUrl, false);
    addUrl(settings.roughnessUrl, false);
    addUrl(settings.transparencyUrl, false);

    mapsToLoad.forEach(({ url: u, isColor }) => {
      if (!textureCache[u]) {
        loaderRef.current.load(u, (tex) => {
          tex.colorSpace = isColor ? THREE.SRGBColorSpace : THREE.NoColorSpace;
          tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
          tex.needsUpdate = true;
          setTextureCache(prev => ({ ...prev, [u]: tex }));
        });
      }
    });
  }, [settings, textureCache]);

  const processedModel = useMemo(() => {
    fbx.scale.setScalar(1);
    fbx.position.set(0, 0, 0);
    fbx.updateMatrixWorld(true);

    const box = new THREE.Box3().setFromObject(fbx);
    const center = box.getCenter(new THREE.Vector3());
    const size = box.getSize(new THREE.Vector3());

    fbx.position.set(-center.x, -center.y, -center.z);
    fbx.updateMatrixWorld(true);

    const targetSize = 35; 
    const scaleFactor = targetSize / Math.max(size.x, size.y, size.z);
    fbx.scale.setScalar(scaleFactor);
    fbx.updateMatrixWorld(true);

    const materialNames: string[] = [];
    meshAnchorRefs.current.clear();
    let hotspotCount = 0;

    fbx.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;
        const mat = Array.isArray(mesh.material) ? mesh.material[0] : mesh.material;

        if (mat) {
          if (!mat.name) mat.name = `Part_${materialNames.length}`;
          if (!materialNames.includes(mat.name)) {
            materialNames.push(mat.name);
          }

          // Smart Hotspot Selection: 
          // We pick up to 10 unique meshes to act as hotspots.
          // We prefer meshes with unique names or significant parts.
          if (hotspotCount < 10) {
            const meshName = mesh.name || `Component_${hotspotCount}`;
            // Avoid duplicate hotspots for the same named object
            if (!meshAnchorRefs.current.has(meshName)) {
               meshAnchorRefs.current.set(meshName, { 
                 mesh, 
                 id: meshName, 
                 name: mat.name // We show the material name as the label
               });
               hotspotCount++;
            }
          }
        }

        initialPositions.current.set(child, child.position.clone());
        const direction = new THREE.Vector3();
        child.getWorldPosition(direction);
        explodeDirections.current.set(child, direction.normalize());
      }
    });

    if (onMaterialsLoaded) onMaterialsLoaded(materialNames);
    return fbx;
  }, [fbx, url]);

  useEffect(() => {
    processedModel.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;
        const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
        const updatedMaterials = materials.map((mat) => {
          if (!mat.userData.pbr || mat.type !== 'MeshStandardMaterial') {
            const originalColor = (mat as any).color ? (mat as any).color.clone() : new THREE.Color(0xffffff);
            mat.userData.pbr = new THREE.MeshStandardMaterial({ name: mat.name, color: originalColor, side: THREE.DoubleSide });
            mat.userData.originalColor = originalColor;
          }
          const pbr = mat.userData.pbr as THREE.MeshStandardMaterial;
          pbr.map = (settings.materialMappings[mat.name] && textureCache[settings.materialMappings[mat.name]]) || null;
          pbr.normalMap = (settings.normalMappings[mat.name] && textureCache[settings.normalMappings[mat.name]]) || null;
          pbr.metalnessMap = (settings.metalMappings[mat.name] && textureCache[settings.metalMappings[mat.name]]) || (settings.metalnessUrl && textureCache[settings.metalnessUrl]) || null;
          pbr.roughnessMap = (settings.roughMappings[mat.name] && textureCache[settings.roughMappings[mat.name]]) || (settings.roughnessUrl && textureCache[settings.roughnessUrl]) || null;
          pbr.alphaMap = (settings.alphaMappings[mat.name] && textureCache[settings.alphaMappings[mat.name]]) || (settings.transparencyUrl && textureCache[settings.transparencyUrl]) || null;
          pbr.metalness = pbr.metalnessMap ? 1.0 : settings.metalness;
          pbr.roughness = pbr.roughnessMap ? 1.0 : settings.roughness;
          pbr.transparent = !!pbr.alphaMap || settings.opacity < 1.0;
          pbr.opacity = settings.opacity;
          const baseColor = settings.color === '#ffffff' ? mat.userData.originalColor : new THREE.Color(settings.color);
          pbr.color.copy(baseColor);

          if (settings.hoveredMaterial === mat.name) {
            pbr.emissive.setHex(0x6366f1);
            pbr.emissiveIntensity = pulse * 0.4;
          } else {
            pbr.emissive.setHex(0x000000);
            pbr.emissiveIntensity = 0;
          }
          pbr.needsUpdate = true;
          return pbr;
        });
        mesh.material = Array.isArray(mesh.material) ? updatedMaterials : updatedMaterials[0];
      }
    });
  }, [processedModel, settings, textureCache, pulse]);

  return (
    <group>
      <primitive object={processedModel} />
      {settings.showHotspots && activeHotspots.map((h) => (
        <Html key={h.id} position={h.position} distanceFactor={40} zIndexRange={[10, 0]}>
          <div className="relative flex items-center justify-center">
            <button 
              onClick={(e) => {
                e.stopPropagation();
                onHotspotClick?.(h.id, h.position);
              }}
              className="w-6 h-6 rounded-full bg-white/20 backdrop-blur-md border-2 border-white shadow-xl hover:scale-125 transition-all cursor-pointer pointer-events-auto flex items-center justify-center group"
            >
               <div className="w-2 h-2 bg-indigo-600 rounded-full animate-pulse" />
            </button>

            {settings.activeAnnotationId === h.id && (
              <div className="absolute left-10 glass-panel rounded-3xl p-5 w-64 pointer-events-auto border-white/40 animate-in fade-in zoom-in-95 slide-in-from-left-4 shadow-2xl z-50">
                <div className="flex justify-between items-start mb-3">
                  <div className="flex flex-col">
                    <span className="text-[7px] font-black text-indigo-600 uppercase tracking-[0.2em] mb-0.5">Component Node</span>
                    <h4 className="text-[12px] font-bold text-zinc-900 truncate max-w-[140px]">{h.name}</h4>
                  </div>
                  <button 
                    onClick={(e) => { 
                      e.stopPropagation(); 
                      onHotspotClick?.('', new THREE.Vector3()); 
                    }}
                    className="p-1.5 hover:bg-black/5 rounded-full text-zinc-400 hover:text-red-500 transition-all"
                  >
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12" />
                    </svg>
                  </button>
                </div>
                <p className="text-[10px] text-zinc-500 leading-relaxed font-medium mb-3">
                  Tracking world-space position. This part is now isolated for real-time PBR material manipulation.
                </p>
                <div className="flex items-center gap-2 pt-3 border-t border-black/5">
                  <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse"></div>
                  <span className="text-[8px] font-bold text-zinc-400 uppercase tracking-widest">Active Tracking</span>
                </div>
              </div>
            )}
          </div>
        </Html>
      ))}
    </group>
  );
};

export default FBXModel;

import React from 'react';
import { ThreeElements } from '@react-three/fiber';
import * as THREE from 'three';

declare global {
  namespace React {
    namespace JSX {
      interface IntrinsicElements extends ThreeElements {}
    }
  }
}

export interface CustomHotspot {
  id: string;
  meshName: string;
  localPosition: THREE.Vector3;
  label: string;
  description: string;
}

export interface MaterialSettings {
  opacity: number;
  metalness: number;
  roughness: number;
  emissiveIntensity: number;
  color: string;
  transparent: boolean;
  materialMappings: Record<string, string>;
  normalMappings: Record<string, string>;
  metalMappings: Record<string, string>;
  roughMappings: Record<string, string>;
  alphaMappings: Record<string, string>;
  hoveredMaterial: string | null;
  metalnessUrl?: string | null;
  roughnessUrl?: string | null;
  transparencyUrl?: string | null;
  shadowUrl?: string | null;
  eyesUrl?: string | null;
  isExploded: boolean;
  explodeFactor: number;
  activeAnnotationId: string | null;
  showHotspots: boolean;
  // New properties for manual hotspot placement
  isPlacementMode: boolean;
  customHotspots: CustomHotspot[];
}

export interface SceneModelInstance {
  id: string;
  name: string;
  url: string;
  settings: MaterialSettings;
  detectedMaterials: string[];
  position: [number, number, number];
}

export interface ModelMetadata {
  name: string;
  size: string;
  triangleCount: number;
  materials: string[];
}

import React, { useEffect, useMemo, useState, useRef } from 'react';
import { useLoader, useFrame, ThreeEvent } from '@react-three/fiber';
import { FBXLoader } from 'three/examples/jsm/loaders/FBXLoader';
import { Html } from '@react-three/drei';
import * as THREE from 'three';
import '../types';
import { MaterialSettings, CustomHotspot } from '../types';

interface FBXModelProps {
  url: string;
  settings: MaterialSettings;
  onMaterialsLoaded?: (materials: string[]) => void;
  onHotspotClick?: (id: string, position: THREE.Vector3) => void;
  onAddHotspot?: (hotspot: CustomHotspot) => void;
  onRemoveHotspot?: (id: string) => void;
}

const FBXModel: React.FC<FBXModelProps> = ({ 
  url, settings, onMaterialsLoaded, onHotspotClick, onAddHotspot, onRemoveHotspot 
}) => {
  const fbx = useLoader(FBXLoader, url);
  const [textureCache, setTextureCache] = useState<{ [url: string]: THREE.Texture }>({});
  const loaderRef = useRef(new THREE.TextureLoader());
  const initialPositions = useRef<Map<THREE.Object3D, THREE.Vector3>>(new Map());
  const explodeDirections = useRef<Map<THREE.Object3D, THREE.Vector3>>(new Map());

  const [pulse, setPulse] = useState(0);
  const [internalExplodeFactor, setInternalExplodeFactor] = useState(0);

  // To render hotspots in world space, we need to compute their current world positions every frame
  const [renderedHotspots, setRenderedHotspots] = useState<{id: string, name: string, pos: THREE.Vector3, desc: string}[]>([]);

  useFrame((state) => {
    setPulse(Math.sin(state.clock.elapsedTime * 6) * 0.5 + 0.5);
    const target = settings.isExploded ? 1.0 : 0.0;
    const nextFactor = THREE.MathUtils.lerp(internalExplodeFactor, target, 0.05);
    setInternalExplodeFactor(nextFactor);

    // Update mesh positions for explode
    fbx.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const original = initialPositions.current.get(child);
        const direction = explodeDirections.current.get(child);
        if (original && direction) {
          const magnitude = nextFactor * 25; 
          child.position.set(
            original.x + direction.x * magnitude,
            original.y + direction.y * magnitude,
            original.z + direction.z * magnitude
          );
        }
      }
    });

    // Compute world positions for custom hotspots
    const updated: {id: string, name: string, pos: THREE.Vector3, desc: string}[] = [];
    settings.customHotspots.forEach(hs => {
      const mesh = fbx.getObjectByName(hs.meshName) as THREE.Mesh;
      if (mesh) {
        const wp = hs.localPosition.clone();
        mesh.localToWorld(wp);
        updated.push({ id: hs.id, name: hs.label, pos: wp, desc: hs.description });
      }
    });
    setRenderedHotspots(updated);
  });

  // Texture Logic (remains similar)
  useEffect(() => {
    const mapsToLoad: { url: string; isColor: boolean }[] = [];
    const addUrl = (u: any, isColor = false) => { if (u && typeof u === 'string') mapsToLoad.push({ url: u, isColor }); };
    Object.values(settings.materialMappings).forEach(u => addUrl(u, true));
    Object.values(settings.normalMappings).forEach(u => addUrl(u, false));
    Object.values(settings.metalMappings).forEach(u => addUrl(u, false));
    Object.values(settings.roughMappings).forEach(u => addUrl(u, false));
    Object.values(settings.alphaMappings).forEach(u => addUrl(u, false));
    addUrl(settings.metalnessUrl, false); addUrl(settings.roughnessUrl, false); addUrl(settings.transparencyUrl, false);
    mapsToLoad.forEach(({ url: u, isColor }) => {
      if (!textureCache[u]) {
        loaderRef.current.load(u, (tex) => {
          tex.colorSpace = isColor ? THREE.SRGBColorSpace : THREE.NoColorSpace;
          tex.needsUpdate = true;
          setTextureCache(prev => ({ ...prev, [u]: tex }));
        });
      }
    });
  }, [settings, textureCache]);

  const processedModel = useMemo(() => {
    fbx.scale.setScalar(1);
    fbx.position.set(0, 0, 0);
    fbx.updateMatrixWorld(true);
    const box = new THREE.Box3().setFromObject(fbx);
    const center = box.getCenter(new THREE.Vector3());
    const size = box.getSize(new THREE.Vector3());
    fbx.position.set(-center.x, -center.y, -center.z);
    const targetSize = 35; 
    const scaleFactor = targetSize / Math.max(size.x, size.y, size.z);
    fbx.scale.setScalar(scaleFactor);
    fbx.updateMatrixWorld(true);

    const materialNames: string[] = [];
    fbx.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;
        const mat = Array.isArray(mesh.material) ? mesh.material[0] : mesh.material;
        if (mat) {
          if (!mat.name) mat.name = `Part_${materialNames.length}`;
          if (!materialNames.includes(mat.name)) materialNames.push(mat.name);
        }
        // Save initial state for explode
        initialPositions.current.set(child, child.position.clone());
        const direction = new THREE.Vector3();
        child.getWorldPosition(direction);
        explodeDirections.current.set(child, direction.normalize());
      }
    });
    if (onMaterialsLoaded) onMaterialsLoaded(materialNames);
    return fbx;
  }, [fbx, url]);

  // Handle clicking on the model to add a hotspot
  const handlePointerDown = (e: ThreeEvent<PointerEvent>) => {
    if (!settings.isPlacementMode) return;
    e.stopPropagation();

    const { point, object } = e;
    const mesh = object as THREE.Mesh;

    // Convert world click point to local point relative to the mesh
    const localPos = mesh.worldToLocal(point.clone());

    const newHotspot: CustomHotspot = {
      id: Math.random().toString(36).substr(2, 9),
      meshName: mesh.name,
      localPosition: localPos,
      label: `Point ${settings.customHotspots.length + 1}`,
      description: "Custom user-placed tracking marker."
    };

    onAddHotspot?.(newHotspot);
  };

  // Material updates
  useEffect(() => {
    processedModel.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;
        const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
        const updatedMaterials = materials.map((mat) => {
          if (!mat.userData.pbr || mat.type !== 'MeshStandardMaterial') {
            const originalColor = (mat as any).color ? (mat as any).color.clone() : new THREE.Color(0xffffff);
            mat.userData.pbr = new THREE.MeshStandardMaterial({ name: mat.name, color: originalColor, side: THREE.DoubleSide });
            mat.userData.originalColor = originalColor;
          }
          const pbr = mat.userData.pbr as THREE.MeshStandardMaterial;
          pbr.map = (settings.materialMappings[mat.name] && textureCache[settings.materialMappings[mat.name]]) || null;
          pbr.normalMap = (settings.normalMappings[mat.name] && textureCache[settings.normalMappings[mat.name]]) || null;
          pbr.metalnessMap = (settings.metalMappings[mat.name] && textureCache[settings.metalMappings[mat.name]]) || (settings.metalnessUrl && textureCache[settings.metalnessUrl]) || null;
          pbr.roughnessMap = (settings.roughMappings[mat.name] && textureCache[settings.roughMappings[mat.name]]) || (settings.roughnessUrl && textureCache[settings.roughnessUrl]) || null;
          pbr.alphaMap = (settings.alphaMappings[mat.name] && textureCache[settings.alphaMappings[mat.name]]) || (settings.transparencyUrl && textureCache[settings.transparencyUrl]) || null;
          pbr.metalness = pbr.metalnessMap ? 1.0 : settings.metalness;
          pbr.roughness = pbr.roughnessMap ? 1.0 : settings.roughness;
          pbr.transparent = !!pbr.alphaMap || settings.opacity < 1.0;
          pbr.opacity = settings.opacity;
          const baseColor = settings.color === '#ffffff' ? mat.userData.originalColor : new THREE.Color(settings.color);
          pbr.color.copy(baseColor);

          if (settings.hoveredMaterial === mat.name) {
            pbr.emissive.setHex(0x6366f1);
            pbr.emissiveIntensity = pulse * 0.4;
          } else {
            pbr.emissive.setHex(0x000000);
            pbr.emissiveIntensity = 0;
          }
          pbr.needsUpdate = true;
          return pbr;
        });
        mesh.material = Array.isArray(mesh.material) ? updatedMaterials : updatedMaterials[0];
      }
    });
  }, [processedModel, settings, textureCache, pulse]);

  return (
    <group onPointerDown={handlePointerDown}>
      <primitive object={processedModel} />
      {settings.showHotspots && renderedHotspots.map((h) => (
        <Html key={h.id} position={h.pos} distanceFactor={40} zIndexRange={[10, 0]}>
          <div className="relative flex items-center justify-center">
            <button 
              onClick={(e) => { e.stopPropagation(); onHotspotClick?.(h.id, h.pos); }}
              className={`w-6 h-6 rounded-full bg-white/40 backdrop-blur-md border-2 border-white shadow-xl hover:scale-125 transition-all cursor-pointer pointer-events-auto flex items-center justify-center group ${settings.activeAnnotationId === h.id ? 'ring-4 ring-indigo-500/30 scale-110' : ''}`}
            >
               <div className="w-2.5 h-2.5 bg-indigo-600 rounded-full" />
            </button>

            {settings.activeAnnotationId === h.id && (
              <div className="absolute left-10 glass-panel rounded-3xl p-5 w-64 pointer-events-auto border-white/40 animate-in fade-in zoom-in-95 slide-in-from-left-4 shadow-2xl z-50">
                <div className="flex justify-between items-start mb-3">
                  <div className="flex flex-col">
                    <span className="text-[7px] font-black text-indigo-600 uppercase tracking-[0.2em] mb-0.5">Custom Marker</span>
                    <h4 className="text-[12px] font-bold text-zinc-900 truncate max-w-[140px]">{h.name}</h4>
                  </div>
                  <div className="flex gap-1">
                    <button 
                      onClick={(e) => { e.stopPropagation(); onRemoveHotspot?.(h.id); }}
                      className="p-1.5 hover:bg-red-500/10 rounded-full text-zinc-400 hover:text-red-500 transition-all"
                      title="Delete Point"
                    >
                      <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                      </svg>
                    </button>
                    <button 
                      onClick={(e) => { e.stopPropagation(); onHotspotClick?.('', new THREE.Vector3()); }}
                      className="p-1.5 hover:bg-black/5 rounded-full text-zinc-400 hover:text-indigo-600 transition-all"
                    >
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12" />
                      </svg>
                    </button>
                  </div>
                </div>
                <p className="text-[10px] text-zinc-500 leading-relaxed font-medium mb-3">{h.desc}</p>
                <div className="flex items-center gap-2 pt-3 border-t border-black/5">
                  <div className="w-1.5 h-1.5 bg-indigo-500 rounded-full animate-pulse"></div>
                  <span className="text-[8px] font-bold text-zinc-400 uppercase tracking-widest">Tracking Part</span>
                </div>
              </div>
            )}
          </div>
        </Html>
      ))}
    </group>
  );
};

export default FBXModel;

