import React, { useEffect, useMemo, useState, useRef } from 'react';
import { useLoader, useFrame, ThreeEvent } from '@react-three/fiber';
import { FBXLoader } from 'three/examples/jsm/loaders/FBXLoader';
import { Html } from '@react-three/drei';
import * as THREE from 'three';
import '../types';
import { MaterialSettings, CustomHotspot } from '../types';

interface FBXModelProps {
  url: string;
  settings: MaterialSettings;
  onMaterialsLoaded?: (materials: string[]) => void;
  onHotspotClick?: (id: string, position: THREE.Vector3) => void;
  onAddHotspot?: (hotspot: CustomHotspot) => void;
  onRemoveHotspot?: (id: string) => void;
  onSpeak?: (text: string) => void;
}

const FBXModel: React.FC<FBXModelProps> = ({ 
  url, settings, onMaterialsLoaded, onHotspotClick, onAddHotspot, onRemoveHotspot, onSpeak
}) => {
  const fbx = useLoader(FBXLoader, url);
  const [textureCache, setTextureCache] = useState<{ [url: string]: THREE.Texture }>({});
  const loaderRef = useRef(new THREE.TextureLoader());
  const initialPositions = useRef<Map<THREE.Object3D, THREE.Vector3>>(new Map());
  const explodeDirections = useRef<Map<THREE.Object3D, THREE.Vector3>>(new Map());

  const [pulse, setPulse] = useState(0);
  const [internalExplodeFactor, setInternalExplodeFactor] = useState(0);

  const [renderedHotspots, setRenderedHotspots] = useState<{id: string, name: string, pos: THREE.Vector3, desc: string}[]>([]);

  useFrame((state) => {
    setPulse(Math.sin(state.clock.elapsedTime * 6) * 0.5 + 0.5);
    const target = settings.isExploded ? 1.0 : 0.0;
    const nextFactor = THREE.MathUtils.lerp(internalExplodeFactor, target, 0.05);
    setInternalExplodeFactor(nextFactor);

    fbx.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const original = initialPositions.current.get(child);
        const direction = explodeDirections.current.get(child);
        if (original && direction) {
          const magnitude = nextFactor * 25; 
          child.position.set(
            original.x + direction.x * magnitude,
            original.y + direction.y * magnitude,
            original.z + direction.z * magnitude
          );
        }
      }
    });

    const updated: {id: string, name: string, pos: THREE.Vector3, desc: string}[] = [];
    settings.customHotspots.forEach(hs => {
      const mesh = fbx.getObjectByName(hs.meshName) as THREE.Mesh;
      if (mesh) {
        const wp = hs.localPosition.clone();
        mesh.localToWorld(wp);
        updated.push({ id: hs.id, name: hs.label, pos: wp, desc: hs.description });
      }
    });
    setRenderedHotspots(updated);
  });

  useEffect(() => {
    const mapsToLoad: { url: string; isColor: boolean }[] = [];
    const addUrl = (u: any, isColor = false) => { if (u && typeof u === 'string') mapsToLoad.push({ url: u, isColor }); };
    Object.values(settings.materialMappings).forEach(u => addUrl(u, true));
    Object.values(settings.normalMappings).forEach(u => addUrl(u, false));
    Object.values(settings.metalMappings).forEach(u => addUrl(u, false));
    Object.values(settings.roughMappings).forEach(u => addUrl(u, false));
    Object.values(settings.alphaMappings).forEach(u => addUrl(u, false));
    addUrl(settings.metalnessUrl, false); addUrl(settings.roughnessUrl, false); addUrl(settings.transparencyUrl, false);
    mapsToLoad.forEach(({ url: u, isColor }) => {
      if (!textureCache[u]) {
        loaderRef.current.load(u, (tex) => {
          tex.colorSpace = isColor ? THREE.SRGBColorSpace : THREE.NoColorSpace;
          tex.needsUpdate = true;
          setTextureCache(prev => ({ ...prev, [u]: tex }));
        });
      }
    });
  }, [settings, textureCache]);

  const processedModel = useMemo(() => {
    fbx.position.set(0, 0, 0);
    fbx.rotation.set(0, 0, 0);
    fbx.scale.setScalar(1);
    fbx.updateMatrixWorld(true);

    const box = new THREE.Box3().setFromObject(fbx);
    const center = new THREE.Vector3();
    box.getCenter(center);
    const size = new THREE.Vector3();
    box.getSize(size);

    fbx.position.x = -center.x;
    fbx.position.y = -center.y;
    fbx.position.z = -center.z;
    fbx.updateMatrixWorld(true);

    const targetSize = 35; 
    const scaleFactor = targetSize / Math.max(size.x, size.y, size.z);
    fbx.scale.setScalar(scaleFactor);
    fbx.updateMatrixWorld(true);

    const materialNames: string[] = [];
    fbx.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;
        const mat = Array.isArray(mesh.material) ? mesh.material[0] : mesh.material;
        if (mat) {
          if (!mat.name) mat.name = `Part_${materialNames.length}`;
          if (!materialNames.includes(mat.name)) materialNames.push(mat.name);
        }
        initialPositions.current.set(child, child.position.clone());
        const worldPos = new THREE.Vector3();
        child.getWorldPosition(worldPos);
        explodeDirections.current.set(child, worldPos.normalize());
      }
    });

    if (onMaterialsLoaded) onMaterialsLoaded(materialNames);
    return fbx;
  }, [fbx, url]);

  const handlePointerDown = (e: ThreeEvent<PointerEvent>) => {
    if (!settings.isPlacementMode) return;
    e.stopPropagation();
    const { point, object } = e;
    const mesh = object as THREE.Mesh;
    const localPos = mesh.worldToLocal(point.clone());
    const newHotspot: CustomHotspot = {
      id: Math.random().toString(36).substr(2, 9),
      meshName: mesh.name,
      localPosition: localPos,
      label: `Point ${settings.customHotspots.length + 1}`,
      description: "Custom user-placed tracking marker."
    };
    onAddHotspot?.(newHotspot);
  };

  useEffect(() => {
    processedModel.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;
        const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
        const updatedMaterials = materials.map((mat) => {
          if (!mat.userData.pbr || mat.type !== 'MeshStandardMaterial') {
            const originalColor = (mat as any).color ? (mat as any).color.clone() : new THREE.Color(0xffffff);
            mat.userData.pbr = new THREE.MeshStandardMaterial({ name: mat.name, color: originalColor, side: THREE.DoubleSide });
            mat.userData.originalColor = originalColor;
          }
          const pbr = mat.userData.pbr as THREE.MeshStandardMaterial;
          pbr.map = (settings.materialMappings[mat.name] && textureCache[settings.materialMappings[mat.name]]) || null;
          pbr.normalMap = (settings.normalMappings[mat.name] && textureCache[settings.normalMappings[mat.name]]) || null;
          pbr.metalnessMap = (settings.metalMappings[mat.name] && textureCache[settings.metalMappings[mat.name]]) || (settings.metalnessUrl && textureCache[settings.metalnessUrl]) || null;
          pbr.roughnessMap = (settings.roughMappings[mat.name] && textureCache[settings.roughMappings[mat.name]]) || (settings.roughnessUrl && textureCache[settings.roughnessUrl]) || null;
          pbr.alphaMap = (settings.alphaMappings[mat.name] && textureCache[settings.alphaMappings[mat.name]]) || (settings.transparencyUrl && textureCache[settings.transparencyUrl]) || null;
          pbr.metalness = pbr.metalnessMap ? 1.0 : settings.metalness;
          pbr.roughness = pbr.roughnessMap ? 1.0 : settings.roughness;
          pbr.transparent = !!pbr.alphaMap || settings.opacity < 1.0;
          pbr.opacity = settings.opacity;
          const baseColor = settings.color === '#ffffff' ? mat.userData.originalColor : new THREE.Color(settings.color);
          pbr.color.copy(baseColor);
          if (settings.hoveredMaterial === mat.name) {
            pbr.emissive.setHex(0x6366f1);
            pbr.emissiveIntensity = pulse * 0.4;
          } else {
            pbr.emissive.setHex(0x000000);
            pbr.emissiveIntensity = 0;
          }
          pbr.needsUpdate = true;
          return pbr;
        });
        mesh.material = Array.isArray(mesh.material) ? updatedMaterials : updatedMaterials[0];
      }
    });
  }, [processedModel, settings, textureCache, pulse]);

  return (
    <group onPointerDown={handlePointerDown}>
      <primitive object={processedModel} />
      {settings.showHotspots && renderedHotspots.map((h) => (
        <Html key={h.id} position={h.pos} distanceFactor={40} zIndexRange={[10, 0]}>
          <div className="relative flex items-center justify-center">
            <button 
              onClick={(e) => { 
                e.stopPropagation(); 
                onSpeak?.(`Viewing point ${h.name}`);
                onHotspotClick?.(h.id, h.pos); 
              }}
              className={`w-6 h-6 rounded-full bg-white/40 backdrop-blur-md border-2 border-white shadow-xl hover:scale-125 transition-all cursor-pointer pointer-events-auto flex items-center justify-center group ${settings.activeAnnotationId === h.id ? 'ring-4 ring-indigo-500/30 scale-110' : ''}`}
            >
               <div className="w-2.5 h-2.5 bg-indigo-600 rounded-full" />
            </button>
            {settings.activeAnnotationId === h.id && (
              <div className="absolute left-10 glass-panel rounded-3xl p-5 w-64 pointer-events-auto border-white/40 animate-in fade-in zoom-in-95 slide-in-from-left-4 shadow-2xl z-50">
                <div className="flex justify-between items-start mb-3">
                  <div className="flex flex-col">
                    <span className="text-[7px] font-black text-indigo-600 uppercase tracking-[0.2em] mb-0.5">Custom Marker</span>
                    <h4 className="text-[12px] font-bold text-zinc-900 truncate max-w-[140px]">{h.name}</h4>
                  </div>
                  <div className="flex gap-1">
                    <button 
                      onClick={(e) => { e.stopPropagation(); onRemoveHotspot?.(h.id); }}
                      className="p-1.5 hover:bg-red-500/10 rounded-full text-zinc-400 hover:text-red-500 transition-all"
                    >
                      <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                    </button>
                    <button 
                      onClick={(e) => { 
                        e.stopPropagation(); 
                        onSpeak?.("Closing details");
                        onHotspotClick?.('', new THREE.Vector3()); 
                      }} 
                      className="p-1.5 hover:bg-black/5 rounded-full text-zinc-400 hover:text-indigo-600 transition-all"
                    >
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                  </div>
                </div>
                <p className="text-[10px] text-zinc-500 leading-relaxed font-medium mb-3">{h.desc}</p>
              </div>
            )}
          </div>
        </Html>
      ))}
    </group>
  );
};

export default FBXModel;

import React from 'react';
import { SceneModelInstance } from '../types';

interface SidebarProps {
  models: SceneModelInstance[];
  selectedId: string | null;
  onSelect: (id: string) => void;
  onAddFile: (file: File) => void;
  onRemove: (id: string) => void;
  // Make matName optional to match handleTextureUpload in App.tsx
  onTextureUpload: (file: File, type: string, matName?: string) => void;
  onHoverMaterial: (matName: string | null) => void;
  hoveredMaterial: string | null;
  // Add onSpeak to SidebarProps to match usage in App.tsx
  onSpeak?: (text: string) => void;
}

const Sidebar: React.FC<SidebarProps> = ({ 
  models, selectedId, onSelect, onAddFile, onRemove, onTextureUpload, onHoverMaterial, hoveredMaterial, onSpeak 
}) => {
  const selectedModel = models.find(m => m.id === selectedId);

  const handleBatchFiles = (e: React.ChangeEvent<HTMLInputElement>, type: string) => {
    const files = e.target.files;
    if (!files || !selectedModel) return;
    const fileArray = Array.from(files) as File[];

    fileArray.forEach(file => {
      const fileName = file.name.toLowerCase();
      const matchedMat = selectedModel.detectedMaterials.find(mat => {
        const lowMat = mat.toLowerCase();
        return fileName.includes(lowMat) || lowMat.includes(fileName.split('.')[0]);
      });

      if (matchedMat) {
        onTextureUpload(file, type, matchedMat);
      }
    });
  };

  return (
    <div className="w-96 h-full glass-panel border-l border-black/5 flex flex-col p-6 pointer-events-auto z-20 overflow-y-auto custom-scroll">

      {/* 1. MODEL IMPORT */}
      <div className="mb-6">
        <h2 className="text-zinc-400 text-[9px] font-black uppercase tracking-[0.4em] mb-3">Model Asset</h2>
        <label className="flex flex-col items-center justify-center w-full py-8 bg-indigo-500/5 border-2 border-dashed border-indigo-500/20 rounded-2xl hover:border-indigo-500 hover:bg-indigo-500/10 cursor-pointer transition-all group">
          <div className="mb-2 p-2.5 bg-indigo-500/10 rounded-xl group-hover:scale-110 transition-transform">
            <svg className="w-5 h-5 text-indigo-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M10 14l2-2m0 0l2 2m-2-2v6" />
            </svg>
          </div>
          <span className="text-[10px] font-black text-zinc-800 uppercase tracking-[0.2em]">Import FBX</span>
          <input type="file" className="hidden" accept=".fbx" onChange={(e) => e.target.files?.[0] && onAddFile(e.target.files[0])} />
        </label>
      </div>

      {/* 2. BATCH UPLOAD SECTION */}
      {selectedId && (
        <div className="mb-8 p-4 bg-black/5 rounded-2xl border border-black/5">
          <h2 className="text-indigo-600 text-[9px] font-black uppercase tracking-[0.4em] mb-4">Batch Import (Auto-Map)</h2>
          <div className="grid grid-cols-2 gap-2">
            {[
              { id: 'base', label: 'All Base' },
              { id: 'normal', label: 'All Normal' },
              { id: 'metal', label: 'All Metal' },
              { id: 'rough', label: 'All Rough' },
              { id: 'alpha', label: 'All Alpha' }
            ].map((btn) => (
              <label key={btn.id} className="cursor-pointer group">
                <div className="flex items-center gap-2 px-3 py-2 bg-indigo-500/10 hover:bg-indigo-500/20 border border-indigo-500/20 rounded-lg transition-all">
                  <svg className="w-3 h-3 text-indigo-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-8l-4-4m0 0L8 8m4-4v12" />
                  </svg>
                  <span className="text-[7px] font-black uppercase text-indigo-800 tracking-widest">{btn.label}</span>
                </div>
                <input type="file" multiple className="hidden" accept="image/*" onChange={(e) => handleBatchFiles(e, btn.id)} />
              </label>
            ))}
          </div>
        </div>
      )}

      {/* 3. ACTIVE OBJECTS */}
      <div className="flex-1 space-y-4">
        <h3 className="text-zinc-400 text-[8px] font-black uppercase tracking-[0.3em] mb-2 border-b border-black/5 pb-2">Active Hierarchy</h3>
        {models.map((model) => (
          <div key={model.id} className="space-y-2">
            <div 
              onClick={() => onSelect(model.id)}
              className={`group p-4 rounded-xl border transition-all cursor-pointer flex items-center justify-between ${selectedId === model.id ? 'bg-indigo-600/5 border-indigo-500/20 shadow-sm' : 'bg-black/5 border-transparent hover:bg-black/10'}`}
            >
              <div className="flex flex-col min-w-0">
                <span className={`text-[10px] font-bold truncate tracking-tight ${selectedId === model.id ? 'text-indigo-900' : 'text-zinc-600'}`}>
                  {model.name}
                </span>
                <span className="text-[7px] text-zinc-400 uppercase font-black tracking-widest mt-0.5">{model.detectedMaterials.length} Materials</span>
              </div>
              <button onClick={(e) => { e.stopPropagation(); onRemove(model.id); }} className="opacity-0 group-hover:opacity-100 p-1.5 text-zinc-400 hover:text-red-500 transition-all">
                <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
              </button>
            </div>

            {selectedId === model.id && (
              <div className="pl-2 space-y-4 mt-2 animate-in slide-in-from-left-2 duration-300 max-h-[400px] overflow-y-auto custom-scroll pr-2">
                {model.detectedMaterials.map((mat) => (
                  <div key={mat} onMouseEnter={() => onHoverMaterial(mat)} onMouseLeave={() => onHoverMaterial(null)} className={`p-3 rounded-xl border transition-all ${hoveredMaterial === mat ? 'bg-indigo-500/5 border-indigo-500/10' : 'bg-black/5 border-transparent'}`}>
                    <div className="text-[8px] text-zinc-500 font-black truncate uppercase mb-2 tracking-widest">{mat}</div>
                    <div className="grid grid-cols-5 gap-1.5">
                      {[
                        { id: 'base', label: 'COL', tip: 'Base Color' },
                        { id: 'normal', label: 'NRM', tip: 'Normal Map' },
                        { id: 'metal', label: 'MET', tip: 'Metallic' },
                        { id: 'rough', label: 'RGH', tip: 'Roughness' },
                        { id: 'alpha', label: 'TRN', tip: 'Transparency' }
                      ].map((slot) => (
                        <label key={slot.id} className="cursor-pointer group/slot relative">
                          <div className={`aspect-square rounded-lg flex flex-col items-center justify-center transition-all border ${
                            (slot.id === 'base' && model.settings.materialMappings[mat]) ||
                            (slot.id === 'normal' && model.settings.normalMappings[mat]) ||
                            (slot.id === 'metal' && model.settings.metalMappings[mat]) ||
                            (slot.id === 'rough' && model.settings.roughMappings[mat]) ||
                            (slot.id === 'alpha' && model.settings.alphaMappings[mat])
                              ? 'bg-indigo-500/20 border-indigo-500/30' : 'bg-white/80 border-black/5 hover:bg-white'
                          }`}>
                            <span className="text-[7px] font-black tracking-tighter text-zinc-500 group-hover/slot:text-indigo-600">{slot.label}</span>
                          </div>
                          <input type="file" className="hidden" accept="image/*" onChange={(e) => e.target.files?.[0] && onTextureUpload(e.target.files[0], slot.id, mat)} />
                        </label>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

