import React, { useState, Suspense, useCallback, useRef } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, PerspectiveCamera, Environment, ContactShadows, Float, Html } from '@react-three/drei';
import * as THREE from 'three';
import './types';
import Room from './components/Room';
import FBXModel from './components/FBXModel';
import UIOverlay from './components/UIOverlay';
import Sidebar from './components/Sidebar';
import { MaterialSettings, SceneModelInstance, CustomHotspot } from './types';
import { speakText } from './services/ttsService';

const App: React.FC = () => {
  const [models, setModels] = useState<SceneModelInstance[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [isMoveMode, setIsMoveMode] = useState(false);
  const controlsRef = useRef<any>(null);

  const createDefaultSettings = (): MaterialSettings => ({
    opacity: 1.0,
    metalness: 0.5,
    roughness: 0.5,
    emissiveIntensity: 0.0,
    color: '#ffffff',
    transparent: false,
    materialMappings: {},
    normalMappings: {},
    metalMappings: {},
    roughMappings: {},
    alphaMappings: {},
    hoveredMaterial: null,
    metalnessUrl: null,
    roughnessUrl: null,
    transparencyUrl: null,
    shadowUrl: null,
    eyesUrl: null,
    isExploded: false,
    explodeFactor: 0,
    activeAnnotationId: null,
    showHotspots: true,
    isPlacementMode: false,
    customHotspots: []
  });

  const handleAddFile = (file: File) => {
    const url = URL.createObjectURL(file);
    const id = Math.random().toString(36).substr(2, 9);
    const newModel: SceneModelInstance = {
      id,
      name: file.name.replace('.fbx', ''),
      url,
      settings: createDefaultSettings(),
      detectedMaterials: [],
      position: [0, 0, 0]
    };
    setModels(prev => [...prev, newModel]);
    setSelectedId(id);
    if (controlsRef.current) {
      controlsRef.current.reset();
    }
  };

  const updateModelData = (id: string, updates: Partial<SceneModelInstance>) => {
    setModels(prev => prev.map(m => m.id === id ? { ...m, ...updates } : m));
  };

  const handleCameraAction = (action: string, point?: THREE.Vector3) => {
    if (!controlsRef.current) return;
    const controls = controlsRef.current;

    if (action === 'focus' && point) {
      const targetPos = point.clone();
      const cameraOffset = new THREE.Vector3(25, 18, 25);
      const newCamPos = targetPos.clone().add(cameraOffset);

      controls.target.copy(targetPos);
      controls.object.position.copy(newCamPos);
      controls.update();
      return;
    }

    const moveStep = 5;
    const zoomStep = 0.8;

    switch (action) {
      case 'zoomIn': controls.object.position.multiplyScalar(zoomStep); break;
      case 'zoomOut': controls.object.position.divideScalar(zoomStep); break;
      case 'panLeft': controls.target.x -= moveStep; break;
      case 'panRight': controls.target.x += moveStep; break;
      case 'panUp': controls.target.y += moveStep; break;
      case 'panDown': controls.target.y -= moveStep; break;
      case 'reset':
        controls.reset();
        controls.target.set(0, 0, 0);
        controls.object.position.set(40, 30, 70);
        break;
    }
    controls.update();
  };

  const handleAddHotspot = (hs: CustomHotspot) => {
    if (!selectedId) return;
    const model = models.find(m => m.id === selectedId);
    if (model) {
      updateModelData(selectedId, {
        settings: {
          ...model.settings,
          customHotspots: [...model.settings.customHotspots, hs],
          isPlacementMode: false 
        }
      });
    }
  };

  const handleRemoveHotspot = (id: string) => {
    if (!selectedId) return;
    const model = models.find(m => m.id === selectedId);
    if (model) {
      updateModelData(selectedId, {
        settings: {
          ...model.settings,
          customHotspots: model.settings.customHotspots.filter(h => h.id !== id),
          activeAnnotationId: model.settings.activeAnnotationId === id ? null : model.settings.activeAnnotationId
        }
      });
    }
  };

  const handleTextureUpload = useCallback((file: File, type: string, matName?: string) => {
    if (!selectedId) return;
    const url = URL.createObjectURL(file);
    const model = models.find(m => m.id === selectedId);
    if (!model) return;

    const newSettings = { ...model.settings };

    if (matName) {
      if (type === 'base') newSettings.materialMappings = { ...newSettings.materialMappings, [matName]: url };
      if (type === 'normal') newSettings.normalMappings = { ...newSettings.normalMappings, [matName]: url };
      if (type === 'metal') newSettings.metalMappings = { ...newSettings.metalMappings, [matName]: url };
      if (type === 'rough') newSettings.roughMappings = { ...newSettings.roughMappings, [matName]: url };
      if (type === 'alpha') newSettings.alphaMappings = { ...newSettings.alphaMappings, [matName]: url };
    } else {
      if (type === 'metal') newSettings.metalnessUrl = url;
      if (type === 'rough') newSettings.roughnessUrl = url;
      if (type === 'alpha') newSettings.transparencyUrl = url;
    }

    updateModelData(selectedId, { settings: newSettings });
  }, [selectedId, models]);

  const selectedModel = models.find(m => m.id === selectedId);

  return (
    <div className="relative w-screen h-screen overflow-hidden flex bg-[#fdfbf7]">
      <div className="flex-1 relative">
        <Canvas 
          shadows 
          dpr={[1, 2]} 
          gl={{ antialias: true, alpha: true }}
          onPointerDown={() => isMoveMode && setIsMoveMode(false)}
        >
          <PerspectiveCamera makeDefault position={[40, 30, 70]} fov={35} />
          <Suspense fallback={<Html center><div className="text-indigo-600 font-bold uppercase tracking-[0.5em] animate-pulse text-[10px]">Architecting...</div></Html>}>
            <ambientLight intensity={0.8} />
            <spotLight position={[50, 50, 50]} angle={0.15} penumbra={1} intensity={1.5} castShadow />
            <Environment preset="city" />
            <Room />
            {models.map((model) => (
              <group key={model.id} position={model.position} onPointerDown={(e) => { 
                if (model.settings.isPlacementMode) return; 
                e.stopPropagation(); 
                if (selectedId !== model.id) {
                  setSelectedId(model.id); 
                }
              }}>
                <Float speed={1.5} rotationIntensity={0.1} floatIntensity={0.1}>
                  <FBXModel 
                    url={model.url} 
                    settings={model.settings} 
                    onMaterialsLoaded={(mats) => updateModelData(model.id, { detectedMaterials: mats })} 
                    onHotspotClick={(hsId, pos) => {
                      updateModelData(model.id, { settings: { ...model.settings, activeAnnotationId: hsId } });
                      if (hsId) {
                        handleCameraAction('focus', pos);
                      } else {
                        handleCameraAction('reset');
                      }
                    }}
                    onAddHotspot={handleAddHotspot}
                    onRemoveHotspot={handleRemoveHotspot}
                    onSpeak={speakText}
                  />
                </Float>
              </group>
            ))}
          </Suspense>
          <OrbitControls 
            ref={controlsRef}
            makeDefault 
            enableDamping 
            minDistance={5} 
            maxDistance={500} 
            enabled={!isMoveMode}
          />
        </Canvas>
        <UIOverlay 
          settings={selectedModel?.settings || createDefaultSettings()} 
          setSettings={(newSettings) => { if (selectedId) updateModelData(selectedId, { settings: newSettings }); }}
          onFileUpload={handleAddFile}
          onTextureUpload={handleTextureUpload} 
          onCameraAction={handleCameraAction}
          detectedMaterials={selectedModel?.detectedMaterials || []}
          isModelLoaded={!!selectedId}
          isMoveMode={isMoveMode}
          setMoveMode={(val) => {
            setIsMoveMode(val);
          }}
        />
      </div>
      <Sidebar 
        models={models} 
        selectedId={selectedId} 
        onSelect={(id) => {
          setSelectedId(id);
        }} 
        onAddFile={handleAddFile}
        onRemove={(id) => { 
          setModels(prev => prev.filter(m => m.id !== id)); 
          if (selectedId === id) setSelectedId(null); 
        }}
        onTextureUpload={handleTextureUpload}
        hoveredMaterial={selectedModel?.settings.hoveredMaterial || null}
        onHoverMaterial={(mat) => {
          if (selectedId) {
            const current = models.find(m => m.id === selectedId);
            if (current) updateModelData(selectedId, { settings: { ...current.settings, hoveredMaterial: mat } });
          }
        }}
      />
    </div>
  );
};

