// Define the structure for hotspots
interface Hotspot {
  id: string;
  position: [number, number, number];
  label: string;
  description: string;
}

// 3D Scene Components
const Model = () => {
  // Using a placeholder box to represent a complex model
  return (
    <mesh position={[0, 1.5, 0]} castShadow receiveShadow>
      <boxGeometry args={[3, 3, 3]} />
      <meshStandardMaterial color="#3b82f6" metalness={0.7} roughness={0.2} />
    </mesh>
  );
};

const Room = () => {
  return (
    <group>
      {/* Floor */}
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 0, 0]} receiveShadow>
        <planeGeometry args={[50, 50]} />
        <meshStandardMaterial color="#111" />
      </mesh>
      {/* Lights */}
      <ambientLight intensity={0.5} />
      <spotLight position={[10, 10, 10]} angle={0.15} penumbra={1} intensity={2} castShadow />
      <pointLight position={[-10, 5, -10]} intensity={1} />
    </group>
  );
};

interface HotspotComponentProps {
  hotspot: Hotspot;
  activeId: string | null;
  onClick: (h: Hotspot) => void;
}

const HotspotComponent: React.FC<HotspotComponentProps> = ({ hotspot, activeId, onClick }) => {
  const meshRef = useRef<THREE.Mesh>(null);
  const isActive = activeId === hotspot.id;

  useFrame((state) => {
    if (meshRef.current) {
      meshRef.current.rotation.y += 0.02;
      if (isActive) {
        const scale = 1 + Math.sin(state.clock.elapsedTime * 5) * 0.1;
        meshRef.current.scale.set(scale, scale, scale);
      }
    }
  });

  return (
    <group position={hotspot.position}>
      <mesh 
        ref={meshRef} 
        onClick={(e) => {
          e.stopPropagation();
          onClick(hotspot);
        }}
        onPointerOver={() => (document.body.style.cursor = 'pointer')}
        onPointerOut={() => (document.body.style.cursor = 'auto')}
      >
        <sphereGeometry args={[0.15, 32, 32]} />
        <meshStandardMaterial color={isActive ? "#fbbf24" : "#ffffff"} emissive={isActive ? "#fbbf24" : "#ffffff"} emissiveIntensity={2} />
      </button>

      {isActive && (
        <Float speed={2} rotationIntensity={0.5} floatIntensity={0.5}>
          <Text
            position={[0, 0.5, 0]}
            fontSize={0.2}
            color="white"
            anchorX="center"
            anchorY="middle"
            maxWidth={2}
          >
            {hotspot.label}
          </Text>
        </Float>
      )}
    </group>
  );
};

