import React, { useEffect, useMemo, useState, useRef } from 'react';
import { useLoader, useFrame, ThreeEvent } from '@react-three/fiber';
import { FBXLoader } from 'three/examples/jsm/loaders/FBXLoader';
import { Html } from '@react-three/drei';
import * as THREE from 'three';
import '../types';
import { MaterialSettings, CustomHotspot } from '../types';

interface FBXModelProps {
  url: string;
  settings: MaterialSettings;
  onMaterialsLoaded?: (materials: string[]) => void;
  onHotspotClick?: (id: string, position: THREE.Vector3) => void;
  onAddHotspot?: (hotspot: CustomHotspot) => void;
  onRemoveHotspot?: (id: string) => void;
  // Removed onSpeak as we now use pre-cached audio from the parent
}

const FBXModel: React.FC<FBXModelProps> = ({ 
  url, settings, onMaterialsLoaded, onHotspotClick, onAddHotspot, onRemoveHotspot
}) => {
  const fbx = useLoader(FBXLoader, url);
  const [textureCache, setTextureCache] = useState<{ [url: string]: THREE.Texture }>({});
  const loaderRef = useRef(new THREE.TextureLoader());
  const initialPositions = useRef<Map<THREE.Object3D, THREE.Vector3>>(new Map());
  const explodeDirections = useRef<Map<THREE.Object3D, THREE.Vector3>>(new Map());

  const [pulse, setPulse] = useState(0);
  const [internalExplodeFactor, setInternalExplodeFactor] = useState(0);

  const [renderedHotspots, setRenderedHotspots] = useState<{id: string, name: string, pos: THREE.Vector3, desc: string}[]>([]);

  useFrame((state) => {
    setPulse(Math.sin(state.clock.elapsedTime * 6) * 0.5 + 0.5);
    const target = settings.isExploded ? 1.0 : 0.0;
    const nextFactor = THREE.MathUtils.lerp(internalExplodeFactor, target, 0.05);
    setInternalExplodeFactor(nextFactor);

    fbx.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const original = initialPositions.current.get(child);
        const direction = explodeDirections.current.get(child);
        if (original && direction) {
          const magnitude = nextFactor * 25; 
          child.position.set(
            original.x + direction.x * magnitude,
            original.y + direction.y * magnitude,
            original.z + direction.z * magnitude
          );
        }
      }
    });

    const updated: {id: string, name: string, pos: THREE.Vector3, desc: string}[] = [];
    settings.customHotspots.forEach(hs => {
      const mesh = fbx.getObjectByName(hs.meshName) as THREE.Mesh;
      if (mesh) {
        const wp = hs.localPosition.clone();
        mesh.localToWorld(wp);
        updated.push({ id: hs.id, name: hs.label, pos: wp, desc: hs.description });
      }
    });
    setRenderedHotspots(updated);
  });

  useEffect(() => {
    const mapsToLoad: { url: string; isColor: boolean }[] = [];
    const addUrl = (u: any, isColor = false) => { if (u && typeof u === 'string') mapsToLoad.push({ url: u, isColor }); };
    Object.values(settings.materialMappings).forEach(u => addUrl(u, true));
    Object.values(settings.normalMappings).forEach(u => addUrl(u, false));
    Object.values(settings.metalMappings).forEach(u => addUrl(u, false));
    Object.values(settings.roughMappings).forEach(u => addUrl(u, false));
    Object.values(settings.alphaMappings).forEach(u => addUrl(u, false));
    mapsToLoad.forEach(({ url: u, isColor }) => {
      if (!textureCache[u]) {
        loaderRef.current.load(u, (tex) => {
          tex.colorSpace = isColor ? THREE.SRGBColorSpace : THREE.NoColorSpace;
          tex.needsUpdate = true;
          setTextureCache(prev => ({ ...prev, [u]: tex }));
        });
      }
    });
  }, [settings, textureCache]);

  const processedModel = useMemo(() => {
    fbx.position.set(0, 0, 0); fbx.rotation.set(0, 0, 0); fbx.scale.setScalar(1); fbx.updateMatrixWorld(true);
    const box = new THREE.Box3().setFromObject(fbx);
    const center = new THREE.Vector3(); box.getCenter(center);
    const size = new THREE.Vector3(); box.getSize(size);
    fbx.position.x = -center.x; fbx.position.y = -center.y; fbx.position.z = -center.z;
    fbx.updateMatrixWorld(true);
    const targetSize = 35; 
    const scaleFactor = targetSize / Math.max(size.x, size.y, size.z);
    fbx.scale.setScalar(scaleFactor); fbx.updateMatrixWorld(true);

    const materialNames: string[] = [];
    fbx.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;
        const mat = Array.isArray(mesh.material) ? mesh.material[0] : mesh.material;
        if (mat) {
          if (!mat.name) mat.name = `Part_${materialNames.length}`;
          if (!materialNames.includes(mat.name)) materialNames.push(mat.name);
        }
        initialPositions.current.set(child, child.position.clone());
        const worldPos = new THREE.Vector3();
        child.getWorldPosition(worldPos);
        explodeDirections.current.set(child, worldPos.normalize());
      }
    });
    if (onMaterialsLoaded) onMaterialsLoaded(materialNames);
    return fbx;
  }, [fbx, url]);

  const handlePointerDown = (e: ThreeEvent<PointerEvent>) => {
    if (!settings.isPlacementMode) return;
    e.stopPropagation();
    const { point, object } = e;
    const mesh = object as THREE.Mesh;
    const localPos = mesh.worldToLocal(point.clone());
    const newHotspot: CustomHotspot = {
      id: Math.random().toString(36).substr(2, 9),
      meshName: mesh.name,
      localPosition: localPos,
      label: `Point ${settings.customHotspots.length + 1}`,
      description: "עודד קטש הוא המלך, בכדורסל אין הפועל"
    };
    onAddHotspot?.(newHotspot);
  };

  useEffect(() => {
    processedModel.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;
        const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
        const updatedMaterials = materials.map((mat) => {
          if (!mat.userData.pbr || mat.type !== 'MeshStandardMaterial') {
            const originalColor = (mat as any).color ? (mat as any).color.clone() : new THREE.Color(0xffffff);
            mat.userData.pbr = new THREE.MeshStandardMaterial({ name: mat.name, color: originalColor, side: THREE.DoubleSide });
            mat.userData.originalColor = originalColor;
          }
          const pbr = mat.userData.pbr as THREE.MeshStandardMaterial;
          pbr.map = (settings.materialMappings[mat.name] && textureCache[settings.materialMappings[mat.name]]) || null;
          pbr.normalMap = (settings.normalMappings[mat.name] && textureCache[settings.normalMappings[mat.name]]) || null;
          pbr.metalnessMap = (settings.metalMappings[mat.name] && textureCache[settings.metalMappings[mat.name]]) || (settings.metalnessUrl && textureCache[settings.metalnessUrl]) || null;
          pbr.roughnessMap = (settings.roughMappings[mat.name] && textureCache[settings.roughMappings[mat.name]]) || (settings.roughnessUrl && textureCache[settings.roughnessUrl]) || null;
          pbr.alphaMap = (settings.alphaMappings[mat.name] && textureCache[settings.alphaMappings[mat.name]]) || (settings.transparencyUrl && textureCache[settings.transparencyUrl]) || null;
          pbr.metalness = pbr.metalnessMap ? 1.0 : settings.metalness;
          pbr.roughness = pbr.roughnessMap ? 1.0 : settings.roughness;
          pbr.transparent = !!pbr.alphaMap || settings.opacity < 1.0;
          pbr.opacity = settings.opacity;
          const baseColor = settings.color === '#ffffff' ? mat.userData.originalColor : new THREE.Color(settings.color);
          pbr.color.copy(baseColor);
          if (settings.hoveredMaterial === mat.name) {
            pbr.emissive.setHex(0x6366f1); pbr.emissiveIntensity = pulse * 0.4;
          } else {
            pbr.emissive.setHex(0x000000); pbr.emissiveIntensity = 0;
          }
          pbr.needsUpdate = true;
          return pbr;
        });
        mesh.material = Array.isArray(mesh.material) ? updatedMaterials : updatedMaterials[0];
      }
    });
  }, [processedModel, settings, textureCache, pulse]);

  return (
    <group onPointerDown={handlePointerDown}>
      <primitive object={processedModel} />
      {settings.showHotspots && renderedHotspots.map((h) => (
        <Html key={h.id} position={h.pos} distanceFactor={40} zIndexRange={[10, 0]}>
          <div className="relative flex items-center justify-center">
            <button 
              onClick={(e) => { e.stopPropagation(); onHotspotClick?.(h.id, h.pos); }}
              className={`w-6 h-6 rounded-full bg-white/40 backdrop-blur-md border-2 border-white shadow-xl hover:scale-125 transition-all cursor-pointer pointer-events-auto flex items-center justify-center group ${settings.activeAnnotationId === h.id ? 'ring-4 ring-indigo-500/30 scale-110' : ''}`}
            >
               <div className="w-2.5 h-2.5 bg-indigo-600 rounded-full" />
            </button>
            {settings.activeAnnotationId === h.id && (
              <div className="absolute left-10 glass-panel rounded-3xl p-5 w-64 pointer-events-auto border-white/40 animate-in fade-in zoom-in-95 slide-in-from-left-4 shadow-2xl z-50">
                <div className="flex justify-between items-start mb-3">
                  <div className="flex flex-col">
                    <span className="text-[7px] font-black text-indigo-600 uppercase tracking-[0.2em] mb-0.5">Custom Marker</span>
                    <h4 className="text-[12px] font-bold text-zinc-900 truncate max-w-[140px]">{h.name}</h4>
                  </div>
                  <div className="flex gap-1">
                    <button onClick={(e) => { e.stopPropagation(); onRemoveHotspot?.(h.id); }} className="p-1.5 hover:bg-red-500/10 rounded-full text-zinc-400 hover:text-red-500 transition-all"><svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg></button>
                    <button onClick={(e) => { e.stopPropagation(); onHotspotClick?.('', new THREE.Vector3()); }} className="p-1.5 hover:bg-black/5 rounded-full text-zinc-400 hover:text-indigo-600 transition-all"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12" /></svg></button>
                  </div>
                </div>
                <p className="text-[10px] text-zinc-500 leading-relaxed font-medium mb-3">{h.desc}</p>
              </div>
            )}
          </div>
        </Html>
      ))}
    </group>
  );
};

export default FBXModel;

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const suggestMaterials = async (modelDescription: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Suggest physically accurate PBR material settings for a 3D model described as: "${modelDescription}". Return suggestions for Opacity, Metalness, and Roughness.`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          opacity: { type: Type.NUMBER, description: "Transparency level (0-1)" },
          metalness: { type: Type.NUMBER, description: "Metalness level (0-1)" },
          roughness: { type: Type.NUMBER, description: "Roughness level (0-1)" },
          explanation: { type: Type.STRING, description: "Brief reason for these settings" }
        },
        required: ["opacity", "metalness", "roughness", "explanation"]
      }
    }
  });

  try {
    const text = response.text;
    if (!text) return null;
    return JSON.parse(text.trim());
  } catch (e) {
    console.error("Failed to parse Gemini response", e);
    return null;
  }
};

/**
 * Generates a creative and professional description for a specific part of a 3D model.
 */
export const generateHotspotDescription = async (partName: string, modelName: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `You are an expert architectural critic. Generate a short, professional, and inspiring one-sentence description for the part named "${partName}" in a 3D model of a "${modelName}". The description should be in Hebrew and focus on design quality.`,
    });
    return response.text?.trim() || "תיאור לא זמין כרגע.";
  } catch (e) {
    console.error("Gemini Description Error:", e);
    return "חלק מעוצב ואיכותי כחלק מהקומפוזיציה הכוללת.";
  }
};

import React, { useState, Suspense, useCallback, useRef } from 'react';
import { Canvas, useFrame, useThree } from '@react-three/fiber';
import { OrbitControls, PerspectiveCamera, Environment, Float, Html } from '@react-three/drei';
import * as THREE from 'three';
import './types';
import Room from './components/Room';
import FBXModel from './components/FBXModel';
import UIOverlay from './components/UIOverlay';
import Sidebar from './components/Sidebar';
import { MaterialSettings, SceneModelInstance, CustomHotspot } from './types';
import { generateAudioBuffer, playAudioBuffer, speakText } from './services/ttsService';
import { generateHotspotDescription } from './services/geminiService';

const CameraHandler: React.FC<{ targetView: { pos: THREE.Vector3, lookAt: THREE.Vector3 } | null, controlsRef: any }> = ({ targetView, controlsRef }) => {
  const { camera } = useThree();
  useFrame(() => {
    if (targetView && controlsRef.current) {
      camera.position.lerp(targetView.pos, 0.05);
      controlsRef.current.target.lerp(targetView.lookAt, 0.05);
      controlsRef.current.update();
    }
  });
  return null;
};

const App: React.FC = () => {
  const [models, setModels] = useState<SceneModelInstance[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [isMoveMode, setIsMoveMode] = useState(false);
  const [targetView, setTargetView] = useState<{ pos: THREE.Vector3, lookAt: THREE.Vector3 } | null>(null);
  const controlsRef = useRef<any>(null);

  const createDefaultSettings = (): MaterialSettings => ({
    opacity: 1.0, metalness: 0.5, roughness: 0.5, emissiveIntensity: 0.0,
    color: '#ffffff', transparent: false, materialMappings: {},
    normalMappings: {}, metalMappings: {}, roughMappings: {}, alphaMappings: {},
    hoveredMaterial: null, isExploded: false, explodeFactor: 0,
    activeAnnotationId: null, showHotspots: true, isPlacementMode: false, customHotspots: []
  });

  const handleAddFile = (file: File) => {
    const url = URL.createObjectURL(file);
    const id = Math.random().toString(36).substr(2, 9);
    setModels(prev => [...prev, {
      id, name: file.name.replace('.fbx', ''), url,
      settings: createDefaultSettings(), detectedMaterials: [], position: [0, 0, 0]
    }]);
    setSelectedId(id);
    setTargetView(null);
  };

  const updateModelData = (id: string, updates: Partial<SceneModelInstance>) => {
    setModels(prev => prev.map(m => m.id === id ? { ...m, ...updates } : m));
  };

  const handleCameraAction = (action: string, point?: THREE.Vector3) => {
    if (action === 'focus' && point) {
      setTargetView({ pos: point.clone().add(new THREE.Vector3(25, 15, 25)), lookAt: point.clone() });
      return;
    }
    if (action === 'reset') {
      setTargetView({ pos: new THREE.Vector3(40, 30, 70), lookAt: new THREE.Vector3(0, 0, 0) });
      return;
    }
    setTargetView(null); 
    if (!controlsRef.current) return;
    const controls = controlsRef.current;
    if (action === 'zoomIn') controls.object.position.multiplyScalar(0.8);
    if (action === 'zoomOut') controls.object.position.divideScalar(0.8);
    controls.update();
  };

  const handleAddHotspot = async (hs: CustomHotspot) => {
    if (!selectedId) return;
    const model = models.find(m => m.id === selectedId);
    if (!model) return;

    // Add placeholder first with a loading state for description
    const tempHs = { ...hs, description: "מייצר תיאור חכם..." };
    const updatedHotspots = [...model.settings.customHotspots, tempHs];
    updateModelData(selectedId, { settings: { ...model.settings, customHotspots: updatedHotspots, isPlacementMode: false } });

    // 1. GENERATE SMART DESCRIPTION
    const smartDescription = await generateHotspotDescription(hs.meshName, model.name);

    // 2. UPDATE DESCRIPTION IN STATE
    setModels(prev => prev.map(m => m.id === selectedId ? {
      ...m,
      settings: {
        ...m.settings,
        customHotspots: m.settings.customHotspots.map(h => h.id === hs.id ? { ...h, description: smartDescription } : h)
      }
    } : m));

    // 3. PRE-CACHE AUDIO BUFFER
    const buffer = await generateAudioBuffer(smartDescription);
    if (buffer) {
      setModels(prev => prev.map(m => m.id === selectedId ? {
        ...m,
        settings: {
          ...m.settings,
          customHotspots: m.settings.customHotspots.map(h => h.id === hs.id ? { ...h, audioBuffer: buffer } : h)
        }
      } : m));
    }
  };

  const handleRemoveHotspot = (id: string) => {
    if (!selectedId) return;
    const model = models.find(m => m.id === selectedId);
    if (model) {
      updateModelData(selectedId, {
        settings: {
          ...model.settings,
          customHotspots: model.settings.customHotspots.filter(h => h.id !== id),
          activeAnnotationId: model.settings.activeAnnotationId === id ? null : model.settings.activeAnnotationId
        }
      });
    }
  };

  const handleTextureUpload = useCallback((file: File, type: string, matName?: string) => {
    if (!selectedId) return;
    const url = URL.createObjectURL(file);
    const model = models.find(m => m.id === selectedId);
    if (!model) return;
    const newSettings = { ...model.settings };
    if (matName) {
      if (type === 'base') newSettings.materialMappings = { ...newSettings.materialMappings, [matName]: url };
      if (type === 'normal') newSettings.normalMappings = { ...newSettings.normalMappings, [matName]: url };
      if (type === 'metal') newSettings.metalMappings = { ...newSettings.metalMappings, [matName]: url };
      if (type === 'rough') newSettings.roughMappings = { ...newSettings.roughMappings, [matName]: url };
      if (type === 'alpha') newSettings.alphaMappings = { ...newSettings.alphaMappings, [matName]: url };
    }
    updateModelData(selectedId, { settings: newSettings });
  }, [selectedId, models]);

  const selectedModel = models.find(m => m.id === selectedId);

  return (
    <div className="relative w-screen h-screen overflow-hidden flex bg-[#fdfbf7]">
      <div className="flex-1 relative">
        <Canvas shadows dpr={[1, 2]} gl={{ antialias: true, alpha: true }} onPointerDown={() => { if (isMoveMode) setIsMoveMode(false); setTargetView(null); }}>
          <PerspectiveCamera makeDefault position={[40, 30, 70]} fov={35} />
          <CameraHandler targetView={targetView} controlsRef={controlsRef} />
          <Suspense fallback={<Html center><div className="text-indigo-600 font-bold uppercase tracking-[0.5em] animate-pulse text-[10px]">Architecting...</div></Html>}>
            <ambientLight intensity={0.8} />
            <spotLight position={[50, 50, 50]} angle={0.15} penumbra={1} intensity={1.5} castShadow />
            <Environment preset="city" />
            <Room />
            {models.map((model) => (
              <group key={model.id} position={model.position} onPointerDown={(e) => { if (model.settings.isPlacementMode) return; e.stopPropagation(); if (selectedId !== model.id) setSelectedId(model.id); }}>
                <Float speed={1.5} rotationIntensity={0.1} floatIntensity={0.1}>
                  <FBXModel 
                    url={model.url} 
                    settings={model.settings} 
                    onMaterialsLoaded={(mats) => updateModelData(model.id, { detectedMaterials: mats })} 
                    onHotspotClick={(hsId, pos) => {
                      updateModelData(model.id, { settings: { ...model.settings, activeAnnotationId: hsId } });
                      if (hsId) {
                        handleCameraAction('focus', pos);
                        const hs = model.settings.customHotspots.find(h => h.id === hsId);
                        if (hs?.audioBuffer) {
                          playAudioBuffer(hs.audioBuffer);
                        } else if (hs?.description) {
                          // Fallback if click happens before buffer is ready
                          speakText(hs.description);
                        }
                      } else {
                        handleCameraAction('reset');
                      }
                    }}
                    onAddHotspot={handleAddHotspot}
                    onRemoveHotspot={handleRemoveHotspot}
                  />
                </Float>
              </group>
            ))}
          </Suspense>
          <OrbitControls ref={controlsRef} makeDefault enableDamping minDistance={5} maxDistance={500} enabled={!isMoveMode} />
        </Canvas>
        <UIOverlay settings={selectedModel?.settings || createDefaultSettings()} setSettings={(ns) => { if (selectedId) updateModelData(selectedId, { settings: ns }); }} onFileUpload={handleAddFile} onTextureUpload={handleTextureUpload} onCameraAction={handleCameraAction} detectedMaterials={selectedModel?.detectedMaterials || []} isModelLoaded={!!selectedId} isMoveMode={isMoveMode} setMoveMode={setIsMoveMode} />
      </div>
      <Sidebar models={models} selectedId={selectedId} onSelect={setSelectedId} onAddFile={handleAddFile} onRemove={(id) => { setModels(prev => prev.filter(m => m.id !== id)); if (selectedId === id) setSelectedId(null); }} onTextureUpload={handleTextureUpload} onHoverMaterial={(mat) => { if (selectedId) { const curr = models.find(m => m.id === selectedId); if (curr) updateModelData(selectedId, { settings: { ...curr.settings, hoveredMaterial: mat } }); } }} hoveredMaterial={selectedModel?.settings.hoveredMaterial || null} />
    </div>
  );
};

export default App;

import React, { useEffect, useMemo, useState, useRef } from 'react';
import { useLoader, useFrame, ThreeEvent } from '@react-three/fiber';
import { FBXLoader } from 'three/examples/jsm/loaders/FBXLoader';
import { Html } from '@react-three/drei';
import * as THREE from 'three';
import '../types';
import { MaterialSettings, CustomHotspot } from '../types';

interface FBXModelProps {
  url: string;
  settings: MaterialSettings;
  onMaterialsLoaded?: (materials: string[]) => void;
  onHotspotClick?: (id: string, position: THREE.Vector3) => void;
  onAddHotspot?: (hotspot: CustomHotspot) => void;
  onRemoveHotspot?: (id: string) => void;
}

const FBXModel: React.FC<FBXModelProps> = ({ 
  url, settings, onMaterialsLoaded, onHotspotClick, onAddHotspot, onRemoveHotspot
}) => {
  const fbx = useLoader(FBXLoader, url);
  const [textureCache, setTextureCache] = useState<{ [url: string]: THREE.Texture }>({});
  const loaderRef = useRef(new THREE.TextureLoader());
  const initialPositions = useRef<Map<THREE.Object3D, THREE.Vector3>>(new Map());
  const explodeDirections = useRef<Map<THREE.Object3D, THREE.Vector3>>(new Map());

  const [pulse, setPulse] = useState(0);
  const [internalExplodeFactor, setInternalExplodeFactor] = useState(0);

  const [renderedHotspots, setRenderedHotspots] = useState<{id: string, name: string, pos: THREE.Vector3, desc: string}[]>([]);

  useFrame((state) => {
    setPulse(Math.sin(state.clock.elapsedTime * 6) * 0.5 + 0.5);
    const target = settings.isExploded ? 1.0 : 0.0;
    const nextFactor = THREE.MathUtils.lerp(internalExplodeFactor, target, 0.05);
    setInternalExplodeFactor(nextFactor);

    fbx.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const original = initialPositions.current.get(child);
        const direction = explodeDirections.current.get(child);
        if (original && direction) {
          const magnitude = nextFactor * 25; 
          child.position.set(
            original.x + direction.x * magnitude,
            original.y + direction.y * magnitude,
            original.z + direction.z * magnitude
          );
        }
      }
    });

    const updated: {id: string, name: string, pos: THREE.Vector3, desc: string}[] = [];
    settings.customHotspots.forEach(hs => {
      const mesh = fbx.getObjectByName(hs.meshName) as THREE.Mesh;
      if (mesh) {
        const wp = hs.localPosition.clone();
        mesh.localToWorld(wp);
        updated.push({ id: hs.id, name: hs.label, pos: wp, desc: hs.description });
      }
    });
    setRenderedHotspots(updated);
  });

  useEffect(() => {
    const mapsToLoad: { url: string; isColor: boolean }[] = [];
    const addUrl = (u: any, isColor = false) => { if (u && typeof u === 'string') mapsToLoad.push({ url: u, isColor }); };
    Object.values(settings.materialMappings).forEach(u => addUrl(u, true));
    Object.values(settings.normalMappings).forEach(u => addUrl(u, false));
    Object.values(settings.metalMappings).forEach(u => addUrl(u, false));
    Object.values(settings.roughMappings).forEach(u => addUrl(u, false));
    Object.values(settings.alphaMappings).forEach(u => addUrl(u, false));
    mapsToLoad.forEach(({ url: u, isColor }) => {
      if (!textureCache[u]) {
        loaderRef.current.load(u, (tex) => {
          tex.colorSpace = isColor ? THREE.SRGBColorSpace : THREE.NoColorSpace;
          tex.needsUpdate = true;
          setTextureCache(prev => ({ ...prev, [u]: tex }));
        });
      }
    });
  }, [settings, textureCache]);

  const processedModel = useMemo(() => {
    fbx.position.set(0, 0, 0); fbx.rotation.set(0, 0, 0); fbx.scale.setScalar(1); fbx.updateMatrixWorld(true);
    const box = new THREE.Box3().setFromObject(fbx);
    const center = new THREE.Vector3(); box.getCenter(center);
    const size = new THREE.Vector3(); box.getSize(size);
    fbx.position.x = -center.x; fbx.position.y = -center.y; fbx.position.z = -center.z;
    fbx.updateMatrixWorld(true);
    const targetSize = 35; 
    const scaleFactor = targetSize / Math.max(size.x, size.y, size.z);
    fbx.scale.setScalar(scaleFactor); fbx.updateMatrixWorld(true);

    const materialNames: string[] = [];
    fbx.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;
        const mat = Array.isArray(mesh.material) ? mesh.material[0] : mesh.material;
        if (mat) {
          if (!mat.name) mat.name = `Part_${materialNames.length}`;
          if (!materialNames.includes(mat.name)) materialNames.push(mat.name);
        }
        initialPositions.current.set(child, child.position.clone());
        const worldPos = new THREE.Vector3();
        child.getWorldPosition(worldPos);
        explodeDirections.current.set(child, worldPos.normalize());
      }
    });
    if (onMaterialsLoaded) onMaterialsLoaded(materialNames);
    return fbx;
  }, [fbx, url]);

  const handlePointerDown = (e: ThreeEvent<PointerEvent>) => {
    if (!settings.isPlacementMode) return;
    e.stopPropagation();
    const { point, object } = e;
    const mesh = object as THREE.Mesh;
    const localPos = mesh.worldToLocal(point.clone());
    const newHotspot: CustomHotspot = {
      id: Math.random().toString(36).substr(2, 9),
      meshName: mesh.name,
      localPosition: localPos,
      label: mesh.name || `Point ${settings.customHotspots.length + 1}`,
      description: 'מייצר תיאור...'
    };
    onAddHotspot?.(newHotspot);
  };

  useEffect(() => {
    processedModel.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;
        const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
        const updatedMaterials = materials.map((mat) => {
          if (!mat.userData.pbr || mat.type !== 'MeshStandardMaterial') {
            const originalColor = (mat as any).color ? (mat as any).color.clone() : new THREE.Color(0xffffff);
            mat.userData.pbr = new THREE.MeshStandardMaterial({ name: mat.name, color: originalColor, side: THREE.DoubleSide });
            mat.userData.originalColor = originalColor;
          }
          const pbr = mat.userData.pbr as THREE.MeshStandardMaterial;
          pbr.map = (settings.materialMappings[mat.name] && textureCache[settings.materialMappings[mat.name]]) || null;
          pbr.normalMap = (settings.normalMappings[mat.name] && textureCache[settings.normalMappings[mat.name]]) || null;
          pbr.metalnessMap = (settings.metalMappings[mat.name] && textureCache[settings.metalMappings[mat.name]]) || (settings.metalnessUrl && textureCache[settings.metalnessUrl]) || null;
          pbr.roughnessMap = (settings.roughMappings[mat.name] && textureCache[settings.roughMappings[mat.name]]) || (settings.roughnessUrl && textureCache[settings.roughnessUrl]) || null;
          pbr.alphaMap = (settings.alphaMappings[mat.name] && textureCache[settings.alphaMappings[mat.name]]) || (settings.transparencyUrl && textureCache[settings.transparencyUrl]) || null;
          pbr.metalness = pbr.metalnessMap ? 1.0 : settings.metalness;
          pbr.roughness = pbr.roughnessMap ? 1.0 : settings.roughness;
          pbr.transparent = !!pbr.alphaMap || settings.opacity < 1.0;
          pbr.opacity = settings.opacity;
          const baseColor = settings.color === '#ffffff' ? mat.userData.originalColor : new THREE.Color(settings.color);
          pbr.color.copy(baseColor);
          if (settings.hoveredMaterial === mat.name) {
            pbr.emissive.setHex(0x6366f1); pbr.emissiveIntensity = pulse * 0.4;
          } else {
            pbr.emissive.setHex(0x000000); pbr.emissiveIntensity = 0;
          }
          pbr.needsUpdate = true;
          return pbr;
        });
        mesh.material = Array.isArray(mesh.material) ? updatedMaterials : updatedMaterials[0];
      }
    });
  }, [processedModel, settings, textureCache, pulse]);

  return (
    <group onPointerDown={handlePointerDown}>
      <primitive object={processedModel} />
      {settings.showHotspots && renderedHotspots.map((h) => (
        <Html key={h.id} position={h.pos} distanceFactor={40} zIndexRange={[10, 0]}>
          <div className="relative flex items-center justify-center">
            <button 
              onClick={(e) => { e.stopPropagation(); onHotspotClick?.(h.id, h.pos); }}
              className={`w-6 h-6 rounded-full bg-white/40 backdrop-blur-md border-2 border-white shadow-xl hover:scale-125 transition-all cursor-pointer pointer-events-auto flex items-center justify-center group ${settings.activeAnnotationId === h.id ? 'ring-4 ring-indigo-500/30 scale-110' : ''}`}
            >
               <div className="w-2.5 h-2.5 bg-indigo-600 rounded-full" />
            </button>
            {settings.activeAnnotationId === h.id && (
              <div className="absolute left-10 glass-panel rounded-3xl p-5 w-64 pointer-events-auto border-white/40 animate-in fade-in zoom-in-95 slide-in-from-left-4 shadow-2xl z-50">
                <div className="flex justify-between items-start mb-3">
                  <div className="flex flex-col">
                    <span className="text-[7px] font-black text-indigo-600 uppercase tracking-[0.2em] mb-0.5">Custom Marker</span>
                    <h4 className="text-[12px] font-bold text-zinc-900 truncate max-w-[140px]">{h.name}</h4>
                  </div>
                  <div className="flex gap-1">
                    <button onClick={(e) => { e.stopPropagation(); onRemoveHotspot?.(h.id); }} className="p-1.5 hover:bg-red-500/10 rounded-full text-zinc-400 hover:text-red-500 transition-all"><svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg></button>
                    <button onClick={(e) => { e.stopPropagation(); onHotspotClick?.('', new THREE.Vector3()); }} className="p-1.5 hover:bg-black/5 rounded-full text-zinc-400 hover:text-indigo-600 transition-all"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12" /></svg></button>
                  </div>
                </div>
                <p className={`text-[10px] text-zinc-500 leading-relaxed font-medium mb-3 ${h.desc.includes('מייצר') ? 'animate-pulse' : ''}`}>{h.desc}</p>
              </div>
            )}
          </div>
        </Html>
      ))}
    </group>
  );
};

