/**
 * Native Speech Fallback using Web Speech API
 */
const speakNative = (text: string) => {
  if (!('speechSynthesis' in window)) return;

  // Cancel any ongoing speech
  window.speechSynthesis.cancel();

  const utterance = new SpeechSynthesisUtterance(text);
  // Detect Hebrew text and set language accordingly
  const isHebrew = /[\u0590-\u05FF]/.test(text);
  utterance.lang = isHebrew ? 'he-IL' : 'en-US';
  utterance.rate = 1.0;
  utterance.pitch = 1.0;

  window.speechSynthesis.speak(utterance);
};

/**
 * Generates an AudioBuffer from text using Gemini TTS.
 */
export const generateAudioBuffer = async (text: string): Promise<AudioBuffer | null> => {
  try {
    const ctx = getAudioContext();
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Kore' },
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    if (base64Audio) {
      const audioData = decodeBase64(base64Audio);
      return await decodeAudioData(audioData, ctx, 24000, 1);
    }
  } catch (error: any) {
    // Check for quota exhaustion specifically
    if (error?.message?.includes('429') || error?.message?.includes('quota')) {
      console.warn("Gemini TTS Quota Exhausted. Falling back to native speech.");
    } else {
      console.error("TTS Generation Error:", error);
    }
  }
  return null;
};

/**
 * Plays a pre-generated AudioBuffer immediately.
 */
export const playAudioBuffer = async (buffer: AudioBuffer) => {
  const ctx = getAudioContext();
  if (ctx.state === 'suspended') {
    await ctx.resume();
  }
  const source = ctx.createBufferSource();
  source.buffer = buffer;
  source.connect(ctx.destination);
  source.start(0);
};

/**
 * Standard TTS logic with fallback.
 * Tries Gemini first, falls back to native browser speech if it fails or quota is met.
 */
export const speakText = async (text: string) => {
  const trimmedText = text.trim();
  if (!trimmedText) return;

  try {
    const buffer = await generateAudioBuffer(trimmedText);
    if (buffer) {
      await playAudioBuffer(buffer);
    } else {
      // If buffer generation returns null (quota/error), use native fallback
      speakNative(trimmedText);
    }
  } catch (e) {
    // Catch any unexpected errors and use native fallback
    speakNative(trimmedText);
  }
};

import React, { useState, Suspense, useCallback, useRef } from 'react';
import { Canvas, useFrame, useThree } from '@react-three/fiber';
import { OrbitControls, PerspectiveCamera, Environment, Float, Html } from '@react-three/drei';
import * as THREE from 'three';
import './types';
import FBXModel from './components/FBXModel';
import UIOverlay from './components/UIOverlay';
import Sidebar from './components/Sidebar';
import { MaterialSettings, SceneModelInstance, CustomHotspot } from './types';
